D.banter.forEach(line=>{
  if(line.who!=='나'||!/(^\s*\([\s\S]*\)\s*$)/.test(line.t)) return;
  line.who='sys';
  line.t=line.t.trim().slice(1,-1);
});
D.radioTexts.forEach(line=>{
  if(!/(^\s*\([\s\S]*\)\s*$)/.test(line.t)) return;
  line.narration=true;
  line.t=line.t.trim().slice(1,-1);
});

