D.gateMissingStatus = (state)=>{
  const fallback={pillar:'필수 기록',have:0,need:1,hint:'목표 메뉴에서 끝내지 못한 메인 스토리를 확인한다'};
  const liveState=typeof S!=='undefined'&&state===S;
  const missing=liveState&&typeof G!=='undefined'&&typeof G.seoulMissing==='function'
    ? G.seoulMissing() : fallback;
  const reasons={
    본편:'남산 정지 장치에 필요한 핵심 기록이 아직 없습니다.',
    관계:'함께 남산에 들어갈 동료들의 사정과 목적을 충분히 확인하지 않았습니다.',
    세계:'정지 명령을 각 지역에 전달할 연락망이 부족합니다.',
    진실:'현재 이송 명령이 잘못됐다고 입증할 자료가 부족합니다.',
    유산:'정지 권한을 여는 원본 기록과 물건이 부족합니다.',
    여정:'남산 진입에 필요한 여정 기록이 부족합니다.',
    '필수 기록':'남산 진입에 필요한 기록이 부족합니다.'
  };
  return {...missing,reason:reasons[missing.pillar]||reasons.여정};
};
