D.npcGreeting = (id, state={})=>{
  const npc=D.npcs[id];
  if(!npc) return '';
  if(!state.met) return npc.greet0;
  if(state.att>10) return npc.greetGood;
  if(state.att<-10) return npc.greetBad;
  return D.npcRepeatGreetings[id];
};

