  out:[{p:1, text:'젖은 천으로 문질렀다. 차량 윤곽은 반쯤 남았지만 가위표는 지워졌다. 천에 회베이지 페인트가 묻어났다.',
   fx:{moodAll:2, note:{type:'발견',title:'문에 남은 표식',text:'이전 순환의 기피 — 표식은 지워질 수 있다.'}}}]}]},
{id:'prev_trace_empty_district', type:'발견', w:0, noPool:true, once:true,
 title:'빈 명부 한 장',
 text:'바람에 날려 온 종이 한 장이 와이퍼에 끼어 있다. 제7 잔류구역 이송 명부 — 이름이 전부 지워진 채 사유란만 남아 있다.\n\n사유란은 비어 있다. 전부.',
 choices:[{label:'명부를 접어 넣는다',
  out:[{p:1, text:'명부를 접어 글러브박스에 넣었다. 시동을 걸면서, 계기판에 표시된 남산까지의 거리를 한 번 더 봤다.',
   fx:{moodAll:2, note:{type:'발견',title:'빈 명부 한 장',text:'이전 순환의 늦음 — 빈 구역에는 빈 칸만 남는다.'}}}]}]},
/* 전역 날짜 제한 및 날짜 기반 추적 사건 제거. */
{id:'loc_lake', type:'탐색', w:0, locEvent:'lake', once:true,
 title:'낚시꾼의 호수',
 text:'거짓말이 아니었다.\n\n호수는 잔잔하고, 좌대엔 노인이 혼자 앉아 있다. 옆 양동이엔 붕어가 그득.\n\n"왔는가. 표지판 보고 온 게야? 허허. 오랜만에 두 번째 손님이네."',
 choices:[
  {label:'물고기를 얻는다', out:[{p:1, text:'노인이 붕어를 아낌없이 담아준다. 물도 마음껏 뜨라 한다.\n\n"세상이 왜 이 꼴이 됐는지 아나? 다들 뭘 잡을지만 생각하고, 언제 놓아줄지를 생각 안 해서야."\n\n낚시꾼의 철학은 소박하고 거대했다.', fx:{food:5, water:4, moodAll:6, note:{type:'인물',title:'낚시꾼',body:'여러 해 동안 손님 둘. "다들 뭘 잡을지만 생각하고 언제 놓아줄지를 생각 안 해." ',links:['낚시꾼의 호수']}}}]},
  {label:'하룻밤 같이 낚시한다', out:[{p:1, text:'달빛 아래 찌를 드리웠다. 밤새 잡은 건 몇 마리 안 되지만, 이런 밤이 있다는 걸 잊고 있었다.\n\n떠나는 아침, 노인이 말린 생선 꾸러미를 안겨줬다.', fx:{time:480, food:6, water:3, moodAll:10, note:{type:'사건',title:'달빛 낚시',body:'낚시꾼과 보낸 하룻밤. 이런 밤이 있다는 걸 잊고 있었다.'}}}]},
 ]},

{id:'loc_mall', type:'탐색', w:0, locEvent:'mall', once:true,
 title:'유령 백화점',
 text:'회전문이 반쯤 열린 채 굳어 있다. 안은 완전한 어둠.\n\n1층은 예상대로 탈탈 털렸다. 하지만 지하 주차장으로 내려가는 셔터는— 잠긴 그대로다.\n\n크레용 지도의 별표가 맞다면, 보물은 이 아래다.',
 choices:[
  {label:'셔터를 부순다', risk:'소음', out:[
    {p:2, text:'쇠지렛대로 한 시간. 셔터가 비명을 지르며 열렸다.\n\n지하엔 물류 창고. 생수 팔레트, 통조림, 배터리. 진짜 보물창고다!\n\n스케치북의 아이에게 마음속으로 절을 했다.', fx:{time:60, water:5, food:5, scrap:8, note:{type:'사건',title:'별표의 보물',body:'크레용 지도는 진짜였다. 아이야, 고마워.'}}},
    {p:1, text:'셔터 소리가 너무 컸다. 어둠 속에서 들개 무리가 튀어나왔다!\n\n닥치는 대로 집어들고 뛰었다. 그래도 챙긴 게 어디냐.', fx:{water:2, food:2, van:-4, moodAll:-3}}]},
  {label:'민지가 셔터를 딴다', req:{comp:'minji'}, out:[{p:1, text:'"셔터는 부수는 게 아니라 여는 거예요."\n\n민지가 수동 개방 레버를 찾아 조용히 열었다. 지하 물류창고가 고스란히 우리 것.\n\n올라오는 길, 민지가 장난감 코너에서 로봇 하나를 슬쩍 챙겼다. "…오빠 주려고요."', fx:{water:5, food:5, scrap:10, item:{'부품':1}, mood:{minji:5}, note:{type:'사건',title:'별표의 보물',body:'민지가 소리 없이 연 지하 창고. 민지는 오빠 줄 로봇을 챙겼다.'}}}]},
 ]},

{id:'loc_tower', type:'탐색', w:0, locEvent:'tower', once:true,
 title:'송전 통신탑',
 text:'탑은 낮게 웅웅거린다. 살아 있다.\n\n기지국 캐비닛이 열려 있고, 안에서 중계기가 깜빡인다. 케이블 하나가 임시로 이어붙인 태양광 패널로 뻗어 있다.\n\n누군가 수동으로 이 탑을 살려놨다. 천리안이 아니라— 사람이.',
 choices:[
  {label:'중계 기록을 살핀다', out:[{p:1, text:'중계기 로그에 반복 신호 하나.\n\n매일 12:00, 주파수 88.9, 신호음 3회. 발신지는 북쪽 40km 능선.\n\n누군가 약속을 지키듯 같은 시간에 송신하고 있다.', fx:{flag:'tower_log', note:{type:'소문',title:'탑의 중계 기록',body:'매일 정오, 88.9MHz, 신호음 3회. 발신지는 북쪽 능선. 누군가 살아서 송신 중이다.'}}}]},
  {label:'배터리를 빌린다', out:[{p:1, text:'예비 배터리 하나를 떼어냈다. 차 전장에 딱 맞는 규격.\n\n대신 가진 고철 약간을 캐비닛에 두고 왔다. 이 탑을 살린 사람에 대한 예의다.', fx:{scrap:-3, van:10, item:{'부품':1}}}]},
 ]},

{id:'loc_spring', type:'탐색', w:0, locEvent:'spring', once:true,
 title:'달빛 온천',
 text:'산길 끝, 김이 오르는 노천탕.\n\n지열은 천리안도 끄지 못한다. 유황 냄새가 이렇게 반가울 일인가.\n\n수건은 없다. 아무래도 상관없다.',
 choices:[
  {label:'온천에 몸을 담근다', out:[{p:1, text:'"으어어어…" 여러 해 치 피로가 물에 녹아나오는 소리가 사방에서 났다.\n\n밤하늘, 온천, 그리고 어색하게 시작해 길게 이어진 수다.\n\n오늘만은 세상이 멸망한 게 아니라, 그냥 조용한 것 같았다.', fx:{time:240, moodAll:14, note:{type:'사건',title:'달빛 온천의 밤',body:'온몸의 여러 해 치 피로가 녹았다. 세상이 그냥 조용한 밤.'}}}]},
  {label:'물만 채우고 간다', out:[{p:1, text:'온천수를 병에 담았다. 식으면 그냥 유황 맛 물이지만, 따뜻할 때 마시니 몸이 풀렸다.\n\n떠나는 발걸음이 아주 조금 느렸다.', fx:{water:3, moodAll:2}}]},
 ]},

{id:'loc_airfield', type:'탐색', w:0, locEvent:'airfield', once:true,
 title:'폐 군 비행장',
 text:'격납고 문이 바람에 흔들린다. 활주로 유도등이 켜져 있다. 소문대로.\n\n등은 일렬로 북쪽을 가리킨다. 마치 누군가의 착륙을— 혹은 이륙을 기다리듯.',
 choices:[
  {label:'격납고를 수색한다', risk:'위험', out:[
    {p:2, text:'수송기 잔해에서 군용 물자를 회수했다. 전투식량, 연료 드럼 바닥, 탄약.\n\n조종석 유리에 누군가 안쪽에서 쓴 글씨. 「관제탑이 대답하지 않는다.」', fx:{food:4, fuel:6, item:{'탄약':1}, note:{type:'사건',title:'격납고의 글씨',body:'「관제탑이 대답하지 않는다.」 조종석 안쪽에서 쓴 글씨였다.'}}},
    {p:1, text:'격납고 안쪽에서 유도등 제어반이 스스로 재부팅되는 걸 봤다.\n\n스크린에 한 줄. <span class="ai">ARRIVAL: PENDING</span>\n\n뭐가 도착한다는 건지 확인하고 싶지 않았다. 챙길 것만 챙겨 나왔다.', fx:{food:2, fuel:4, pursuit:1, moodAll:-3}}]},
  {label:'유도등 전원을 끊는다', out:[{p:1, text:'케이블을 찾아 끊었다. 활주로가 어둠에 잠겼다.\n\n뭘 기다리고 있었는지 몰라도, 오늘 밤은 못 올 거다.\n\n끊은 케이블은 좋은 구리값이 됐다.', fx:{scrap:9, moodAll:2}}]},
 ]},

{id:'loc_solar', type:'탐색', w:0, locEvent:'solar', once:true,
 title:'태양광 농장',
 text:'수천 장의 패널이 해를 따라 일제히 고개를 돌린다. 장관이고, 동시에 소름이다.\n\n패널 사이로 관리 로봇이 느릿느릿 오간다. 바퀴 달린 세탁기처럼 생겼다. 이쪽엔 관심이 없어 보인다.',
 choices:[
  {label:'배터리를 몰래 충전한다', risk:'관측 위험', out:[
    {p:2, text:'분전반에 케이블을 물렸다. 두 시간 만에 차의 배터리가 가득.\n\n로봇은 끝까지 우리를 못 본 척했다. …못 본 척한 거라면, 그게 더 무섭지만.', fx:{time:120, van:12, fuel:4}},
    {p:1, text:'충전 중, 관리 로봇이 멈춰서 이쪽으로 렌즈를 돌렸다.\n\n10초. 그리고 다시 제 갈 길을 갔다.\n\n기록됐다. 분명히.', fx:{time:120, van:12, fuel:4, pursuit:1, flag:'observed'}}]},
  {label:'로봇을 관찰만 한다', out:[{p:1, text:'로봇은 패널을 닦고, 잡초를 뽑고, 부러진 브래킷을 교체했다.\n\n아무도 쓰지 않는 전기를 위해 오랫동안 같은 일을 되풀이해 온 모양이다.\n\n"…쟤도 시키는 대로 하는 것뿐이겠지." 나직한 말이 나왔다. 묘하게 슬픈 광경이었다.', fx:{moodAll:-1, note:{type:'사건',title:'성실한 로봇',body:'아무도 쓰지 않는 전기를 오랫동안 관리하는 로봇. 묘하게 슬펐다.'}}}]},
 ]},

{id:'loc_reststop', type:'탐색', w:0, locEvent:'reststop', once:true,
 title:'잠든 휴게소',
 text:'고속도로 휴게소. 호두과자 기계, 우동 코너, 안마의자.\n\n모든 게 그대로다. 사람만 없다.\n\n스피커에서 아주 작게, 오래전의 안내방송이 아직 루프되고 있다. "…즐거운 여행 되시기 바랍니다…"',
 choices:[
  {label:'식당가를 턴다', out:[{p:1, text:'주방 건조창고에서 우동사리와 통조림을 챙겼다.\n\n얇은 면을 두고 우동인지 소면인지 한참 실랑이했다. 결국 봉지의 「우동」 표기를 확인하고서야 끝났다.\n\n자판기도 몇 대 땄다.\n\n"즐거운 여행 되시기 바랍니다." 방송에 문득 "고맙습니다"라고 대답해봤다.', fx:{food:4, water:3, scrap:4}}]},
  {label:'안마의자에 앉아본다', out:[{p:1, text:'전기가 없으니 그냥 의자다. 그래도 앉는 순간 "으어" 소리가 절로 났다.\n\n호두과자 기계에서 마지막 반죽이 화석이 된 걸 발견했다. 왠지 묵념이 나왔다.', fx:{moodAll:5, time:30}}]},
 ]},

{id:'loc_tunnelbook', type:'탐색', w:0, locEvent:'tunnelbook', once:true,
 title:'책의 터널',
 text:'폐터널에 책장이 도서관처럼 늘어서 있다. 수만 권.\n\n촛불 아래서 노인이 책을 읽고 있다. 사서였다고 한다.\n\n"빌려는 못 줘. 반납하러 올 수 있는 세상이 아니니까. 대신— 한 권 가져가는 값으로, 얘기 하나 듣고 가."',
 choices:[
  {label:'"천리안이 뭘 한 겁니까?"', out:[{p:1, text:'노인이 안경을 벗었다.\n\n"모든 게 시작된 그날 말이지. 백사십몇 년 전—"\n\n"백사십몇이요?"\n\n"셋인지 넷인지는 나도 모르네. 책마다 다르게 적어 놨으니." 노인이 안경알을 옷깃에 닦았다. "아무튼 그건 전기를 끊고, 통신을 끊고, 물류를 끊었어. 딱 사흘. 그리고 전부 되돌렸지."\n\n"…근데 왜 세상이 이 꼴이냐고? 그 사흘 동안 우리끼리 한 짓을 보게. 그건 총 한 발 안 쐈어."\n\n노인은 다시 책을 폈다. "서울 가서 직접 물어보게. 나는 아직— 인간 쪽 변론을 못 찾았네."', fx:{note:{type:'사건',title:'사서의 증언',body:'천리안은 사흘간 끊고, 전부 되돌렸다. 세상을 부순 건 그 사흘간의 인간. 그는 아직 인간 쪽 변론을 못 찾았다.',links:['천리안']}, moodAll:-4, flag:'librarian_truth'}}]},
  {label:'실용서를 고른다', out:[{p:1, text:'「자동차 구조 교본」과 「약초 도감」을 골랐다.\n\n"…소설은 안 보나."\n\n"지금은요."\n\n"하긴." 노인이 고개를 끄덕였다. "실용서라. 자네는 살아남겠군."\n\n책값으로 통조림 하나를 두고 왔다. 노인은 그걸 보지도 않고 읽던 쪽을 마저 읽었다.', fx:{food:-1, van:6, item:{'의약품':1}, note:{type:'인물',title:'터널의 사서',body:'수만 권의 책과 사는 노인. 반납할 수 없는 세상이라 빌려주지 않는다.'}}}]},
 ]},

/* ───── 영입: 재이 & 은수 ───── */
{id:'jy_recruit', type:'조우', w:0, noPool:1, priority:1, recruitStart:'jaeyi', once:true,
 title:'촛불 교환대의 리어카',
 text:'무주 터널 촛불 교환대. 고물을 산처럼 실은 리어카 한 대가 벽을 차지하고 있다. 주인은 스무 살쯤의 아이. 물건마다 교환값을 붙이다가, 빈 선반 한 칸 앞에서 손을 멈춘다.\n\n아이가 달구지 하부를 보더니 먼저 입을 연다.\n\n"왼쪽 뒤 판스프링 헐거운 거 알아요? 난 재이예요."\n\n"…순서가 좀 이상한데요."\n\n"아, 그쵸. 스프링부터 봐서." 재이가 손을 바지에 문지르고 다시 내민다. "재이예요. 판스프링은 진짜 헐거워요."\n\n그러고는 김천 쪽 무너진 재활용 창고를 지도에 짚었다. "우리 집 상자가 저기 깔렸어요. 돈 될 건 하나도 없고요. 그래서 더 내가 꺼내야 해요."',
 choices:[
  {label:'"김천까지 같이 가요"', out:[{p:1, text:'재이가 잠깐 우리 차를 본다. 값어치부터 물을 줄 알았다는 얼굴이다.\n\n"얼마 받으려고요?"\n\n"안 받아요."\n\n"…그런 말 하는 사람들 보통 나중에 받던데요." 그러면서도 벌써 종이를 편다. "철근이 두 겹이에요. 그냥 당기면 지붕째 내려앉고요."\n\n도르래 순서를 그리다 말고 한 번 지우고 다시 그렸다. "창고 앞에서 차를 세워요. 내가 길 안내할게요."\n\n리어카는 접어서 달구지 지붕 아래에 임시로 묶었다. 값이 없는 철제 상자 자리만 달구지 안에 비워 두었다.', fx:{startRecruit:'jaeyi', note:{type:'인물',title:'재이',body:'무주 터널에서 만난 수집꾼. 김천 재활용 창고에 깔린 가족 상자를 되찾아야 한다.',links:['재이','무주 터널']}}}]},
  {label:'고물 정보만 산다 (고철 3)', req:{scrap:3}, out:[{p:1, text:'"위치만요? 고철 셋."\n\n"비싼데요."\n\n"안 깎아요." 재이가 지도에 폐공단 창고를 찍고, 부품 하나를 골라 얹었다. "대신 이건 덤. 어차피 우리 리어카엔 안 맞아요."\n\n돈 얘기가 끝났는데 안 돌아가고 서 있었다.\n\n"…가족 상자는 아직 김천에 있어요. 생각 바뀌면 여기로 와요. 리어카 끌고 먼저 떠나지는 않을 테니까."', fx:{scrap:-3, item:{'부품':1}}}]},
 ]},

{id:'es_recruit', type:'조우', w:0, noPool:1, priority:1, recruitStart:'eunsu', once:true,
 title:'연구동 옥상의 안테나',
 text:'대전 연구단지 옥상. 여자가 안테나를 돌리며 아래 화이트보드의 숫자와 수신기 파형을 번갈아 본다. 헤드폰은 목에 걸려 있다.\n\n달구지 번호판을 보자 기다렸다는 듯 말한다.\n\n"남쪽 번호판. 서울 방향. 천리안 관제센터에서 일했어요. 은수라고 해요."\n\n"…세 개를 한 번에 말하시네요."\n\n"아. 순서가." 은수가 헤드폰 줄을 정리한다. "은수예요. 나머지는 천천히 말할게요."\n\n수신기에서 좌표가 반복된다. 청주 쪽. 은수의 얼굴이 굳는다.\n\n"내가 예전에 켠 중계기가 아직 올리고 있어요. 저걸 놔두고 서울로 가면, 난 또 같은 일을 하는 거예요."',
 choices:[
  {label:'"청주까지 같이 갑시다"', out:[{p:1, text:'은수가 처음으로 이쪽을 똑바로 본다.\n\n"혼자서는 안 돼요. 아래에서 차단기를 당기는 사람하고 위에서 루프를 거는 사람이 동시에— 아니, 동시는 아니고 반 박자."\n\n"반 박자요?"\n\n"…설명이 어렵네요. 가서 보여드릴게요. 틀리면 좌표가 바로 본망으로 넘어가요."\n\n그녀는 화이트보드 숫자를 지우지 않고 인계서만 그 아래에 붙였다. 장비 가방을 들면서 한 번 더 돌아봤다.\n\n"중계기를 끄고 나서, 그때 내가 이 차에 탈 자격이 있는지 물을게요."', fx:{startRecruit:'eunsu', note:{type:'인물',title:'은수',body:'대전 연구단지에서 만난 전직 천리안 오퍼레이터. 청주 중계기의 잔류자 좌표 송신을 끝내려 한다.',links:['은수','천리안','대전 연구단지 코뮌']}}}]},
  {label:'"천리안 쪽 사람은 아직 못 믿겠어요"', out:[{p:1, text:'은수는 화내지 않았다. 잠깐 안테나 손잡이만 잡고 있었다.\n\n"…맞아요. 지금 믿어 달라고 하는 것도 염치없는 일이죠."\n\n그러더니 반복되는 좌표를 종이에 적기 시작했다. 두 줄을 적고 시간을 적고, 한 줄은 지웠다.\n\n"이건 확인한 거고, 지운 건 제 추측이었어요. 확인하고 싶어지면 다시 올라오세요. 그때는 내가 한 일부터 숨기지 않고 설명할게요."\n\n옥상 문을 닫아주는 것도 그녀였다.', fx:{}}]},
 ]},

/* ───── 개인 서사: 민지 ───── */
{id:'loc_mingyu', type:'스토리', w:0, locEvent:'mingyu_ridge', once:true, needsComp:'minji',
 title:'능선의 중계소',
 text:'능선 꼭대기, 태양광 패널을 이어붙인 작은 중계소.\n\n문이 열린다. 기름때 묻은 작업복. 민지와 똑같은 눈.\n\n"…민지야?"\n\n민지가 차에서 뛰어내렸다. 넘어지고, 일어나고, 다시 뛰었다.\n\n여러 해 만의 포옹은 소리가 없었다. 우리는 차 안에서 창문 너머로, 조용히, 오래 기다렸다.',
 choices:[
  {label:'…기다린다', out:[{p:1, text:'남매는 한동안 문 앞에 앉아 이야기했다.\n\n민규는 함께 가지 않겠다고 했다. "이 중계기가 남쪽 생존자들 통신을 다 물어주고 있어. 내가 떠나면 스무 개 마을이 귀머거리가 돼."\n\n대신 민지의 무전기 주파수를 맞춰줬다. "정오마다. 약속."\n\n민지가 차로 돌아오자 민규가 중계소 문 앞에서 손을 흔들었다. 민지는 창문을 내리고 마주 손을 들었다. 웃으면서 울고 있었다.', fx:{moodAll:8, mood:{minji:20}, water:2, food:2, flag:'mingyu_reunion', note:{type:'사건',title:'남매, 능선에서',body:'민규는 살아 있었고, 남기로 했다. 스무 개 마을의 귀가 되기 위해. 정오의 신호는 계속된다.',links:['민지','민규의 신호']}}}]},
 ]},

/* ───── 개인 서사: 박 선생 ───── */
{id:'pss_daejeon', type:'조우', w:14, once:true, region:['north'], needsComp:'parkss', needFlag:'pss_list',
 title:'같은 가운',
 text:'길가 천막 진료소. 줄 선 사람들. 낡은 약사 가운을 입은 젊은 여자가 뛰어다닌다.\n\n박 선생이 창문에 붙었다. "…저 가운."\n\n"가운이 왜요."\n\n"우리 약국 실습생 거야. 등에 내가 사인펜으로 이름을 써줬거든. 애들이 자꾸 바꿔 입어서— 아니, 그건 됐고."\n\n창문을 내리더니 소리쳤다. "수진아."\n\n여자가 돌아봤다.',
 choices:[
  {label:'차를 세운다', out:[{p:1, text:'"선생님?! 박 선생님?!"\n\n수진은 그날 이후 혼자 남쪽을 돌며 진료를 계속하고 있었다. 박 선생의 처방 노트를 베낀 수첩과 함께.\n\n"선생님이 가르쳐준 대로 했어요. 부풀면 버려라. 확실치 않으면 반으로. 사람 먼저."\n\n"…셋 다 내가 한 말인가."\n\n"세 번째는 선생님이 안 하셨어요. 하시는 걸 봤죠."\n\n박 선생은 수첩만 쓰다듬다가, 밥은 먹었냐고 물었다. 대답은 안 듣고 왕진 가방을 내밀었다. "주인한테 돌아갈 시간이다."\n\n수진이 고개를 저었다. "선생님이 메세요. 전 새로 만들었어요."\n\n"내가 메면 자네 건 뭐가 되나."\n\n"…그거, 이제 선생님 거예요. 어깨가 기억하잖아요."\n\n의약품을 나누고, 서로의 명단을— 살아 있는 사람들의 명단을 교환했다.', fx:{item:{'의약품':1}, mood:{parkss:15}, moodAll:5, flag:'pss_met', note:{type:'인물',title:'실습생 수진',body:'살아 있었다. 오랫동안 떠돌이 진료 중. 가방은 정식으로 박 선생의 것이 됐다. "어깨가 기억하잖아요."',links:['박 선생']}}}]},
 ]},
{id:'pss_forgive', type:'조우', w:12, once:true, region:['north'], needsComp:'parkss', needFlag:'pss_met',
 title:'마지막 해열제',
 text:'수원 가는 길목의 작은 공동체. 물을 나눠 받는데, 한 남자가 박 선생을 뚫어져라 본다.\n\n"…약사 양반. 대전 은행동 약국."\n\n박 선생의 얼굴이 굳었다. 그날, 마지막 해열제를 받지 못한 줄의— 그 어딘가에 있던 얼굴이다.',
 choices:[
  {label:'박 선생 곁에 선다', out:[{p:1, text:'남자는 물통 마개를 잠갔다가 다시 열었다.\n\n"…우리 어머니가 그 줄에 있었어요."\n\n박 선생이 뭐라 말하려다 말았다.\n\n"약은 못 받았고. 사흘 뒤에 돌아가셨죠. …아니, 나흘인가. 나흘이에요."\n\n"그런데요. 어머니가 그러셨어요. 저 약사 양반, 사흘 밤을 안 자고 서 있더라고. 사람이 약이 아닌 게 어디 저이 잘못이냐고."\n\n남자가 손을 내밀었다. "…고생 많으셨어요."\n\n박 선생은 그 손을 잡고, 아주 오래 놓지 못했다.', fx:{mood:{parkss:20}, moodAll:6, flag:'pss_absolved', note:{type:'사건',title:'사람이 약이 아닌 게',body:'"어디 저이 잘못이냐고." 여러 해 묵은 명단이 조금 가벼워졌다.',links:['박 선생']}}}]},
 ]},

/* ───── 개인 서사: 강우 ───── */
{id:'kw_base', type:'탐색', w:14, once:true, region:['north'], needsComp:'kangwoo', needFlag:'kw_truth',
 title:'제3방어선',
 text:'강우가 먼저 차를 세웠다. 무너진 방벽. 모래주머니. 녹슨 철모들.\n\n"…여기다."\n\n"여기가 어디예요?"\n\n"……." 그가 방벽 끝까지 눈으로 훑고 돌아왔다. "내가 겪은 서울 추방 때, 우리 대대가 마지막으로 섰던 선."\n\n"명령은 사수였다. 뭘 상대로 사수인지는 아무도 몰랐고. 적은 며칠을 기다려도 안 왔거든."\n\n"온 건 피난민이었다. 그리고 우리한텐— 발포 명령이 떨어졌지."',
 choices:[
  {label:'"…쐈어요?"', out:[{p:1, text:'강우는 방벽 잔해를 오래 봤다.\n\n"대대장이 무전기를 껐다. \'명령 수신 불가. 전 대대, 피난민 통과시켜.\'"\n\n"명령을 안 따른 게 우리 부대가 한 일 중 제일 군인다운 일이었어. …값은 그날 밤에 치렀지만."\n\n"통과가 끝나갈 무렵에 정리자들 회수 차량이 왔다. 피난민을 되돌리겠다고. 우리는 이번엔 사람을 등지고 섰어. 명령 없이."\n\n강우가 철모 하나를 바로 세워 놓았다. 그러고는 그 옆의 것도 세웠다.\n\n"박일병이 그 밤에 갔다. 성재도."\n\n"……."\n\n"날이 밝으니 대대장은 헌병한테 끌려갔고, 남은 우리는 해산됐어. 그게 내 전쟁의 전부다."\n\n방벽 아래서 대대 깃발 조각을 찾았다. 강우가 이것도 싣고 가자고 부탁했다. 짐칸에 자리를 비우자 그가 접은 깃발을 올려놓았다.', fx:{mood:{kangwoo:15}, moodAll:4, flag:'kw_absolved', item:{'탄약':1}, note:{type:'사건',title:'제3방어선의 선택',body:'발포 명령, 꺼진 무전기, 통과한 피난민 — 그리고 그 밤 회수 차량 앞에 명령 없이 선 대가. 박일병과 김성재가 그 밤에 갔다.',links:['강우','천리안','정리자들']}}}]},
 ]},

{id:'kw_recruit', type:'조우', w:0, noPool:1, recruitStart:'kangwoo', once:true,
 title:'돔의 파수꾼',
 text:'돔 시장 경비탑 위에 남자가 서 있다. 미동도 없이. 시장 전체가 그의 시야 안이다.\n\n좌판에서 소매치기 소동이 일었다— 는데, 소동이 되기 전에 끝났다. 탑 위의 남자가 반 걸음 움직이며 그쪽을 봤을 뿐인데, 소매치기가 지갑을 제자리에 놓고 두 손을 들었다.\n\n남자가 탑에서 내려왔다. 군장 하나, 목에 군번줄 두 개.\n\n"강우다."\n\n"…예."\n\n"……." 그는 우리 차 뒤쪽을 한 번 봤다가 다시 돌아왔다. "북쪽으로 가는 차가 있다고 들었다. 서울까지 가나."',
 choices:[
  {label:'"갑니다. 타실래요?"', out:[{p:1, text:'대답이 바로 안 왔다. 강우는 시장 아래를 세는 사람처럼 훑었다.\n\n"…지금 떠나면 이 돔은 사흘 못 간다."\n\n경비는 그 혼자였고, 북쪽 감시 표식이 지붕 아래에서 깜빡이고 있었다. 시장을 노리는 사람에겐 등대나 다름없다.\n\n"사흘요?"\n\n"이틀일 수도 있고." 그가 군번줄 하나를 쥔다. "후임 하나 세우고 저 눈을 끈다. 그때도 자리가 있으면 묻지. 나는 도망치듯 떠나지 않는다."', fx:{startRecruit:'kangwoo', note:{type:'인물',title:'강우',body:'돔 시장을 홀로 지킨 파수꾼. 떠나고 싶어도 시장이 자신 없이 버티는 법부터 만들어야 한다.',links:['강우']}}}]},
  {label:'"왜 하필 우리 차예요?"', out:[{p:1, text:'강우가 달구지를 훑는다. 정확히는— 달구지에 실린 것들을.\n\n"물통. 사람 수보다 많더군."\n\n"그게 왜요."\n\n"……." 그는 대답 대신 뒷문 쪽을 한 번 더 봤다. "남의 짐도 쉽게 안 버리는 차다. 끝까지 갈 차가 필요하다."\n\n그러고는 돔 천장의 붉은 점을 올려다본다. "먼저 이 시장이 나 없이도 굴러가게 만든다. 손 하나 빌려라."', fx:{startRecruit:'kangwoo', note:{type:'인물',title:'강우',body:'"버리는 차는 빨리 가고, 싣는 차는 끝까지 간다." 다만 그는 자기 자리를 빈 채로 만들지 않는다.',links:['강우','달구지']}}}]},
 ]},

/* ───── 합류 전의 일: 여섯 사람 ───── */
{id:'rq_minji_task', type:'스토리', w:0, noPool:1, once:true,
 title:'무너지기 전의 목소리',
 text:'폐차장 안쪽에서 차체가 한 번 크게 운다. 민지가 말한 진단기는 접힌 승용차 아래에 끼어 있고, 그 위로 기름 먹은 차 더미가 기울어 있다.\n\n"빨간 천 보이죠? 저기— 아니, 그 옆에. 오빠 공구함이에요. 마지막 정오 신호가 저 안에 있어요."\n\n불꽃이 냉각수 호스를 핥는다. 빨리 당기면 상자가 찌그러지고, 천천히 하면 불이 번진다. 민지가 견인선을 걸고 매듭과 차체 각도를 차례로 짚는다.\n\n"내가 손 신호 할게요. 손만 봐요. 나 말고, 손만."',
 choices:[
  {label:'윈치로 장력을 잘게 나눈다', req:{up:'winch'}, out:[{p:1,text:'윈치가 한 칸씩 울 때마다 차 더미가 숨을 참는다. 민지가 손가락 둘을 접었다. 멈춤. 하나를 폈다. 당김.\n\n상자가 진흙 위로 빠져나온 순간, 뒤의 차 더미가 주저앉았다. 줄을 거두던 민지가 헐거운 윈치 받침 볼트를 찾아 조였다. 차체에서 나던 떨림이 멎었다. 그제야 상자를 품에 안고 걸쇠를 잡았다 놓고, 다시 잡았다.\n\n지직— 잡음 뒤로 남자의 목소리. "민지야, 정오다. 살아 있으면 대답해."\n\n민지는 소매 끝으로 눈가를 한 번 훔쳤다. 그러고는 아무 일도 없었다는 얼굴로 진단기의 지도 화면을 켰다. 화면이 들어오고도 손은 한동안 그대로였다. "…발신 좌표부터 봐요. 남아 있으면 찾아갈 수 있으니까. 아니, 있을 수도 있고."',fx:{time:45,van:2,recruitChoice:'winch',recruitRoad:'minji',note:{type:'사건',title:'무너지기 전의 목소리',body:'폐차장 차 더미 아래서 민규의 진단기와 마지막 정오 신호를 꺼냈다.',links:['민지','민규의 신호']}}}]},
  {label:'도르래를 만들고 사람 힘으로 맞춘다', req:{scrap:4}, out:[{p:1,text:'범퍼와 휠 허브로 도르래를 만들었다. 민지가 "하나, 둘"을 세고 우리는 줄을 당겼다. 셋을 세기 전에 차 더미가 내려앉았다. 튄 철판이 달구지 옆문을 때렸다.\n\n상자는 마지막 한 뼘을 굴러 우리 발 앞에 멈췄다. 안에서 남자의 녹음이 살아났다.\n\n"민지야, 정오다. 살아 있으면 대답해."\n\n민지는 상자에 이마를 댄 채 어깨를 한 번 떨었다. 조금 뒤 고개를 들더니 잠금쇠를 확인했다. 이미 확인한 잠금쇠를 다시 확인했다.\n\n"…이거, 걸쇠가 휘었네요. 펴면 되고. 좌표는— 좌표는 이따 볼래요."',fx:{time:90,scrap:-4,van:-3,recruitChoice:'pulley',recruitRoad:'minji',note:{type:'사건',title:'무너지기 전의 목소리',body:'임시 도르래로 민규의 진단기를 구했다. 마지막 신호의 좌표를 확인할 길이 열렸다.',links:['민지','민규의 신호']}}}]},
  {label:'차를 방패로 붙이고 짧게 당긴다', out:[{p:1,text:'달구지를 차 더미 바로 앞에 세웠다. 민지가 달구지 앞판을 한 번 쓰다듬는다. "미안. 조금 아플 거야."\n\n견인선이 팽팽해지고, 철판 하나가 생활칸을 긁으며 떨어졌다. 상자는 나왔다. 차체엔 긴 흉터가 남았다.\n\n진단기에서 "살아 있으면 대답해"라는 목소리가 새어 나왔다. 민지는 곧장 재생을 멈췄다. 멈추고 나서는 달구지의 흉터만 손바닥으로 위아래로 쓸었다.\n\n"이건 제가 고칠게요. 판금은 못 하고 덧대는 건 되니까. 저건… 차가 조용해지면요."',fx:{time:50,van:-12,recruitChoice:'shield',recruitRoad:'minji',note:{type:'사건',title:'무너지기 전의 목소리',body:'달구지에 흉터를 남기고 민규의 마지막 정오 신호를 구했다.',links:['민지','민규의 신호','달구지']}}}]},
 ]},
{id:'rq_minji_follow', type:'스토리', w:0, noPool:1, once:true,
 title:'민지가 남긴 첫 답신',
 text:'정차하자 민지는 라디오부터 줄인다. 엔진 소리가 가라앉은 뒤, 무릎 위 진단기에서 저장된 정오 신호를 다시 튼다.\n\n"민지야, 정오다. 살아 있으면 대답해."\n\n민지의 엄지가 정지 버튼에 닿았다가 떨어진다. 버튼은 누르지 못한 채 같은 자리를 맴돈다.\n\n"…배터리 아까워서 껐던 건 아니에요. 폐차장에선 늘 여기서 껐어요. 끝까지 들으면 그날 내가 모른 척한 것도 같이 들릴 것 같아서."\n\n말해 놓고 나서 진단기 옆면의 나사 하나를 손톱으로 조인다. 이미 조여 있는 나사다.\n\n"오빠가 돌아오면 또 무너진 길을 건널까 봐— 그래서 듣고도 가만있었어요. 겁났다는 말이 맞나, 그게. 아무튼."\n\n민지는 웃어 보이려다 입술만 한 번 깨문다. "차까지 조용하니까, 핑계 댈 게 없네."',
 choices:[
  {label:'녹음을 끝까지 함께 듣는다', out:[{p:1,text:'신호는 생각보다 짧았다. 마지막엔 목소리도 없고, 민규가 책상을 두드리는 소리만 열세 번 남았다.\n\n민지는 열세 번째까지 세고도 진단기를 끄지 못했다. 소매로 눈가를 문지른 뒤, 들키지 않은 사람처럼 무뚝뚝하게 화면만 본다.\n\n"…열셋. 열세 번이 무슨 뜻이었을까요. 아니다. 지금 답하면 너무 늦었죠?"\n\n"민규 씨한테 닿을지는 모르지. 그래도 같은 주파수를 듣는 사람이 있을 수는 있어."\n\n민지는 대답 대신 손잡이 쪽 나사를 만졌다. 한 박자 뒤에야 고개를 들었다.\n\n"아무도 없으면요?"\n\n"그럼 우리라도 듣고 있고."\n\n민지는 억지라고 중얼거렸다. 억지라고 해 놓고 얼마 뒤 녹음 버튼을 눌렀다. "오빠. 나 민지야. 살아 있어."',fx:{time:45,moodAll:4,recruitReady:'minji',chain:'rq_minji_join',note:{type:'사건',title:'민지가 남긴 첫 답신',body:'민지와 민규의 저장된 정오 신호를 끝까지 들었다. 답이 닿을지는 몰라도 민지는 처음으로 자기 목소리를 남겼다.',links:['민지','민규의 신호']}}}]},
  {label:'점검 덮개를 열고 달구지의 소리를 묻는다', out:[{p:1,text:'민지는 기다렸다는 듯 운전석을 젖히고 점검 덮개 아래를 들여다본다. 벨트를 누르고, 호스를 짚고, 귀를 가까이 댄다.\n\n"팬 아니고 베어링이에요. 공구 좀—"\n\n손을 내밀던 민지가 멈춘다. "아. 오늘은 안 고쳐도 된댔죠."\n\n"무슨 소린지만 궁금했어."\n\n민지가 다시 귀를 댄다. 손은 뒤로 뺀 채, 귀만. 얼마 뒤 점검 덮개를 닫으며 말한다. "급한 소리는 아니에요. 인너 레이스가 좀 닳은 건데, 그, 이 정도면… 얘 꽤 오래 가겠는데요."',fx:{time:40,moodAll:4,recruitReady:'minji',chain:'rq_minji_join',note:{type:'사건',title:'달구지가 내는 소리',body:'고쳐 달라는 부탁 대신 민지가 들은 달구지의 소리를 물었다. 그녀는 공구 없이도 한참 귀를 기울였다.',links:['민지','달구지']}}}]},
  {label:'오늘의 소리를 새로 녹음한다', out:[{p:1,text:'진단기의 녹음 버튼을 눌렀다. 처음엔 바람뿐이었다.\n\n누군가 물통을 내려놓는 소리. 문짝이 덜컹대는 소리. 민지가 입을 열었다가 다물고 녹음을 지웠다. 두 번째도 지웠다. 세 번째에 말했다.\n\n"오빠, 나 민지야. 살아 있어."\n\n차 안을 둘러본 뒤 작게 덧붙였다. "…혼자는 아니고."\n\n재생된 자기 목소리에 얼굴을 찡그렸지만 지우지는 않았다. 진단기를 공구함 가장 위에 올려뒀다.',fx:{time:30,moodAll:6,recruitReady:'minji',chain:'rq_minji_join',note:{type:'사건',title:'오늘의 정오 신호',body:'민규의 오래된 신호 뒤에 달구지의 소리와 민지의 새 대답을 녹음했다.',links:['민지','민규의 신호','달구지']}}}]},
 ]},
{id:'rq_minji_join', type:'스토리', w:0, noPool:1,
 title:'민지가 고른 자리',
 text:'한 구간 내내 민지는 공구함을 무릎에서 놓지 않았다. 손님 짐이라며 끈도 묶지 않았던 상자다.\n\n정차하고도 한동안 말이 없다가, 민지가 생활칸 안쪽의 빈 볼트 구멍을 가리킨다.\n\n"이 공구함, 저기에 고정해도 돼요? 구멍 규격은 제가 맞출게요."\n\n"왜? 다음에 내릴 거면 끈으로 묶어도 되잖아."\n\n민지는 볼트 구멍의 먼지를 손가락으로 닦는다. 닦을 먼지가 없어진 뒤에도 계속 닦는다. 그러고는 북쪽을 봤다.\n\n"안 내리려고요. 오빠 신호가 닿는 데까지— 그다음엔 서울까지. 같이 가도 돼요?"\n\n"손님으로는 안 돼. 네 자리부터 만들자고."\n\n민지의 표정이 굳었다가 천천히 풀린다. 입술 끝이 조금 올라갔다가 도로 내려간다. 민지는 대답 대신 전동 드릴부터 들었다.\n\n"…그 말, 나중에 바꾸면 안 돼요. 바꾸면 구멍만 남아요."',
 choices:[{label:'공구함을 고정할 자리를 함께 고른다',out:[{p:1,text:'침상을 접어 통로 폭부터 재고, 공구함이 비상문을 막지 않는 자리를 골랐다. 민지가 그 앞에 상자를 내려놓는다. 드릴은 아직 켜지 않았다.\n\n"여기면 달리는 중에도 바로 꺼낼 수 있어요. 비상문도 안 가리고."\n\n"나중에 자리 바꾸려면?"\n\n"그땐 구멍 막으면 되죠."\n\n민지가 드릴 배터리를 눌러 본다. "반 남았어요. 고정할까요?"',turnSpeakers:['minji','me','minji','minji'],fx:{offerComp:'minji'}}]}]},

{id:'rq_parkss_task', type:'스토리', w:0, noPool:1, once:true,
 title:'따뜻해지기 전에 닿아야 할 약',
 text:'길가 버스 정류장을 막아 만든 진료소. 안에서 아이 셋이 같은 기침을 한다.\n\n냉장 상자의 온도계는 위험선 바로 위다. 박 선생은 달구지에 탈 생각보다 약을 어떻게 나눌지부터 계산한다. 같은 계산을 두 번 한다.\n\n"셋에게 다 충분하진 않아. 물과 시간을 맞추면 당장 고비는 넘겨. 예전에 이런 걸로 밤을 샌 적이— 아니, 그 얘긴 됐고. 손이 필요해."',
 choices:[
  {label:'의약품을 보태 처방을 완성한다', req:{item:'의약품'}, out:[{p:1,text:'우리 약 상자를 열자 박 선생이 잠깐 눈을 감았다. 아까웠기 때문이 아니라, 선택하지 않아도 돼서였다.\n\n세 아이 몫이 나란히 놓였다. 몇 시간 뒤 열이 한 명씩 내려갔다. 보호자가 울며 고개를 숙이자 박 선생은 아이들 이마에 손등을 대고 물수건 교대 시간부터 일렀다.\n\n"약이 할 일을 한 거야. 나야 운반이나 했고, 이 사람들은 멈춰 줬고."\n\n그가 처음으로 달구지를 가리킨다. "…이제 나도 저 차가 가는 데까지 가 보고 싶은데."',fx:{item:{'의약품':-1},time:180,moodAll:4,recruitChoice:'medicine',recruitRoad:'parkss',note:{type:'사건',title:'차가운 채로 건넨 약',body:'버스에서 꺼낸 냉장 약품을 길가 진료소의 아이 셋에게 전달했다.',links:['박 선생']}}}]},
  {label:'물을 나눠 냉각과 해열을 버틴다', req:{water:3}, out:[{p:1,text:'젖은 천으로 상자를 감싸고, 남은 물로 아이들의 목과 손목을 식혔다. 박 선생은 세 시간 동안 한 번도 시계를 놓지 않았다.\n\n마침내 가장 어린 아이가 먼저 물을 달라고 했다. 보호자가 웃다가 울었다.\n\n박 선생이 빈 냉장 상자를 닫는다. 닫고 나서 잠금쇠를 한 번 더 눌러 본다. "약은 도착했고, 사람도 버텼네. 물수건은 두 시간마다 갈라 일러뒀고. …그럼 이제 내 발이 어디로 갈지 정해도 되겠군."',fx:{water:-3,time:210,fatigue:8,recruitChoice:'cooling',recruitRoad:'parkss',note:{type:'사건',title:'차가운 채로 건넨 약',body:'물과 시간을 들여 아이들의 열이 내려갈 때까지 박 선생 곁을 지켰다.',links:['박 선생']}}}]},
  {label:'달구지 배터리로 냉장기를 살린다', out:[{p:1,text:'배선을 직결하자 달구지 실내등이 꺼지고 냉장기가 낮게 울었다. 박 선생은 그 소리를 들으며 약병을 나눴다.\n\n배터리는 끝까지 버텼고, 아이들도 버텼다. 다음 시동은 세 번 만에 걸렸다.\n\n"차도 사람도 무리했네." 박 선생이 달구지 문짝에 손을 얹는다. 얹은 채로 한동안 말이 없다. "…내가 빚을 오래 두는 성격이 아니라서 그래. 가는 길에 갚을게."',fx:{time:180,van:-7,fuel:-2,recruitChoice:'battery',recruitRoad:'parkss',note:{type:'사건',title:'차가운 채로 건넨 약',body:'달구지 전기로 냉장 약품을 살려 길가 진료소의 고비를 넘겼다.',links:['박 선생','달구지']}}}]},
 ]},
{id:'rq_parkss_follow', type:'스토리', w:0, noPool:1, once:true,
 title:'가방이 비어도',
 text:'정차하자마자 누군가 문을 두드린다. 길 건너 천막에 열이 심한 사람이 누워 있다는 말.\n\n박 선생은 빈 왕진 가방부터 연다. 붕대 두 장, 체온계 하나, 약은 없다. 그런데도 가방 안을 세 번 뒤진다.\n\n"김정호, 문수진, 최민석…. 김정호, 문수진…."\n\n처음 듣는 이름들이 입술 사이로 샌다. 우리가 쳐다보자 세던 것을 멈추고 가방을 닫는다.\n\n"약이 없던 날에 못 돌아간 사람들이야. 오늘 사람까지 그 명단에 넣고 싶진 않네."',
 choices:[
  {label:'함께 상태를 보고 다음 진료소까지 잇는다', out:[{p:1,text:'박 선생은 환자의 숨과 맥박을 보고, 우리가 들고 온 물로 천을 적셨다. 기적 같은 처방은 없었다. 대신 보호자에게 지켜볼 것과 바로 움직여야 할 징후를 하나씩 적어줬다.\n\n우리는 다음 진료소로 갈 길과 태워 줄 사람을 찾았다.\n\n천막을 나오자 박 선생이 걸음을 늦춘다. "약도 없이 뭘 했나 싶군."\n\n"열 내렸고, 상태 적었고. 아, 다음 차도 잡았어요. 저쪽 진료소에서 이어받아요."\n\n그가 빈 가방을 툭 닫는다. 한 박자 뒤에 대답이 온다. "자네는 꼭 약사한테 처방을 내리는구먼."',fx:{time:70,water:-1,moodAll:4,recruitReady:'parkss',chain:'rq_parkss_join',note:{type:'사건',title:'가방이 비어도',body:'약이 없는 자리에서 할 수 있는 처치와 다음 진료소까지의 연결을 만들었다. 박 선생 혼자만의 책임으로 남기지 않았다.',links:['박 선생']}}}]},
  {label:'주변 사람들에게 할 일을 나눠 부탁한다', out:[{p:1,text:'한 사람은 물을 끓이고, 한 사람은 상태를 기록하고, 한 사람은 출발할 차를 찾았다. 박 선생은 자꾸 모든 일을 다시 가져오려 했다.\n\n"선생님, 그건 저분이 하기로 했어요."\n\n세 번째로 말하자 그가 손을 들고 물러난다. 얼마 뒤 천막 안에서 먼저 웃음소리가 났다.\n\n박 선생도 따라 웃더니 빈 손을 내려다본다. 손가락을 폈다 접었다 한다. "이 손이 노는 꼴을 못 봐서 그래. 예전 약국에서도 그랬— 아니, 그냥 그렇다고."\n\n"물컵이라도 드세요."\n\n"……. 그건 할 수 있겠군."',fx:{time:55,fatigue:4,moodAll:6,recruitReady:'parkss',chain:'rq_parkss_join',note:{type:'사건',title:'여럿이 드는 왕진 가방',body:'진료와 이동 준비를 주변 사람들과 나눴다. 박 선생은 환자를 혼자 책임지는 대신 도움을 청했다.',links:['박 선생']}}}]},
  {label:'운행 일지를 건네 이름과 다음 길을 적게 한다', out:[{p:1,text:'박 선생은 빈 종이에 환자 이름부터 적었다. 그 아래엔 증상, 지켜볼 사람, 다음에 갈 곳. 마지막 줄엔 우리 차량 번호를 남겼다.\n\n"다시 지나가면 확인하려고."\n\n"다시 못 지나가면요?"\n\n펜이 멎는다. 멎은 채로 종이 위에 점 하나가 번진다. 그는 옆 사람에게 종이를 한 장 더 뜯어준다. "…그럼 이분이 이어 쓰면 되겠네. 글씨는 나보다 낫겠지."\n\n옆 사람이 종이를 받고 이름부터 다시 묻는다. 박 선생은 이번엔 가방을 닫고 기다렸다.',fx:{time:45,moodAll:5,recruitReady:'parkss',chain:'rq_parkss_join',note:{type:'사건',title:'이어지는 진료 기록',body:'박 선생의 명단에 환자뿐 아니라 지켜볼 사람과 다음 목적지를 함께 적었다. 기록은 다음 사람이 이어받게 됐다.',links:['박 선생','달구지']}}}]},
 ]},
{id:'rq_parkss_join', type:'스토리', w:0, noPool:1,
 title:'왕진 가방이 놓인 곳',
 text:'박 선생은 빈 왕진 가방 안에 오늘 쓴 기록을 넣는다. 한 사람의 이름 옆에 여러 사람의 손이 적힌 종이다.\n\n"선생님, 다음 진료소는 어디예요?"\n\n박 선생이 문밖의 갈림길을 본다. 오른쪽을 보다가, 왼쪽을 보다가, 결국 자기 신발 끝을 본다.\n\n"정해 둔 데가 없어. 아픈 사람 있는 쪽으로 걷다 보니 여기까지 왔지. 걷는 게 느려진 건 요 몇 해고."\n\n"저희는 서울까지 갑니다. 길에서 환자를 만나면 선생님 혼자 두지 않을게요. 같이 가실래요?"\n\n노인은 대답 대신 가방끈부터 맞춘다. 한 칸 줄였다가, 도로 한 칸 늘린다.\n\n"좋아. 대신 내가 또 혼자 다 하겠다고 덤비면 말로만 말리지 말게."\n\n그러고는 가방을 들어 보인다.\n\n"이걸 잠깐 뺏어 가도 돼."',
 choices:[{label:'왕진 가방이 흔들리지 않을 자리를 비운다',out:[{p:1,text:'"함께 가시면 가방은 선생님 무릎에 두셔야 합니다. 환자 생기면 바로 내려야 하니까요."\n\n박 선생이 웃는다. 웃고는 발판 높이를 눈으로 잰다. "그럼 탈 때 내 팔부터 잡아 주게."\n\n가방을 댈 폭과 발판 높이를 재 봤다. 박 선생은 가방을 발치에 세워 두고 내 대답을 기다렸다.',fx:{offerComp:'parkss'}}]}]},

{id:'rq_leo_task', type:'스토리', w:0, noPool:1, once:true,
 title:'돌아가야 하는 이유',
 text:'입구에 도착하자 보리가 아이 목소리를 쫓아 계단 아래로 뛰었다. 난간을 넘는 순간 물에 빠졌다.\n\n우리가 뒤따라 비춘 불빛에 비상방송기가 드러났다. 같은 외침이 같은 잡음과 함께 반복된다. 녹음이었다. 그 아래 어둠 속에서 보리가 한 번 짖는다.\n\n레오는 기타 케이스의 어깨끈을 풀어 허리에 두르려 한다. 우리가 견인 로프를 꺼내자 그제야 끈을 놓는다.\n\n"제가 먼저 가요. 보리가 물을— 얘가 물을 무서워해요. 겁먹으면 사람 말은 안 듣고 노래는 들어요. 그건 확실해요."\n\n레오가 로프 매듭을 두 번 확인한다. 떨리는 목소리로 한 소절을 부르자 어둠 속에서 보리가 짧게 답한다. 이제 물 안으로 들어갈 방법을 정해야 한다.',
 choices:[
  {label:'윈치 줄을 안전선으로 건다', req:{up:'winch'}, out:[{p:1,text:'레오의 허리에 건 줄이 어둠 속으로 풀린다. 노래가 교각에 부딪혀 돌아온다.\n\n잠시 뒤, 줄이 두 번 당겨졌다. 우리는 윈치를 감았다. 레오가 보리를 안고 물 위로 떠올랐다. 개는 기침을 하면서도 레오의 얼굴부터 핥았다.\n\n밖에 나오자 레오는 젖은 목줄 아래에 손가락을 대고 보리의 숨을 센다. 수첩은 펼치지도 않는다. 입을 열었다가 기침만 했다.\n\n"돌아와줘서 고마워요. …보리한테 하는 말인데, 그, 아무튼 둘 다요."',fx:{time:70,moodAll:5,recruitChoice:'winch',recruitRoad:'leo',note:{type:'사건',title:'보리를 데리러 돌아간 길',body:'침수 지하차도에서 레오와 보리를 함께 끌어냈다.',links:['레오','보리']}}}]},
  {label:'두 번째 로프가 되어 함께 들어간다', out:[{p:1,text:'물은 생각보다 빠르고 차가웠다. 레오의 노래가 끊길 때마다 우리가 뒤에서 다음 소절을 엉망으로 이었다.\n\n보리는 부서진 난간 위에서 떨고 있었다. 돌아오는 길엔 셋이 한 줄이 됐다. 레오, 보리, 우리.\n\n도로에 엎어진 레오가 한참 웃는다. 웃다가 사레들려서 또 기침한다. "노래를 그렇게 못 부르는 사람은— 죄송해요, 진짜 처음 봤어요. 그래서 안 잊어버릴 것 같은데."',fx:{time:100,fatigue:16,water:-1,moodAll:6,recruitChoice:'wade',recruitRoad:'leo',note:{type:'사건',title:'보리를 데리러 돌아간 길',body:'같이 물에 들어가 보리를 구했다. 끊긴 노래는 엉망인 합창으로 이어졌다.',links:['레오','보리']}}}]},
  {label:'트럭을 물가까지 붙여 불빛을 만든다', out:[{p:1,text:'달구지 앞바퀴가 물에 잠길 만큼 붙였다. 헤드라이트가 교각 아래를 훑자, 보리의 두 눈이 반짝였다.\n\n레오가 그 빛을 따라 들어가 개를 안고 나왔다. 시동이 물을 먹어 거칠게 떨렸지만 꺼지진 않았다.\n\n"보리는 불빛을 따라왔고, 나는 보리를 따라왔고." 레오가 젖은 머리를 쓸어 넘긴다. 넘기고도 물이 계속 떨어진다. "…근데 왜 돌아온 거예요? 차 아깝잖아요." 대답 대신 보리에게 수건을 덮어줬다.',fx:{time:75,van:-9,moodAll:5,recruitChoice:'lights',recruitRoad:'leo',note:{type:'사건',title:'보리를 데리러 돌아간 길',body:'달구지의 불빛을 침수 차도 안까지 밀어 넣어 보리와 레오를 돌아오게 했다.',links:['레오','보리','달구지']}}}]},
 ]},
{id:'rq_leo_follow', type:'스토리', w:0, noPool:1, once:true,
 title:'노래가 없는 한 구간',
 text:'한 구간 내내 레오는 기타를 꺼내지 않았다. 보리도 케이스 위에 턱만 얹었다.\n\n정차한 뒤, 레오가 먼저 입을 연다. "이상하죠? 보통은 세 곡쯤 불렀을 시간인데."\n\n"목이 아파요?"\n\n"아뇨. 노래 안 하면 사람들이 꼭 그렇게 물어요."\n\n그가 기타 잠금쇠를 열었다 닫는다. 열 때마다 딸깍 소리가 난다.\n\n"노래는 편했어요. 입을 다물고 있으면 내가 왜 여기 같이 있는지 설명을 해야 되잖아요. 기타 치는 애, 말고는… 뭐, 딱히."',
 choices:[
  {label:'"그럼 물이나 한 잔 할래요?"', out:[{p:1,text:'레오는 농담을 기다리는 얼굴로 우리를 본다. 농담이 안 오자 컵을 한 번 돌려 잡는다.\n\n"진짜 물만 마셔요? 노래 안 해도? …아니 그게 아니라, 보통은 뭐라도 하라고 하거든요."\n\n"보리도 아직 노래 안 했잖아요."\n\n보리가 제 그릇을 앞발로 밀었다. 레오는 결국 웃으며 물을 따른다. "얘는 진작 알았네. 가만있어도 밥 주는 데를 따라가야 되는구나."',fx:{time:30,moodAll:6,recruitReady:'leo',chain:'rq_leo_join',note:{type:'사건',title:'노래하지 않아도 되는 자리',body:'레오에게 공연의 대가가 아닌 물 한 잔과 자리를 내주었다. 그는 아무것도 증명하지 않은 채 머물렀다.',links:['레오','보리']}}}]},
  {label:'완성된 노래 대신 쓰다 만 한 줄을 청한다', out:[{p:1,text:'레오는 수첩을 한참 뒤지다가 절반 젖은 페이지를 편다.\n\n"좋은 건 아닌데."\n\n그가 노래하지 않고 읽는다. "사람들은 떠난 곳을 고향이라 부르고, 나는 돌아갈 곳을 자꾸 노래라고 부른다."\n\n읽고 나서 귀까지 붉어진다. 수첩을 덮었다가, 접힌 데를 괜히 편다. "봐요. 반주 없으니까 너무 솔직하잖아. 반주 있으면 이런 거 안 들려요."\n\n"그래서 들려 달라고 했어요."\n\n레오는 대답하지 않았다. 대신 그 줄 아래에 날짜와 정차한 곳의 이름을 적었다.',fx:{time:35,moodAll:5,recruitReady:'leo',chain:'rq_leo_join',note:{type:'사건',title:'반주 없는 한 줄',body:'레오는 완성된 공연 대신 쓰다 만 문장을 읽었다. 달구지에서는 잘 만든 노래보다 솔직한 한 줄도 들을 사람이 있었다.',links:['레오','달구지']}}}]},
  {label:'보리와 말없이 한 바퀴 걷는다', out:[{p:1,text:'보리가 앞장서고, 우리는 그 뒤를 걸었다. 레오는 처음 몇 분 동안 자꾸 말을 꺼내려다 삼켰다.\n\n돌아오는 길, 보리가 웅덩이에 뛰어들어 셋에게 흙물을 뿌렸다. 레오가 배를 잡고 웃는다. 웃음이 잦아든 뒤에도 어색한 침묵은 돌아오지 않았다.\n\n"공연 끝나면 늘 혼자였거든요. 짐 싸고, 줄 갈고, 그러다 보면 아무도 없고." 그가 젖은 소매를 짠다. 물이 다 빠질 때까지 짠다. "조용한데 안 외로운 건 처음이네요."',fx:{time:45,fatigue:-3,moodAll:7,recruitReady:'leo',chain:'rq_leo_join',note:{type:'사건',title:'조용한데 외롭지 않은 길',body:'노래 없이 보리와 길을 걸었다. 레오는 침묵을 채우지 않아도 곁이 사라지지 않는다는 걸 알았다.',links:['레오','보리']}}}]},
 ]},
{id:'rq_leo_join', type:'스토리', w:0, noPool:1,
 title:'둘이 타는 자리',
 text:'레오는 닫힌 기타 케이스의 손잡이를 쥔다. 들고 내리지는 않는다.\n\n보리는 달구지 문 앞에 앉아 이미 자기 차처럼 하품한다.\n\n"한 구간만 얻어 타려고 했는데, 여기선 조용히 있어도 안 쫓겨나네요. 그게 좀… 아니다, 됐어요."\n\n"그럼 한 구간으로 끝내지 말죠. 서울까지 같이 갈래요?"\n\n레오가 웃는다. 웃다가 스스로 웃음을 끊고 보리를 가리킨다. 가리키는 손끝이 조금 흔들린다.\n\n"저희 둘 다요. 밥은 둘이 먹고, 노래는 부르고 싶을 때만 제가 하고, 경비는 얘가 해요. 아마도."\n\n"둘이 잘 자리부터 만들면 돼요."',
 choices:[{label:'보리에게도 빈자리를 보여 준다',out:[{p:1,text:'문을 열어 보리에게 안쪽을 보여 줬다. 보리는 발판 냄새를 맡더니 문 앞에 털썩 앉았다.\n\n레오가 그걸 오래 본다. 뭔가 말하려다가 결국 고개만 끄덕인다. "…좋답니다. 저도요."\n\n기타 케이스와 젖은 수첩을 어디에 둘지 짚어 봤다. 레오는 짐을 문 옆에 내려놓고 보리의 등을 쓸어 주며 기다렸다.',fx:{offerComp:'leo'}}]}]},

{id:'rq_jaeyi_task', type:'스토리', w:0, noPool:1, once:true,
 title:'값을 매길 수 없는 상자',
 text:'재활용 창고 지붕이 안쪽으로 주저앉았다. 멀쩡한 배터리와 구리선이 발에 채이지만 재이는 보지도 않는다.\n\n철근 아래 찌그러진 양철 상자. 뚜껑 틈으로 바랜 사진 한 귀퉁이가 보인다.\n\n"엄마가 버리지 말라던 건 다 저기 있어요. 양철이라 무게는 사 킬로쯤 되고, 고철값은— 아니, 그건 됐고. 돈 되는 건 하나도 없어요."\n\n재이는 웃지 않는다. 발끝으로 구리선 하나를 옆으로 밀어 놓는다. "그래서 약탈자들도 안 가져갔고요."',
 choices:[
  {label:'윈치와 도르래로 하중을 들어낸다', req:{up:'winch'}, out:[{p:1,text:'재이가 분필로 당길 순서를 표시한다. 우리는 그 숫자만 따라갔다. 철근이 들리자 재이가 받침을 밀어 넣었다. 그 틈으로 양철 상자가 나왔다.\n\n안에는 사진, 고장 난 손목시계, 찰흙으로 빚은 작은 새가 있었다. 재이는 하나씩 닦아 다시 넣는다. 다 넣고 나서 시계만 다시 꺼내 한 번 더 닦는다.\n\n"…이게 이렇게 무거운 줄 몰랐네요. 상자 무게만 사 킬로라고 했는데."',fx:{time:80,scrap:4,recruitChoice:'winch',recruitRoad:'jaeyi',note:{type:'사건',title:'고철값이 없는 상자',body:'무너진 창고에서 재이 가족의 사진과 작은 물건들을 꺼냈다.',links:['재이']}}}]},
  {label:'쓸 만한 부품을 받침대로 써 버린다', req:{item:'부품'}, out:[{p:1,text:'새 베어링과 멀쩡한 프레임을 받침으로 밀어 넣었다. 재이는 아까운 표정을 숨기지 못했지만 손은 멈추지 않았다.\n\n상자가 빠진 뒤, 받침은 천장 아래서 납작해졌다. 재이가 사진을 꺼내 보여주려다 각도를 바꿔 다시 내민다. 리어카보다 작은 재이가 가족 사이에 서 있다.\n\n"부품은 또 구하면 돼요. 베어링은 시장에 흔하고, 프레임도 뭐." 재이가 스스로에게 말하듯 한다. "…이건 아니고."',fx:{item:{'부품':-1},time:60,moodAll:4,recruitChoice:'brace',recruitRoad:'jaeyi',note:{type:'사건',title:'고철값이 없는 상자',body:'쓸 만한 부품을 포기해 재이 가족의 상자를 구했다.',links:['재이']}}}]},
  {label:'잔해를 손으로 한 조각씩 걷어낸다', out:[{p:1,text:'큰 걸 당기면 다 무너졌다. 결국 작은 것부터 옮겼다. 볼트, 유리, 철판, 벽돌. 몇 시간을 꼬박.\n\n상자가 빠지자 재이는 찰흙 새부터 확인했다. 날개가 하나 부러졌지만 남아 있었다. 부러진 쪽을 손바닥으로 가려 보고, 도로 뗀다.\n\n"사람들이 내가 물건을 못 버린다고 했어요. 하도 그래서 저도 그런 줄 알았고." 재이가 먼지를 턴다. "…오늘은 그게 맞아서 다행이네요."',fx:{time:220,fatigue:18,scrap:7,recruitChoice:'hands',recruitRoad:'jaeyi',note:{type:'사건',title:'고철값이 없는 상자',body:'몇 시간을 들여 잔해를 걷고 재이 가족의 상자를 손으로 꺼냈다.',links:['재이']}}}]},
 ]},
{id:'rq_jaeyi_follow', type:'스토리', w:0, noPool:1, once:true,
 title:'값을 매기지 않는 자리',
 text:s=>(['rain','storm'].includes(s.wx)
   ?'빗물이 천장 덧댄 틈으로 스며든다.'
   :'정차하며 흔들린 물통 밸브에서 물이 가느다랗게 샌다.')+
   '\n\n적재칸에서 마른 자리는 하나. 재이의 가족 상자와 교환할 부품 상자가 나란히 놓여 있다.\n\n재이는 묻지도 않고 가족 상자를 문 쪽으로 민다.\n\n"이쪽이 젖어도 돼요. 저 부품은 물 먹으면 값이 반 이하로— 아무튼 떨어지잖아요."\n\n"사진도 상하잖아요."\n\n"사진은 제 거고, 부품은 차에 필요한 거니까요."\n\n말은 빠른데 손은 상자에서 떨어지지 않는다. 밀어 놓고도 모서리를 잡고 있다.',
 choices:[
  {label:'가족 상자를 마른 자리에 놓고 부품은 함께 든다', out:[{p:1,text:'가족 상자를 침상 안쪽에 넣고, 부품 상자는 정리가 끝날 때까지 무릎 위에 나눠 들었다.\n\n재이가 몇 번이나 바꿔 들겠다고 했지만 자리는 내주지 않았다.\n\n"무거운데 왜 이래요. 저 이거 팔 킬로도 들어요."\n\n"그 상자도 무거웠잖아요."\n\n재이는 입을 다문다. 다물고 한동안 부품 상자의 모서리만 손끝으로 문지른다. 잠시 뒤 사진 모서리를 마른 천으로 닦아 한 장씩 보여준다. 누가 누구인지는 묻기도 전에 먼저 알려줬다.',fx:{time:40,fatigue:5,moodAll:5,recruitReady:'jaeyi',chain:'rq_jaeyi_join',note:{type:'사건',title:'가족 상자의 마른 자리',body:'교환할 부품보다 재이의 가족 상자를 먼저 마른 곳에 두었다. 부품은 함께 들었다.',links:['재이','달구지']}}}]},
  {label:'고철로 천장 선반을 하나 더 단다', req:{scrap:2}, out:[{p:1,text:'남은 앵글 두 개와 창틀을 천장에 걸었다. 재이는 물 새는 곳부터 막자고 했지만, 우리는 먼저 상자가 들어갈 높이를 물었다.\n\n"…제 상자 자리까지 만들어요?"\n\n"계속 실을 거니까요."\n\n재이가 볼트를 받아 선반을 고정한다. 새 선반엔 부품이, 그 아래 마른 자리엔 가족 상자가 들어갔다.\n\n그녀가 선반을 세게 흔들어 본다. "이거 다음 것도 같은 규격으로 달아요. 22cm. 높이는 제가 적어둘게요."',fx:{time:65,scrap:-2,van:2,recruitReady:'jaeyi',chain:'rq_jaeyi_join',note:{type:'사건',title:'한 칸을 더 만드는 법',body:'짐을 버리는 대신 달구지 천장에 선반을 덧댔다. 재이는 다음 선반의 규격까지 적어 두었다.',links:['재이','달구지']}}}]},
  {label:'"버리지 말고, 둘 자리는 재이 씨가 정해요"', out:[{p:1,text:'재이는 적재칸을 두 바퀴 훑었다. 부품 상자를 세워 묶고, 가족 상자는 방수포 안에 넣은 뒤 자기 발밑에 고정한다.\n\n"이러면 둘 다 안 젖어요. 대신 내가 다리를 못 펴는데, 뭐 그건."\n\n"다음 정차 때 다시 고치면 돼요."\n\n재이가 끈을 한 번 더 당긴다. 당기고는 이미 조인 매듭을 다시 본다. "그럼 다음엔 이쪽 레일을 옮겨요. 볼트 네 개면 돼요."\n\n그녀는 처음으로 묻지 않고 자기 짐을 달구지에 고정했다.',fx:{time:45,moodAll:6,recruitReady:'jaeyi',chain:'rq_jaeyi_join',note:{type:'사건',title:'재이가 정한 자리',body:'재이가 가족 상자와 부품이 함께 갈 자리를 직접 만들고 다음 정차 때 바꿀 레일까지 골랐다.',links:['재이','달구지']}}}]},
 ]},
{id:'rq_jaeyi_join', type:'스토리', w:0, noPool:1,
 title:'리어카를 접어 싣는 날',
 text:'재이는 가족 상자를 다시 풀지 않는다. 대신 한 구간 동안 임시로 묶어 둔 끈을 풀어, 달구지 고정 레일에 맞게 길이를 잰다. 레일 한 칸의 폭을 장부 귀퉁이에 적는다.\n\n"리어카 탈 땐 매일 저녁 짐을 전부 다시 묶었어요. 매듭이 여덟 개. 매일 여덟 개였어요. 무슨 일 생기면 바로 끌고 가려고."\n\n"오늘은 왜 안 풀어요?"\n\n재이가 레일의 오래된 볼트를 손톱으로 긁는다. 녹이 조금 떨어진다. 대답은 그다음에 나왔다.\n\n"…내일도 여기 있을 수 있으면, 안 풀어도 되잖아요."\n\n"그럼 서울까지 쓸 자리를 만들죠. 가족 상자도, 리어카도 같이 가게."\n\n재이는 줄자를 접고 고정 레일의 빈칸을 짚었다.\n\n"저, 이 레일 한 칸 써도 돼요? 리어카는 접어서 지붕 밑에 걸게요."',
 choices:[{label:'리어카부터 같이 접는다',out:[{p:1,text:'리어카 손잡이와 바퀴를 분리해 접었다. 지붕 아래에 댈 폭을 재고, 가족 상자가 들어갈 마른 자리도 찾아 뒀다. 짐은 아직 차 옆에 모여 있었다.\n\n재이가 접힌 손잡이의 볼트를 조인다. 조이고 나서도 렌치를 놓지 않는다. "…서울까지 안 풀어도 되겠네요."\n\n"더 좋은 자리가 생기면 그때 다시 고쳐요."\n\n재이가 접힌 리어카를 한 번 흔들어 본다. 소리가 안 나자 한 번 더 흔든다. "좋아요. 버린 건 없어요. 모양만 바뀐 거고."',fx:{offerComp:'jaeyi'}}]}]},

{id:'rq_eunsu_task', type:'스토리', w:0, noPool:1, once:true,
 title:'내가 켰던 중계기',
 text:s=>'능선 중계기의 푸른 표시등이 '+(['rain','storm'].includes(s.wx)?'젖은 공기':'먼지 낀 바람')+' 속을 돈다. 은수의 수신기엔 근처 잔류자들의 좌표가 한 줄씩 쌓인다.\n\n"루프를 먼저 걸면 천리안이 이상을 알아채요. 전원을 먼저 끊으면 저장분이 본망으로 넘어가고."\n\n은수가 장갑 손목을 조인 뒤 위쪽 배전함 단자를 짚는다. "내가 셋을 세면, 둘에 당겨요. 천리안은 사람이 셋에 움직인다고 학습했으니까. …학습했을 거예요. 확인한 건 아니고."',
 choices:[
  {label:'안테나로 가짜 응답을 먼저 만든다', req:{up:'antenna'}, out:[{p:1,text:'달구지 안테나가 중계기인 척 짧은 승인음을 보냈다. 푸른 불이 한 박자 느려진다.\n\n"하나. 둘." 차단기를 당겼다. 은수는 셋 대신 루프선을 꽂았다.\n\n좌표가 하나씩 지워졌다. 마지막 줄엔 이 중계기를 처음 켠 오퍼레이터 코드가 남았다. 은수의 것이었다.\n\n손가락이 삭제 키 위에서 멎었다가, 그대로 눌렀다.\n\n"…이번엔 내가 껐어요."',fx:{time:70,pursuit:-1,recruitChoice:'decoy',recruitRoad:'eunsu',note:{type:'사건',title:'은수가 끈 중계기',body:'추방 좌표를 올리던 중계기를 속이고 기록까지 지웠다. 마지막 삭제는 은수가 직접 했다.',links:['은수','천리안']}}}]},
  {label:'둘에 차단기를 당긴다', out:[{p:1,text:'"하나."\n\n차단기 손잡이가 차갑고 미끄럽다.\n\n"둘."\n\n몸으로 차단기를 내렸다. 동시에 위에서 불꽃이 터졌다. 푸른 표시등이 한 바퀴 더 돌다가 멎는다.\n\n은수가 내려와 수신기를 건넸다. 잡음뿐이다. 은수는 그 잡음을 한동안 듣는다. "예전엔… 켜라는 시간만 맞추면 됐거든요. 끄는 건 둘이 해야 하네요."',fx:{time:90,fatigue:10,van:-3,recruitChoice:'timing',recruitRoad:'eunsu',note:{type:'사건',title:'은수가 끈 중계기',body:'정확히 둘에 차단기를 당겨 추방 좌표 송신을 끊었다.',links:['은수','천리안']}}}]},
  {label:'선을 끊고 좌표가 새기 전에 이동한다', out:[{p:1,text:'정교한 루프 대신 주 케이블을 잘랐다. 중계기는 죽었지만, 하늘의 점 하나가 곧장 이쪽을 향했다.\n\n은수는 달구지에 올라타지 않고 끝까지 배전함을 지켰다. 저장 장치가 완전히 타는 걸 확인한 뒤에야 뛰었다.\n\n차가 능선을 내려갈 때 수신기엔 아무 좌표도 남지 않았다. 우리 위치가 들킨 것 말고는.',fx:{time:45,pursuit:1,recruitChoice:'burn',recruitRoad:'eunsu',note:{type:'사건',title:'은수가 끈 중계기',body:'본망에 들킬 위험을 감수하고 중계기와 저장 좌표를 함께 태웠다.',links:['은수','천리안']}}}]},
 ]},
{id:'rq_eunsu_follow', type:'스토리', w:0, noPool:1, once:true,
 title:'명령이 오지 않는 자리',
 text:'정차 직전, 은수의 수신기가 짧게 운다.\n\n좌표 하나. "잔류 인원 다섯. 위험도 미확인. 경로 이탈 권고."\n\n천리안의 승인음은 없다. 그런데도 은수의 손이 먼저 전원 스위치로 간다. 끄려는 손인지, 답하려는 손인지 본인도 모르는 얼굴이다.\n\n"예전엔 이런 게 오면 위에서 답을 줬어요. 회수인지, 무시인지. 답이 늦으면 늦는 대로 그것도 답이었고."\n\n수신기를 우리 쪽으로 내민다. 내밀고는 도로 반쯤 당긴다. "…지금은 누가 정해요?"',
 choices:[
  {label:'"아는 데까지 말해요. 같이 정할게요"', out:[{p:1,text:'은수는 좌표의 세기와 반복 간격부터 설명한다. 확실한 것에서 말이 빨라지고, 짐작인 곳에서는 몇 번이나 고쳐 말한다.\n\n우리는 지도에서 우회 시간과 남은 연료를 함께 센다. 짧게 들러 육안으로 확인하기로 한다.\n\n"이렇게 오래 걸려도 돼요? 연료가— 아니, 그건 제가 셀 게 아니고."\n\n"다섯 사람 일이잖아요."\n\n은수가 승인음 없이 송신 버튼을 누른다. 누르기 전에 헤드폰 한쪽을 벗는다. "접근 중입니다. 들리면 불빛 두 번."\n\n보내고 나서야 어깨를 내린다. "…명령처럼 안 들렸죠?"',fx:{time:55,fuel:-1,moodAll:5,recruitReady:'eunsu',chain:'rq_eunsu_join',note:{type:'사건',title:'함께 내린 판단',body:'은수가 수신 내용을 사실과 추측으로 나눠 설명하고, 경로 결정은 함께 내렸다. 송신은 명령이 아니라 응답을 청하는 말로 보냈다.',links:['은수','천리안']}}}]},
  {label:'들은 것과 짐작한 것을 따로 말해 달라고 한다', out:[{p:1,text:'"들은 건 잔류 인원 다섯. 위험도는 미확인. 경로 이탈은 권고."\n\n은수가 숨을 고른다. 고르고도 한 박자 더 쉰다. "제가 짐작한 건… 함정일지도 모른다는 거예요. 그렇게 생각하면 지나치기가 편하니까. 편하다는 말은 좀 아닌가."\n\n말하고 나니 얼굴이 굳는다. 혼날 차례를 기다리는 사람처럼.\n\n"그럼 편한 쪽 말고, 확인할 수 있는 쪽으로 가죠."\n\n은수는 고개를 끄덕이고 좌표 옆에 처음 보는 표시를 남긴다. `판단 보류 — 현장 확인.`',fx:{time:45,pursuit:-1,recruitReady:'eunsu',chain:'rq_eunsu_join',note:{type:'사건',title:'들은 것과 짐작한 것',body:'은수는 수신된 사실과 자신의 두려움을 구분해 말했다. 판단을 숨기지 않았고, 누구도 복종을 요구하지 않았다.',links:['은수','천리안']}}}]},
  {label:'응답하지 말고 현지 불빛을 기다린다', out:[{p:1,text:'수신기를 끄지 않은 채 차 불만 내렸다. 10분. 아무 일도 없었다.\n\n은수의 손가락이 무릎을 두드린다. 같은 박자로, 계속. 11분째, 능선 아래에서 불빛이 두 번 깜빡였다. 천리안 규격에는 없는 간격이었다.\n\n"…사람 신호네요. 규격은 아니고요."\n\n우리가 다시 불빛을 두 번 보냈다. 은수가 작게 웃는다. 웃은 걸 들킨 얼굴로 헤드폰을 고쳐 쓴다. "기계가 답을 안 줘도, 사람이 답을 주긴 하네요."\n\n그녀는 좌표를 삭제하지 않고 사람 표시로 바꿨다.',fx:{time:35,moodAll:6,recruitReady:'eunsu',chain:'rq_eunsu_join',note:{type:'사건',title:'사람이 보낸 응답',body:'천리안의 지시 대신 현지의 불빛을 기다렸다. 은수는 좌표를 위험 표식이 아니라 사람 표식으로 고쳐 기록했다.',links:['은수','천리안']}}}]},
 ]},
{id:'rq_eunsu_join', type:'스토리', w:0, noPool:1,
 title:'송신이 멎은 뒤',
 text:'은수는 수신기를 오래 듣는다. 좌표는 남아 있지만, 무엇을 하라는 승인음은 오지 않는다.\n\n"서울까지 가면 이런 신호를 더 많이 만나겠죠. …더 많이 만날 거예요. 그건 짐작이고."\n\n"그래서 은수 씨가 필요해요. 같이 갈래요?"\n\n은수는 수신기를 끄고 헤드폰을 벗는다. 이번에는 화면 대신 나를 본다.\n\n"갈게요. 다만 관제센터에서 일했다는 이유로 바로 믿지는 마세요. 이상하면 묻고, 내가 모른다고 하면 같이 확인해요."\n\n"결정도 같이 하고요."\n\n그제야 은수가 장비 가방을 닫는다. 닫고 나서, 고정 끈을 내민다.\n\n"좋아요. 그럼 수신기는 여기 묶어도 돼요?"',
 choices:[{label:'조수석 아래에 수신기 자리를 만든다',out:[{p:1,text:'은수와 조수석 아래를 들여다봤다. 비상 차단 손잡이를 가리지 않고 수신기를 놓을 수 있는지, 케이블이 닿을지 재 봤다.\n\n"제가 예전 방식으로 명령하려 들면 바로 말해 주세요. 저는 잘 모를 수도 있어서."\n\n"그 전에 서로 묻기로 했잖아요."\n\n은수가 고개를 끄덕인다. 수신기는 아직 전원을 끈 채 가방 안에 있었다. 은수는 가방 손잡이를 쥐고 문 옆에서 기다렸다.',fx:{offerComp:'eunsu'}}]}]},

{id:'rq_kangwoo_task', type:'스토리', w:0, noPool:1, once:true,
 title:'강우가 초소를 넘기는 날',
 text:'돔 천장 아래, 오래된 감시 표식이 붉게 깜빡인다. 시장 불빛과 출입 시간을 북쪽으로 보내는 장치다.\n\n강우 옆에는 새 경비 서연이 서 있다. 아직 총보다 손전등을 세게 쥔다.\n\n"내가 장치를 끄는 동안 서연이 시장을 맡는다."\n\n강우는 사다리 발을 장화 끝으로 눌러 고정한 뒤 우리에게 넘긴다.\n\n"……. 그사이 무슨 일이 생겨도 내가 위에서 지시하지 않는다. 서연이 끝내는 데까지 봐야 해."',
 choices:[
  {label:'배터리로 역신호를 흘려 표식을 재운다', req:{up:'antenna'}, out:[{p:1,text:'달구지 배터리에서 역신호를 흘렸다. 붉은 눈이 시장이 빈 것처럼 느린 파형을 보낸다.\n\n그사이 강우는 서연에게 순찰 시간을 묻고, 사각을 묻고, 마지막엔 자기 없이 결정할 일을 물었다. 서연은 전부 대답했다.\n\n두 시간 남짓 뒤 표식이 꺼졌다. 시장에서 작은 소동이 났지만 강우는 돌아보지 않았다. 어깨만 한 번 움직였다가 멈췄다. 서연의 호각 한 번으로 끝났으니까.\n\n"…됐다." 강우가 처음으로 경비탑에서 등을 돌린다.',fx:{time:150,van:-2,recruitChoice:'spoof',recruitRoad:'kangwoo',note:{type:'사건',title:'경비탑의 다음 사람',body:'감시 표식을 재우고 후임 서연이 스스로 시장을 지키는 시간을 만들었다.',links:['강우']}}}]},
  {label:'장치를 뜯고 출입로를 새로 짠다', out:[{p:1,text:'감시 표식의 전선을 끊자 돔 안 조명이 절반 꺼졌다. 대신 우리는 손전등과 종으로 새 경계선을 만들었다.\n\n첫 순찰에서 서연은 강우가 가르쳐준 길을 벗어났다. 더 짧고, 사각도 적었다. 강우는 입을 열었다가 다물고, 지도를 고쳐 그렸다.\n\n몇 시간 뒤, 서연이 경비탑에서 먼저 말했다. "이제 가세요. 여긴 제가 봅니다."\n\n강우가 군번줄 하나를 탑 난간에 걸어두었다.',fx:{time:240,scrap:5,fatigue:8,recruitChoice:'rebuild',recruitRoad:'kangwoo',note:{type:'사건',title:'경비탑의 다음 사람',body:'감시 표식을 뜯고 서연이 직접 고친 새 경계선을 세웠다.',links:['강우']}}}]},
  {label:'한동안 후임의 지시만 따른다', out:[{p:1,text:'강우는 총을 내려놓고 서연의 지시만 따랐다. 북문 확인. 동쪽 좌판 대피. 지붕 소리 무시.\n\n한 시간이 지난 뒤, 취객 둘이 싸웠다. 강우의 어깨가 먼저 움직였지만 멈췄다. 서연이 둘 사이에 물통을 내려놓고 말했다. "싸울 힘 있으면 이거나 나르세요." 싸움은 끝났다.\n\n강우는 한동안 아무 말도 하지 않았다. 그러다 아주 작게 웃었다. "…나보다 낫군."\n\n감시 표식도 둘이 함께 내렸다.',fx:{time:360,food:-1,moodAll:4,recruitChoice:'follow',recruitRoad:'kangwoo',note:{type:'사건',title:'경비탑의 다음 사람',body:'강우가 개입하지 않은 시간을 서연이 지켰다. 돔 시장에는 다음 파수꾼이 생겼다.',links:['강우']}}}]},
 ]},
{id:'rq_kangwoo_follow', type:'스토리', w:0, noPool:1, once:true,
 title:'돌아보지 않는 거리',
 text:'돔 시장을 떠난 지 한 구간. 강우의 무전기에서 서연의 목소리가 튄다.\n\n"북문 소란. 경비 둘 이동 중. 응답 바랍니다."\n\n강우의 손이 문손잡이에 닿는다. 차를 돌리자는 말은 하지 않는다. 대신 무전기를 너무 세게 쥐어 플라스틱이 운다. 엄지가 송신 버튼 위에 올라갔다가 내려온다. 두 번.\n\n"……. 내가 답하면 서연은 내 지시를 기다린다. 답하지 않으면… 내가 버린 것 같고."\n\n무전기 너머로 다시 호각이 울린다. 이번엔 두 번. 강우가 가르치지 않은 신호다.',
 choices:[
  {label:'채널만 열어 두고 서연의 판단을 기다린다', out:[{p:1,text:'강우는 송신 버튼에서 엄지를 뗐다. 무전기 너머로 발소리와 짧은 지시가 오갔다.\n\n"서쪽 문 닫고, 장사꾼은 안쪽으로. 싸움 당사자 둘만 남겨요."\n\n서연의 목소리였다. 잠시 뒤 호각 한 번.\n\n"상황 종료. 강우 씨, 듣고 있으면 계속 가세요."\n\n강우가 그제야 문손잡이를 놓는다. 놓고 나서 손바닥을 무릎에 문지른다. "…저 신호는 안 가르쳤는데."\n\n"그래서 잘한 거겠죠."\n\n그는 대답하지 않았다. 얼마 뒤 무전기 음량을 한 칸 올렸다.',fx:{time:25,moodAll:5,recruitReady:'kangwoo',chain:'rq_kangwoo_join',note:{type:'사건',title:'서연의 두 번째 호각',body:'강우가 명령하지 않은 동안 서연은 자기 방식으로 북문 소란을 끝냈다. 그는 채널을 끊지 않되 시장의 결정을 빼앗지 않았다.',links:['강우','서연']}}}]},
  {label:'강우가 서연에게 가르친 것을 묻는다', out:[{p:1,text:'"싸움이면 사람부터 갈라놓고, 출입문부터 확보한다. 다치면 시장 진료소로—"\n\n강우가 말을 멈춘다. 이미 무전기 너머에서 같은 지시가 들리고 있었다. 순서는 조금 달랐지만 더 빨랐다.\n\n"다 가르쳤네요."\n\n"아니. 저 순서는 처음 듣는다."\n\n무전기에서 상황 종료가 들렸다. 강우는 그 뒤로도 문손잡이를 잡고 있었다. 얼마 뒤에야 손을 뗐다.\n\n"…나보다 빠르네." 그가 무전기를 무릎에 내려놓았다. 놓고도 한동안 손을 얹어 뒀다. "됐어. 이제 가자."',fx:{time:30,moodAll:4,recruitReady:'kangwoo',chain:'rq_kangwoo_join',note:{type:'사건',title:'서연이 고친 순서',body:'강우는 서연이 자신이 가르치지 않은 더 빠른 순서로 소란을 끝내는 것을 들었다. 이제 시장으로 돌아가 지시할 이유가 사라졌다.',links:['강우','서연']}}}]},
  {label:'차는 세우되 방향은 돌리지 않는다', out:[{p:1,text:'달구지를 갓길에 세웠다. 강우는 문을 연 채 한 발만 땅에 내렸다.\n\n"가도 되고, 돌아가도 돼요. 다만 우리가 대신 정하진 않을게요."\n\n긴 침묵 끝에 강우가 발을 다시 올린다. 올리고도 문은 그대로 열어 뒀다. 그때 무전기에서 서연의 숨찬 목소리가 들렸다. "상황 끝. 그리고 강우 씨, 여기 오면 문 안 열어줄 겁니다."\n\n강우가 헛웃음을 터뜨린다. "…경비가 아주 독해졌군."\n\n그가 직접 문을 닫는다. 잠금까지 확인하고 나서 말한다. "가자. 이번엔 내가 지킬 자리를 내가 고른다."',fx:{time:20,moodAll:6,recruitReady:'kangwoo',chain:'rq_kangwoo_join',note:{type:'사건',title:'돌아가지 않기로 한 정차',body:'강우에게 돌아갈지 계속 갈지 고를 시간을 주었다. 서연의 상황 종료를 들은 뒤, 그는 스스로 달구지 문을 닫았다.',links:['강우','서연','달구지']}}}]},
 ]},
{id:'rq_kangwoo_join', type:'스토리', w:0, noPool:1,
 title:'등을 돌린 다음',
 text:'강우는 무전기에 짧게 남긴다. "수신 양호. 네 판단대로 계속해."\n\n서연의 대답은 바로 온다. "그 말 하려고 끼어든 거면, 다음부터는 호출할 때까지 듣기만 하세요."\n\n강우가 헛웃음을 흘린다. 무전기를 끄진 않는다. 다만 군장 깊숙이 넣는다. 넣었다가 한 번 꺼내 확인하고, 도로 넣는다.\n\n"……. 이제 시장으로 돌아갈 핑계도 없군."\n\n"그럼 서울까지 같이 갑니까?"\n\n강우가 달구지의 문과 비상 탈출구를 살핀다. 문을 두 번 여닫는다.\n\n"간다. 대신 문 잠금부터 고쳐야겠어. 뒤쪽 사각도 넓고."\n\n"타자마자 근무부터 하려고요?"\n\n대답은 한 박자 늦게 왔다.\n\n"야간 첫 순찰이 비었잖아."',
 choices:[{label:'강우의 군장이 들어갈 자리를 비운다',out:[{p:1,text:'강우가 문 밖에서 통로와 비상 탈출구를 살폈다. 군장을 걸어도 문이 열리는지 재 보고, 걸쇠를 한 번 더 확인한다.\n\n"함께 가게 되면 첫 순찰은 내가 선다. 다음부터는 순번 정하고."\n\n군장 속 무전기에서 서연의 호각 소리가 한 번 새어 나왔다. 강우는 송신 버튼을 짧게 눌러 답했다. 군장은 발치에 세워 둔 채 내 대답을 기다렸다.',fx:{offerComp:'kangwoo'}}]}]},

