 choices:[{label:'…', out:[{p:1, text:'저 사람은 오늘 뭘 낚았을까. 찌는 그대로고, 차는 굽이를 돌아 물가에서 멀어진다.', fx:{moodAll:1}}]}]},

/* Roadside camp risks */
{id:'camp_thief', type:'위기', w:0, fixed:true,
 storyOrigin:{kind:'memory',label:'지난밤',title:'야영지',timeLabel:'지난밤 · 야영지'},
 title:'밤손님',
 text:'새벽, 차 밖에서 부스럭거리는 소리에 눈을 떴다.\n\n몸을 일으키지 않고 창틈으로 내다봤다. 그림자 하나가 지붕 짐끈을 풀고 있다. 도둑이다.',
 choices:[
  {label:'소리치며 뛰쳐나간다', out:[
    {p:2, text:'"야!!"\n\n그림자가 화들짝 뛰어 어둠으로 사라졌다. 짐을 점검하니— 고철 몇 개가 사라진 뒤였다. 손이 빨랐다.', fx:{scrap:-4, moodAll:-2}},
    {p:1, text:'"야!!"\n\n도둑이 놀라 훔친 자루를 통째로 떨어뜨리고 도망쳤다. 자루엔 우리 것— 그리고 다른 데서 훔친 것까지 들어 있었다.', fx:{scrap:5, moodAll:2}}]},
  {label:'쇠파이프를 들고 나간다', req:{item:'쇠파이프'}, out:[{p:1, text:'쇠파이프가 달빛에 번쩍이는 것만으로 상황이 종료됐다.\n\n도둑은 훔치려던 것을 내려놓고, 정중히 사과하고(진짜로 꾸벅 인사를 했다), 어둠으로 사라졌다.\n\n"…예의 바른 도둑이네." 다시 잠들긴 글렀다.', fx:{fatigue:8, moodAll:1}}]},
  {label:'숨죽이고 보낸다', out:[{p:1, text:'부스럭 소리가 한참 이어지다 멀어졌다.\n\n아침에 지붕의 짐끈이 풀려 있었다. 식량 상자까지 열려 있어 남은 짐을 하나씩 확인했다. 쫓아가지 않은 걸 후회하진 않기로 했다.', fx:{scrap:-3, food:-1, moodAll:-3}}]},
 ]},
{id:'camp_dogs', type:'위기', w:0, fixed:true,
 storyOrigin:{kind:'memory',label:'지난밤',title:'야영지',timeLabel:'지난밤 · 야영지'},
 title:'들개들의 밤',
 text:'낮게 으르렁거리는 소리에 잠이 깼다.\n\n들개 대여섯 마리가 차를 둘러싸고 있다. 목표는 명확하다 — 식량 상자.',
 choices:[
  {label:'보리가 나선다', req:{comp:'leo'}, out:[{p:1, text:'보리가 창문에 앞발을 딛고 특유의 하울링을 길게 뽑았다.\n\n들개들이 멈칫— 하더니 대장 개가 짧게 응답하고 무리를 물렸다. 개들의 언어로 뭔가 합의가 이뤄진 모양이다.\n\n보리는 아침까지 우쭐해 있었다.', fx:{moodAll:3, note:{type:'사건',title:'보리의 하울링 외교',body:'들개 무리와 개들의 언어로 합의. 내용은 보리만 안다.'}}}]},
  {label:'식량 하나를 던져준다', req:{food:1}, out:[{p:1, text:'통조림 하나를 멀리 던졌다. 무리가 그쪽으로 몰려간 사이 조용히 창을 닫았다.\n\n아침에 보니 빈 깡통이 차 앞에 가지런히 놓여 있었다. …설마, 반납인가.', fx:{food:-1, moodAll:1}}]},
  {label:'경적과 헤드라이트로 쫓는다', out:[
    {p:2, text:'빵— 상향등!\n\n들개들이 흩어졌다. 대신 그 요란함에 온 동네— 는 없지만, 밤새 뭔가가 근처를 서성이는 기척에 밤새 설잠을 잤다.', fx:{fatigue:10, moodAll:-2}},
    {p:1, text:'들개들은 흩어졌지만 대장 개가 앙심을 품었는지 타이어에 볼일을 보고 갔다. 실질 피해: 자존심.', fx:{moodAll:-1}}]},
 ]},
{id:'camp_scan', type:'위기', w:0, fixed:true, ai:1,
 storyOrigin:{kind:'memory',label:'지난밤',title:'야영지',timeLabel:'지난밤 · 야영지'},
 title:'새벽의 탐조등',
 text:'새벽 3시. 하늘에서 흰 빛기둥이 내려와 들판을 훑는다.\n\n야간 초계 드론의 탐조등. 빛이 차 쪽으로 천천히 다가온다.',
 choices:[
  {label:'불을 끄고 숨죽인다', out:[
    {p:2, text:'모닥불에 흙을 덮고 바닥에 납작 엎드렸다.\n\n빛기둥이 차 지붕을 스윽— 지나갔다. 폐차로 판정한 모양이다. 달구지의 낡음이 처음으로 고마웠다.', fx:{fatigue:8, moodAll:-2}},
    {p:1, text:'빛기둥이 차 위에서 3초간 멈췄다.\n\n<span class="ai">"…차량 1. 열원 감지. 기록."</span>\n\n드론은 그냥 갔지만, 기록이 남았다.', fx:{pursuit:1, moodAll:-3}}]},
  {label:'은수가 위장 신호를 쏜다', req:{comp:'eunsu'}, out:[{p:1, text:'은수가 수신기로 폐기 차량 트랜스폰더 신호를 흉내 냈다.\n\n드론이 차를 "오래전 폐기 처리된 렌터카"로 분류하고 지나갔다.\n\n"우리 이제 서류상 폐차예요." 은수가 하품하며 말했다. 듣던 중 안심되는 소리였다.', fx:{mood:{eunsu:3}}}]},
 ]},
{id:'camp_visitor', type:'조우', w:0, fixed:true,
 storyOrigin:{kind:'memory',label:'지난밤',title:'야영지',timeLabel:'지난밤 · 야영지'},
 title:'모닥불의 손님',
 text:'불가에 인기척. 배낭을 멘 노인이 조심스레 서 있다.\n\n"…언제부터 거기 계셨어요?"\n\n"글쎄. 불이 보여서 왔는데 부르기가 뭣해서." 노인이 배낭끈을 고쳐 멨다. "불 좀 쬐어도 될까요? 밤길이 생각보다 춥구먼."',
 choices:[
  {label:'자리를 내어준다', out:[
    {p:2, text:'노인은 오랫동안 걸어서 전국을 돌고 있다고 했다.\n\n"차가 있으면 빠르지. 근데 걸으면 다 보여." 노인의 지도엔 우리가 모르는 표시가 가득했다.\n\n"이 세모는 뭐예요?"\n\n"그거는." 노인이 지도를 돌려 봤다가 다시 돌렸다. "적어놓고 까먹었네. 아마 물일 거요. 아마."\n\n떠나기 전, 확실하다는 표시 하나를 우리 지도에 옮겨줬다.', fx:{revealNear:1, moodAll:3, note:{type:'인물',title:'걷는 노인',body:'오랫동안 걸어서 전국을 도는 사람. "걸으면 다 보여."'}}},
    {p:1, text:'노인과 새벽까지 이야기를 나눴다. 대가는 없었고, 필요도 없었다.\n\n아침에 노인은 먼저 떠나며 불씨를 정리해두고 갔다. 좋은 손님이었다.', fx:{moodAll:4, fatigue:6}}]},
  {label:'경계하며 거절한다', out:[{p:1, text:'"…그러세요. 요즘 세상에 당연하지."\n\n노인은 화내지 않고 어둠 속으로 사라졌다. 모닥불이 괜히 머쓱하게 탔다.', fx:{moodAll:-2}}]},
 ]},

/* ═════ 김천 분기 — 한 번 고르면 청주까지 이어지는 두 노선 ═════ */
{id:'route_mid_fork',type:'스토리',w:0,locEvent:'gimcheon',once:true,
 title:'두 길이 갈라지는 곳',scene:'route-mid-fork',
 text:'김천 북쪽 교차로에서 차를 세웠다. 넘어진 표지판 두 장을 씻어 세우니 갈 길이 선명해졌다.\n\n동쪽은 상주와 문경을 지나 청주로 곧장 오르는 능선길. 짧지만 비에 깎인 구간이 많다. 서쪽은 무주와 전주 장터를 거쳐 올라가는 길. 훨씬 멀지만 물과 사람을 만날 곳이 이어진다.\n\n지도 위에서 두 선은 청주에서 다시 만났다. 나는 동쪽 선 옆에 ‘빠름, 험로’, 서쪽 선 옆에 ‘보급, 안전’을 적었다.\n\n달구지 짐칸을 열어 보니 어느 쪽을 고르느냐에 따라 챙길 짐도 달라진다. 능선으로 가면 삽과 견인줄, 장터로 가면 빈 물통과 묶음끈이 먼저다.\n\n청주에 닿을 때까지는 고른 노선 밖으로 나갈 수 없다. 다른 곳에 맡은 일이 있다면 청주에서 길이 합쳐진 뒤 돌아가야 한다. 준비를 마친 뒤 한쪽을 고르기로 했다.',
 choices:[
  {label:'동쪽 능선길로 간다',out:[{p:1,text:'표지판에 분필로 동그라미를 쳤다. 상주, 문경, 충주, 청주.\n\n"산길로 간다. 빨리 가되, 길에서 만난 일은 두고 가지 말자."\n\n삽과 견인줄을 짐 맨 위로 옮겼다. 당장 꺼낼 일이 없으면 좋겠지만, 산길에서 그런 바람은 대개 오래가지 않는다.',fx:{routeChoice:'ridge'}}]},
  {label:'서쪽 장터길로 간다',out:[{p:1,text:'무주 쪽 선에 동그라미를 쳤다. 전주와 논산, 대전을 거쳐 청주까지.\n\n"조금 늦더라도 사람 있는 길로 간다. 남산에 가져갈 건 부품만이 아니니까."\n\n빈 물통과 묶음끈을 짐 맨 위로 옮겼다. 장터길에서는 빈자리도 쓸모가 있다.',fx:{routeChoice:'market'}}]}
 ]},

{id:'route_ridge_rescue',type:'구조',w:0,fixed:true,once:true,scene:'route-ridge-rigging-v2',
 title:'능선 아래의 네 사람',
 turnSpeakers:['me',{who:'passer_woman',name:'여자'},'me',{who:'passer_woman',name:'여자'}],
 combat:{phase:1,total:3,step:'멈춰 세우기',
   threat:'비탈에 걸린 우편 수레',objective:'비탈이 다시 움직이기 전에 네 사람을 도로로 올린다',terrain:'젖은 절개지와 무너진 돌망',stakes:'수레가 계곡 쪽으로 밀리면 사람과 약 상자를 함께 잃는다',intent:'젖은 돌망이 한 번 더 내려앉기 전에 사람과 차의 무게를 고정해야 한다',counters:{'고정':'달구지를 닻으로 쓴다','지휘':'하중을 사람별로 나눈다'}},
 text:'상주를 벗어난 능선에서 손을 흔드는 아이가 보였다. 도로 아래로 작은 수레가 반쯤 굴러 떨어져 있다. 어른 셋과 아이 하나가 돌망 사이에 매달린 채 움직이지 못한다.\n\n"다친 사람 있어요?"\n\n아래에서 여자가 고개를 들었다. 바람에 말이 반쯤 날아갔다. "…목 하나요."\n\n"뭐라고요?"\n\n"발목이요! 한 명! 그런데 이 비탈, 아까부터 계속 내려앉아요."\n\n차를 산 쪽 바위에 바짝 붙였다. 달구지의 무게를 닻으로 쓸 수는 있다. 문제는 비탈이 얼마나 더 버티느냐다.\n\n총을 꺼낼 상대는 없다. 대신 비탈이 조금씩 우리 시간을 가져가고 있다.',
 choices:[
  {label:'달구지를 바위 뒤에 걸고 견인줄을 내린다',tactic:'고정',prep:1,terrainFit:2,out:[{p:1,text:'차를 바위 안쪽에 비스듬히 세우고 바퀴마다 돌을 괴었다. 견인줄을 당기자 차체가 한 번 울었지만 버텼다.\n\n"한 번에 한 사람. 줄 놓치면 안 돼."\n\n아이부터 줄에 매달렸다.',fx:{time:15,combatStart:{id:'ridge_rescue',kind:'구조',threat:'비탈에 걸린 우편 수레',terrain:'젖은 절개지와 무너진 돌망',objective:'네 사람을 도로로 올린다',stakes:'비탈이 다시 움직이기 전에 끝내야 한다',pressure:1},combatEdge:2,chain:'route_ridge_anchor'},sfx:'metal'}]},
  {label:'도로 위 사람들과 먼저 역할을 나눈다',tactic:'지휘',prep:1,terrainFit:1,out:[{p:1,text:'삽을 들 사람, 줄을 잡을 사람, 올라온 사람을 받을 자리를 빠르게 정했다.\n\n"아이부터. 다친 분은 줄로 몸부터 받쳐요. 수레는 사람 뒤."\n\n서로 이름도 모르지만, 적어도 누가 무엇을 하는지는 알게 됐다.',fx:{time:10,combatStart:{id:'ridge_rescue',kind:'구조',threat:'비탈에 걸린 우편 수레',terrain:'젖은 절개지와 무너진 돌망',objective:'네 사람을 도로로 올린다',stakes:'비탈이 다시 움직이기 전에 끝내야 한다',pressure:1},combatEdge:1,combatPressure:-1,chain:'route_ridge_anchor'},sfx:'cover'}]}
 ]},
{id:'route_ridge_anchor',type:'구조',w:0,fixed:true,once:true,scene:'route-ridge-rigging-v2',
 title:'줄 하나에 걸린 무게',
 combat:{phase:2,total:3,step:'길 만들기',
   threat:'비탈에 걸린 우편 수레',objective:'사람이 오를 발판을 만들고 줄의 하중을 나눈다',terrain:'젖은 절개지와 무너진 돌망',stakes:'한 곳에 무게가 몰리면 흙이 다시 무너진다',intent:'당기는 힘이 한곳에 몰리면 발판부터 무너진다',counters:{'토공':'디딜 곳을 늘린다','장비':'하중을 두 줄로 나눈다'}},
 text:'아이와 첫 번째 어른이 도로로 올라왔다. 세 번째 사람을 당기려는 순간, 발밑 돌망이 손바닥만큼 내려앉았다.\n\n아래의 남자가 소리쳤다. "잠깐! 지금 당기면 여기 다 같이 내려가요."\n\n"놓으라고요?"\n\n"풀라고요! 놓지는 말고!"\n\n줄을 조금 풀어 하중을 뺐다. 차는 버티는데 땅이 못 버틴다. 힘보다 사람이 디딜 길부터 만들어야 한다.\n\n수레 안에는 문경으로 가는 편지와 해열제가 섞여 있다. 하지만 먼저 올라와야 할 것은 사람이다.',
 choices:[
  {label:'삽으로 하중을 나눌 계단을 판다',tactic:'토공',terrainFit:2,combatRoll:.62,out:[
    {p:1,text:'한 사람이 설 너비만큼 흙을 걷고 돌을 눌러 박았다. 빠른 길은 아니지만, 발을 옮길 때마다 다음 사람이 설 곳이 생겼다. 남자가 그 발판을 따라 도로까지 올라왔다.',fx:{time:25,fatigue:3,combatEdge:1,combatPressure:-1,combatRead:{label:'사람 줄과 짐 줄을 나눌 발판',tactics:['분리 인양','릴레이']},chain:'route_ridge_extract'},sfx:'cover'},
    {p:1,text:'세 번째 계단을 파는 순간 흙이 통째로 밀려 내려갔다. 방금 만든 발판이 아래 사람 어깨 위로 쏟아졌다.\n\n아래에서 괜찮다는 소리가 올라왔지만 괜찮은 목소리가 아니었다.\n\n다시 팠다. 이번엔 더 얕게, 더 느리게. 남자를 도로까지 받쳐 올리고 나니 판 자리로 흙이 또 흘러들었다.',fx:{time:45,fatigue:8,combatPressure:2,combatRead:{label:'무너진 자리라 발 디딜 곳을 못 믿는다',tactics:['토공']},chain:'route_ridge_extract'},sfx:'impact'}]},
  {label:'견인줄을 두 갈래로 묶어 흔들림을 잡는다',tactic:'장비',terrainFit:2,combatRoll:.6,out:[
    {p:1,text:'본줄은 달구지에, 보조줄은 가드레일 기둥에 걸었다. 한 줄이 흔들릴 때 다른 줄이 몸을 잡았다.\n\n"이제 한 발씩. 뛰지 말고."\n\n남자가 두 줄 사이로 몸을 옮겨 도로 위를 짚었다.',fx:{time:15,scrap:-1,combatEdge:1,combatRead:{label:'한 줄이 흔들릴 때 받쳐 줄 보조 하중',tactics:['분리 인양','릴레이']},chain:'route_ridge_extract'},sfx:'metal'},
    {p:1,text:'가드레일 기둥이 생각보다 삭아 있었다. 보조줄을 당기자 기둥이 뿌리째 기울었다.\n\n급히 본줄 하나로 되돌렸다. 이제 하중을 한 줄에만 실어야 한다.\n\n"한 명씩. 절대 두 명 같이 오르지 마세요."\n\n남자를 먼저 받쳐 올렸다. 그가 도로에 닿고도 본줄은 한동안 흔들렸다.',fx:{time:30,scrap:-2,combatPressure:2,combatRead:{label:'줄이 하나뿐이라 한 번에 한 사람',tactics:['릴레이']},chain:'route_ridge_extract'},sfx:'metal'}]},
  {label:'아래 남자를 업고 짧게 치고 오른다',tactic:'완력',risk:'비탈 압박 상승',combatRoll:.5,out:[
    {p:1,text:'남자를 등에 묶고 가장 짧은 선을 골랐다. 절반은 힘으로, 나머지는 위에서 당기는 줄로 도로까지 올렸다. 빠르지만 땅이 한 번 더 울었다. 발목을 다친 여자는 아직 아래에서 차례를 기다렸다.',fx:{time:10,fatigue:6,combatPressure:1,chain:'route_ridge_extract'},sfx:'engine'},
    {p:1,text:'절반쯤 올라갔을 때 발밑이 꺼졌다. 업힌 남자와 함께 미끄러져 원래 자리보다 아래로 떨어졌다.\n\n허리를 돌에 부딪쳤다. 몸을 펴려니 숨부터 막혔다. 남자가 내 등에서 내려 줄을 다시 걸었다.\n\n이번엔 그를 먼저 도로까지 올리고 빈 줄을 받았다. 내 몸 하나를 끌어올리는 데도 몇 번이나 멈춰야 했다.',fx:{time:35,fatigue:12,combatPressure:2,combatEdge:-1,injury:{who:'driver',label:'허리 삠',days:2},chain:'route_ridge_extract'},sfx:'impact'}]}
 ]},
{id:'route_ridge_extract',type:'구조',w:0,fixed:true,once:true,scene:'route-ridge-rigging-v2',
 title:'마지막 한 번',
 combat:{phase:3,total:3,step:'꺼내기',
   threat:'비탈에 걸린 우편 수레',objective:'마지막 사람과 약 상자를 함께 도로로 올린다',terrain:'젖은 절개지와 무너진 돌망',stakes:'흙이 움직이기 시작했다. 한 번에 끝내야 한다',intent:'큰 자갈이 굴러오기 전에 사람과 약 상자의 하중을 한 번에 나눠야 한다',counters:{'분리 인양':'두 줄을 반 박자 나눠 당긴다','릴레이':'사람과 내용물만 가볍게 옮긴다'}},
 text:'사람 셋은 올라왔다. 아래에는 발목을 다친 여자와 수레가 남았다. 그때 비탈 위쪽에서 자갈이 한꺼번에 굴러내렸다.\n\n여자가 약 상자를 수레 밖으로 밀며 말했다. "이건 두고 저만 올리세요."\n\n"사람 먼저인 건 맞아요." 내가 줄을 다시 잡았다. "그래도 둘 다 올릴 방법부터—"\n\n"둘 다는 안 돼요."\n\n"한 번은 당겨봅시다."\n\n한 번 당길 시간은 남아 있다.',
 choices:[
  {label:'사람 줄과 수레 줄을 따로 당긴다',tactic:'분리 인양',terrainFit:2,combatRoll:.58,out:[
    {p:1,scene:'route-ridge-safe-v2',text:'구호를 셋에 맞췄다. 사람 줄이 먼저 팽팽해지고, 반 박자 뒤 수레가 돌턱을 넘었다. 여자의 손이 도로 가장자리를 잡자 모두가 그대로 뒤로 넘어졌다.\n\n네 사람이 전부 올라왔다. 해열제 상자도 젖었지만 멀쩡했다. 아이가 달구지 문을 두드렸다. "이 차, 집인데 힘도 세네요."',fx:{time:20,moodAll:4,combatEnd:1,combatResult:'success',flag:'route_ridge_saved',note:{type:'사건',title:'능선 아래 네 사람',body:'달구지를 닻으로 삼아 네 사람과 문경행 해열제를 함께 올렸다.',links:['달구지']}}},
    {p:1,scene:'route-ridge-safe-v2',text:'사람은 도로 위로 올라왔지만 수레 바퀴 하나가 돌망에 걸렸다. 줄을 놓는 순간 수레 절반이 아래로 쏟아졌다. 편지는 건졌고 해열제는 반만 남았다.\n\n여자가 숨을 고르며 말했다. "사람 넷이 올라왔잖아요. 나머지는 다시 구하면 돼요."',fx:{time:25,moodAll:2,combatEnd:1,combatResult:'partial',flag:'route_ridge_saved_partial',note:{type:'사건',title:'능선 아래 네 사람',body:'네 사람은 모두 구했다. 약 상자는 절반만 건졌지만, 우선순위는 끝까지 바뀌지 않았다.',links:['달구지']}}},
    {p:1,scene:'route-ridge-safe-v2',text:'두 줄을 당기는 박자가 어긋났다. 수레가 먼저 미끄러지며 여자의 줄을 쳤다.\n\n여자는 올라왔다 — 발목이 아니라 무릎까지 다친 채로. 수레와 해열제는 계곡 아래에서 소리를 멈췄다.\n\n"저 약, 문경 아이들 몫이었는데." 여자는 우리 잘못이 아니라고 두 번 말했다. 두 번째에는 여자가 아래를 보지 못했다. 올라온 사람들은 손에서 줄을 놓지 않은 채 한동안 서 있었다.',fx:{time:35,moodAll:-5,fatigue:6,combatEnd:1,combatResult:'failure',flag:'route_ridge_failed',note:{type:'사건',title:'계곡에 남은 약 상자',body:'네 사람은 구했지만 문경행 해열제를 전부 잃었고 부상자의 상태가 나빠졌다. 문경에서 이 이야기를 다시 듣게 될 것이다.',links:['달구지']}}}]},
  {label:'수레를 비우고 사람과 약만 릴레이로 올린다',tactic:'릴레이',terrainFit:2,combatRoll:.64,out:[
    {p:1,scene:'route-ridge-safe-v2',text:'편지 다발을 품에 나눠 안고, 약 상자는 줄에 묶었다. 빈 수레는 내려두고 사람과 내용물만 차례로 올렸다. 마지막 여자가 도로에 닿자 비탈이 크게 흘러내렸다.\n\n수레는 잃었지만 사람 넷과 배달할 것은 모두 남았다.',fx:{time:30,fatigue:3,moodAll:4,combatEnd:1,combatResult:'success',flag:'route_ridge_saved'}},
    {p:1,scene:'route-ridge-safe-v2',text:'사람 넷과 편지는 모두 올렸다. 약 상자 하나가 진흙에 빠졌지만 더 내려갈 수는 없었다.\n\n"괜찮아요. 문경에서 나눠 쓰면 돼요." 여자가 남은 상자를 꼭 안았다.',fx:{time:35,fatigue:4,moodAll:2,combatEnd:1,combatResult:'partial',flag:'route_ridge_saved_partial'}},
    {p:1,scene:'route-ridge-safe-v2',text:'릴레이 중간에 비탈이 크게 내려앉았다. 마지막 여자를 끌어올리는 데는 성공했지만, 줄을 잡던 내 손바닥이 길게 찢어졌고 약 상자는 전부 흙더미에 묻혔다.\n\n"사람은 다 살았어요." 여자가 말했다. 맞는 말이었다. 그런데 문경 쪽 하늘을 보는 그녀의 눈은 다른 계산을 하고 있었다.',fx:{time:40,fatigue:8,moodAll:-5,injury:{who:'driver',label:'손바닥 열상',days:2},combatEnd:1,combatResult:'failure',flag:'route_ridge_failed',note:{type:'사건',title:'묻힌 약 상자',body:'전원 구조에는 성공했지만 해열제를 전부 잃었다. 문경의 겨울이 조금 더 길어졌다.',links:['달구지']}}}]}
 ]},

{id:'route_market_convoy',type:'호송',w:0,fixed:true,once:true,scene:'route-market-convoy',
 title:'장터에서 묶인 다섯 수레',
 combat:{kind:'호송',phase:1,total:3,step:'행렬 세우기',
   threat:'잠든 자동 검문소',objective:'씨앗과 약을 실은 다섯 수레를 기록 없이 통과시킨다',terrain:'좁은 국도와 폐차 차양, 고장 난 차단봉',stakes:'센서가 행렬을 깨우면 장터 사람들의 이동 기록이 중앙망에 남는다',intent:'센서는 따로 움직이는 사람 수를 세어 재검사를 깨운다',counters:{'편성':'다섯 수레를 한 차량으로 묶는다','정찰':'센서가 외면하는 박자를 찾는다'}},
 text:'무주 장터를 지나려는데 손수레 다섯 대가 같은 자리에 묶여 있었다. 씨앗, 소금, 붕대, 편지. 북쪽 마을 셋이 함께 보낸 짐이다.\n\n수레 행렬을 맡은 운송 담당자가 꺼진 검문소를 가리켰다. "차 한 대는 지나가요. 사람이 줄지어 가면 센서가 켜져요."\n\n차단봉 아래 작은 불 하나가 일정하게 깜빡인다. 전광판은 죽었어도 사람을 세는 장치는 아직 살아 있다.\n\n"달구지 한 대처럼 보이게 만들면 돼요." 내가 수레 사이를 재며 말했다.\n\n"묶는다고요? 다섯 대를 다?"\n\n"전부요. 간격까지 맞춰야 해요."',
 choices:[
  {label:'수레를 달구지 뒤에 한 줄로 묶는다',tactic:'편성',prep:1,terrainFit:2,out:[{p:1,text:'긴 밧줄 하나에 수레 다섯 대를 간격 맞춰 묶었다. 각 수레에는 브레이크를 잡을 사람이 한 명씩 붙었다.\n\n"우리가 멈추면 다 멈추고, 우리가 가면 한 박자 뒤에 갑니다."\n\n제각각이던 짐이 하나의 긴 차량처럼 보이기 시작했다.',fx:{time:20,combatStart:{id:'market_convoy',kind:'호송',threat:'잠든 자동 검문소',terrain:'좁은 국도와 폐차 차양, 고장 난 차단봉',objective:'다섯 수레를 기록 없이 통과시킨다',stakes:'행렬이 끊기면 센서가 사람 수를 센다',pressure:1},combatEdge:1,chain:'route_market_mask'},sfx:'metal'}]},
  {label:'폐차 차양 아래에서 통과 순서를 맞춘다',tactic:'정찰',prep:1,terrainFit:2,out:[{p:1,text:'센서가 꺼지는 간격을 세 번 재었다. 12초마다 렌즈가 반대 차선을 본다.\n\n"첫 수레가 저 금을 넘을 때 마지막 수레가 출발하면 돼요."\n\n사람들이 자기 차례를 입으로 되뇌었다.',fx:{time:15,combatStart:{id:'market_convoy',kind:'호송',threat:'잠든 자동 검문소',terrain:'좁은 국도와 폐차 차양, 고장 난 차단봉',objective:'다섯 수레를 기록 없이 통과시킨다',stakes:'행렬이 끊기면 센서가 사람 수를 센다',pressure:1},combatPressure:-1,chain:'route_market_mask'},sfx:'cover'}]}
 ]},
{id:'route_market_mask',type:'호송',w:0,fixed:true,once:true,scene:'route-market-convoy',
 title:'한 대처럼 보이기',
 combat:{kind:'호송',phase:2,total:3,step:'센서 속이기',
   threat:'잠든 자동 검문소',objective:'행렬 전체를 달구지의 적재물로 인식시킨다',terrain:'좁은 국도와 폐차 차양, 고장 난 차단봉',stakes:'사람 한 명이라도 따로 잡히면 전원 재검사가 시작된다',intent:'센서가 바퀴와 사람 윤곽을 따로 세기 시작한다',counters:{'위장':'긴 차량 윤곽을 만든다','지휘':'모두 같은 박자로 움직인다'}},
 text:'행렬이 검문선 앞에 섰다. 전광판은 죽어 있는데, 센서만 천천히 좌우로 움직였다.\n\n세 번째 수레의 아이가 물었다. "뛰면 더 빨리 지나갈 수 있죠?"\n\n"아니. 오늘은 안 뛰는 게 제일 빨라."\n\n"왜요?"\n\n"…그건 지나고 나서 설명해줄게."\n\n달구지 천막을 길게 풀어 뒤 수레까지 덮자, 서로 다른 다섯 짐이 한 몸처럼 이어졌다.',
 choices:[
  {label:'천막과 반사판으로 차량 윤곽을 잇는다',tactic:'위장',terrainFit:2,combatRoll:.6,out:[
    {p:1,text:'천막 끝에 낡은 반사판을 달았다. 센서가 훑을 때마다 빛은 달구지 뒤쪽까지 한 줄로 이어졌다. 화면에 「장축 화물차」라는 오래된 분류가 잠깐 떴다.',fx:{time:20,scrap:-1,combatEdge:1,combatRead:{label:'센서가 한 차량으로 보는 긴 윤곽',tactics:['차체 지지','인력 릴레이']},chain:'route_market_pass'},sfx:'cover'},
    {p:1,text:'바람이 천막을 들췄다. 이어 놓은 윤곽이 가운데서 끊겼다.\n\n화면 분류가 「장축 화물차」에서 「다중 개체」로 바뀌었다가, 돌아왔다가, 또 바뀌었다.\n\n"저거 계속 헷갈리는 중이에요." 아이가 속삭였다. 헷갈리는 기계는 대개 사람을 부른다.',fx:{time:35,scrap:-2,combatPressure:2,combatRead:{label:'윤곽이 끊겨 센서가 개체 수를 다시 센다',tactics:['위장']},chain:'route_market_pass'},sfx:'warning'}]},
  {label:'각 수레의 움직임을 손신호로 맞춘다',tactic:'지휘',terrainFit:1,combatRoll:.58,out:[
    {p:1,text:'운전석 거울로 뒤를 보며 손을 들었다 내렸다. 다섯 명이 같은 순간에 밀고, 같은 순간에 멈췄다. 센서가 사람을 세지 못하고 바퀴만 셌다.',fx:{time:15,combatEdge:1,combatRead:{label:'센서가 놓치는 한 박자의 정지',tactics:['차체 지지','인력 릴레이']},chain:'route_market_pass'},sfx:'silence'},
    {p:1,text:'세 번째 수레가 반 박자 늦었다. 한 명이 늦으면 뒤가 전부 늦는다.\n\n행렬이 아코디언처럼 늘어졌다 줄었다 했다. 센서 불빛이 그 리듬을 따라 좌우로 흔들렸다.\n\n"제가 늦었어요." 늙은 목소리가 작게 말했다. 아무도 대꾸하지 않은 건 탓하지 않으려고였다.',fx:{time:30,combatPressure:2,combatRead:{label:'행렬 간격이 들쭉날쭉해 한 박자를 못 만든다',tactics:['지휘']},chain:'route_market_pass'},sfx:'warning'}]},
  {label:'달구지 발전기로 센서 주기를 흐트러뜨린다',tactic:'교란',noise:1,risk:'관측 신호가 남을 수 있다',combatRoll:.55,out:[
    {p:1,text:'발전기 회전을 올렸다 내리자 센서 화면에 가는 줄이 번졌다. 완전히 꺼지지는 않았지만, 사람 윤곽이 겹쳐 보였다.',fx:{fuel:-1,combatPressure:1,chain:'route_market_pass'},sfx:'engine'},
    {p:1,text:'회전을 너무 올렸다. 발전기 소리가 국도 전체에 퍼졌고, 센서는 오히려 또렷해졌다.\n\n화면 구석에 작은 글자가 떴다. 「전자 간섭 감지 · 기록」\n\n장터 대표가 조용히 말했다. "저 기록은 지울 수 없어요."',fx:{fuel:-2,combatPressure:2,pursuit:1,chain:'route_market_pass'},sfx:'warning'}]}
 ]},
{id:'route_market_pass',type:'호송',w:0,fixed:true,once:true,scene:'route-market-convoy',
 title:'차단봉 아래의 통과 순서',
 combat:{kind:'호송',phase:3,total:3,step:'통과시키기',
   threat:'잠든 자동 검문소',objective:'행렬을 끊지 않고 차단봉 아래로 빼낸다',terrain:'좁은 국도와 폐차 차양, 고장 난 차단봉',stakes:'마지막 수레가 걸리면 앞사람도 돌아와야 한다',intent:'노란 센서가 재검사로 바뀌기 전에 걸린 셋째 수레를 빼내야 한다',counters:{'차체 지지':'봉을 들어 행렬을 그대로 민다','인력 릴레이':'짐 높이를 낮춰 흐름을 잇는다'}},
 text:'달구지 앞바퀴가 검문선을 넘었다. 차단봉은 반쯤 열린 채 떨리고 있다. 첫 수레는 지났고, 셋째 수레가 낮은 봉 아래에서 짐에 걸렸다.\n\n수레를 끌던 운송 담당자가 뒤에서 말했다. "짐을 여기 두면 사람들만 먼저 건널 수 있어요."\n\n"뭘 두고 가요?"\n\n"씨앗하고 약이요."\n\n무주 장터 대표가 고개를 저었다. "저 씨앗은 내년 봄 농사에 쓸 겁니다. 사람도 짐도 함께 건너야 이 장터가 계속돼요."\n\n센서 불이 노란색으로 바뀌었다. 이제 오래 멈출 수 없다.',
 choices:[
  {label:'달구지로 봉을 받치고 수레를 밀어낸다',tactic:'차체 지지',terrainFit:2,combatRoll:.58,out:[
    {p:1,text:'달구지 지붕 가드를 봉 아래에 밀어 넣었다. 차체가 끼익 울었지만 봉이 손 한 뼘 올라갔다. 다섯 수레가 하나씩 빠져나왔다.\n\n마지막 사람이 넘어오자 센서가 다시 초록으로 돌아갔다. 이름 하나 남기지 않고, 봄에 심을 씨앗은 전부 건넜다.',fx:{time:20,van:-2,food:2,water:2,moodAll:4,combatEnd:1,combatResult:'success',flag:'route_market_escorted',note:{type:'사건',title:'다섯 수레의 장터길',body:'달구지를 지지대로 써 사람과 씨앗, 약을 모두 기록 없이 통과시켰다.',links:['달구지']}}},
    {p:1,text:'사람과 수레는 모두 건넜지만 봉이 떨어지며 소금 자루 하나가 터졌다. 길 위의 소금을 주워 담을 시간은 없었다.\n\n대표가 남은 자루를 확인했다. "씨앗하고 약은 남았어요. 이 정도면 장터를 다시 열 수 있습니다."',fx:{time:25,van:-4,food:1,moodAll:2,combatEnd:1,combatResult:'partial',flag:'route_market_escorted_partial'}},
    {p:1,text:'차체가 봉의 무게를 놓쳤다. 차단봉이 셋째 수레 위로 떨어지며 센서가 빨간불로 바뀌었다.\n\n<span class="ai">"이동 인원 재검사. 기록을 시작합니다."</span>\n\n사람들은 수레를 버리고 흩어져 건넜다. 씨앗 두 자루가 검문선 안쪽에 남았고, 장터 사람 다섯의 윤곽이 어딘가의 기록에 남았다.\n\n대표는 아무도 탓하지 않았다. 그게 더 아팠다.',fx:{time:30,van:-6,moodAll:-5,pursuit:1,combatEnd:1,combatResult:'failure',flag:'route_market_failed',note:{type:'사건',title:'기록에 남은 행렬',body:'차단봉이 떨어져 씨앗 두 자루를 잃었고 장터 사람들의 이동 기록이 중앙망에 남았다. 다음 장이 열릴지는 아무도 장담하지 못했다.',links:['천리안']}}}]},
  {label:'짐 높이를 낮추고 전원이 손으로 넘긴다',tactic:'인력 릴레이',terrainFit:2,combatRoll:.64,out:[
    {p:1,text:'씨앗 자루와 약 상자를 봉 너머 손에서 손으로 옮겼다. 빈 수레를 눕혀 밀고, 건너편에서 다시 실었다.\n\n센서가 깨어났을 때는 마지막 편지 다발까지 달구지 안에 들어온 뒤였다. 장터 사람들의 이름은 어디에도 남지 않았다.',fx:{time:35,fatigue:4,food:2,water:2,moodAll:4,combatEnd:1,combatResult:'success',flag:'route_market_escorted'}},
    {p:1,text:'사람과 약, 씨앗은 모두 넘겼다. 수레 하나의 축이 꺾여 남은 짐은 달구지 지붕에 나눠 실었다.\n\n행렬은 짧아졌지만 끊기지는 않았다.',fx:{time:40,fatigue:5,food:1,moodAll:2,combatEnd:1,combatResult:'partial',flag:'route_market_escorted_partial'}},
    {p:1,text:'릴레이 중간에 센서가 깨어났다. 손에서 손으로 넘어가던 사람의 줄이 끊기며, 마지막 두 명이 검문선 안쪽에 갇혔다.\n\n두 사람이 반대편 배수로로 빠져나오는 데 한 시간이 걸렸다. 씨앗 한 자루는 못 갖고 나왔고, 센서는 그동안 내내 켜져 있었다.\n\n"장터는 다시 열 겁니다." 대표의 목소리는 확신보다 고집에 가까웠다.',fx:{time:70,fatigue:8,moodAll:-5,pursuit:1,combatEnd:1,combatResult:'failure',flag:'route_market_failed',note:{type:'사건',title:'끊긴 릴레이',body:'센서가 깨어나 두 사람이 갇혔다 빠져나왔다. 씨앗 한 자루와 한 시간, 그리고 기록이 남았다.',links:['천리안']}}}]}
 ]},

{id:'settlement_road_echo',type:'여파',w:0,fixed:true,scene:'settlement-road-echo',
 title:'먼저 지나간 달구지의 흔적',
 text:()=>D.roadEchoCopy(S,'text'),
 choices:[
  {label:'차를 세우고 마지막 구간을 함께 정리한다',out:[{p:1,text:()=>D.roadEchoCopy(S,'outcome')+'\n\n우리는 잠깐 늦어졌지만, 그 길을 쓰는 사람은 한 팀 더 늘었다.',fx:{impactEcho:'assist'}}]},
  {label:'무전과 지도로 다음 구간만 이어 준다',out:[{p:1,text:()=>D.roadEchoCopy(S,'outcome')+'\n\n달구지는 먼저 움직였고, 뒤의 수레는 우리가 알려 준 표식을 따라왔다.',fx:{impactEcho:'relay'}}]},
  {label:'멈추지 않고 북쪽으로 계속 간다',out:[{p:1,text:()=>D.roadEchoCopy(S,'outcome')+'\n\n지금은 서울로 가야 한다. 다만 백미러에서 그 행렬이 사라질 때까지 속도를 조금 늦췄다.',fx:{impactEcho:'pass'}}]}
 ]},

/* ═════ 위수 구역 — 초계와 무기 ═════ */

{id:'perimeter_first', type:'스토리', w:0, fixed:true, ai:1,
 title:'위수 구역',
 scene:'combat-walker-watch-v1', sfx:'warning',
 text:'도로 한복판에— 그것이 서 있다.\n\n4족 보행기. 소만 한 크기. 도색은 관공서 회색. 몸통의 렌즈가 차를 향해 조리개를 조인다.\n\n<span class="ai">"정지. 위수 구역입니다."</span>\n\n차를 훑는 초록 스캔선. 그리고—\n\n탕. 경고사격이 차 옆 아스팔트를 때렸다. 기계가 처음으로, 우리에게 무기를 겨눴다.\n\n<span class="ai">"등록되지 않은 차량. 다음 확인 시 회차를 강제합니다. 좋은 하루 되세요."</span>\n\n보행기는 유유히 갓길로 물러나 도로를 열어줬다.',
 choices:[
  {label:'…지나간다', out:[{p:1, text:'보행기가 물러난 뒤에도 한동안 핸들을 놓지 못했다. 그제야 생각이 문장으로 굳었다.\n\n남쪽은 그것의 \'바깥\'이었다. 여긴 \'안\'이다.\n\n차에서 내려 옆판을 살폈다. 경고탄에 튄 아스팔트 파편이 외판을 찍고 지나갔다. 패인 자국을 장갑 낀 손으로 쓸어 봤다.\n\n뒤 칸의 고철과 공구를 손 닿는 곳으로 옮겼다. 맨손으로 다닐 땅이 아니었다.', fx:{van:-6, flag:'armed_age', pursuit:1, note:{type:'사건',title:'첫 경고사격',body:'위수 구역의 경고탄에 튄 파편이 차 외판을 상하게 했다. 뒤 칸의 고철과 공구를 손 닿는 곳으로 옮겼다.',links:['천리안']}}}]},
 ]},

{id:'patrol_walker', minParty:1, type:'추적', w:10, region:['north'], needFlag:'armed_age',
 title:'초계 보행기', scene:'combat-walker-watch-v1',
 combat:{phase:1,total:3,step:'정찰',
   threat:'4족 초계 보행기',terrain:'폐차 행렬과 콘크리트 분리대',pressure:1,
   objective:'렌즈가 돌아오기 전에 자리를 잡는다',stakes:'경보가 북쪽 검문망으로 넘어간다',intent:'몸통 렌즈가 정면 차선을 훑은 뒤 왼쪽 폐차 행렬로 돌아온다',counters:{'엄폐':'폐차로 시야를 끊는다','유인':'스캔 방향을 옆 차선에 묶는다'}}, sfx:'scan',
 text:'언덕 너머에서 회색 몸통이 먼저 보였다. 네 다리는 아직 경사 아래에 있다.\n\n이제 저 발소리는 안다. 한 걸음, 멈춤, 좌우 스캔. 다시 한 걸음.\n\n렌즈가 이쪽으로 돌아오기까지 30초쯤.',
 choices:[
  {label:'폐차 행렬 뒤로 달구지를 붙인다', tactic:'엄폐', prep:1, out:[{p:1, text:'시동을 죽이고 녹슨 화물차 그림자에 바짝 붙였다.\n\n보행기의 렌즈가 도로를 훑었다. 아직은 우리 앞쪽만 본다. 먼저 볼 수 있는 쪽이 조금 유리하다.', fx:{time:5,combatStart:{id:'walker',threat:'4족 초계 보행기',terrain:'폐차 행렬과 콘크리트 분리대',objective:'렌즈와 관절을 읽고 전원을 안전하게 회수한다',stakes:'경보가 북쪽 검문망으로 넘어간다',pressure:1},combatEdge:1,combatPressure:-1,chain:'combat_walker_read'}, sfx:'cover'}]},
  {label:'달구지로 시선을 끌고 옆 차선에 세운다', tactic:'유인', prep:1, risk:'차체가 노출된다', out:[{p:1, text:'헤드라이트를 한 번 켰다 껐다. 렌즈가 즉시 달구지를 물었다.\n\n차를 콘크리트 분리대 옆으로 밀어 세웠다. 숨을 곳은 줄었지만, 놈이 어디를 보는지는 이제 완전히 분명해졌다.', fx:{van:-2,combatStart:{id:'walker',threat:'4족 초계 보행기',terrain:'폐차 행렬과 콘크리트 분리대',objective:'렌즈와 관절을 읽고 전원을 안전하게 회수한다',stakes:'경보가 북쪽 검문망으로 넘어간다',pressure:1},combatEdge:2,combatPressure:1,chain:'combat_walker_read'}, sfx:'engine'}]},
  {label:'농로로 빠져 교전을 버린다', tactic:'이탈', prep:1, out:[{p:1, text:'후진으로 갈림길까지 빠져나온 뒤 농로로 차를 꺾었다.\n\n백미러 속에서 보행기가 몸통을 돌렸다. 도망치는 것은 서 있는 것보다 잘 보인다. 렌즈가 우리 뒤꽁무니를 오래 따라왔다.\n\n멀리 돌아가면 된다. 다만 이 길에 우리가 있었다는 건 어딘가에 적혔다.', fx:{time:35,fuel:-3,moodAll:-3,pursuit:1,combatEnd:1,note:{type:'사건',title:'등을 보인 자리',body:'보행기를 피해 농로로 빠졌다. 후퇴하는 차는 서 있는 차보다 잘 읽힌다.',links:['천리안']}}, sfx:'escape'}]},
 ]},

{id:'combat_walker_read', type:'추적', w:0, fixed:true, ai:1,
 title:'발을 읽는 시간', scene:'combat-walker-watch-v1',
 combat:{phase:2,total:3,step:'대응',difficulty:-1,baseChance:0.56,
   threat:'4족 초계 보행기',terrain:'폐차 사이 관절 사각',
  objective:'한 번뿐인 공격 각도를 만든다',stakes:'서두르면 총구가 먼저 돌아온다',intent:'세 번째 걸음 뒤 오른쪽 앞다리에 하중이 쏠리며 몸통이 내려간다',counters:{'관찰':'보폭의 빈 박자를 확인한다','정비':'유압관의 전도 방향을 읽는다','사격':'관절 사각을 먼저 잡는다'}}, sfx:'walker',
 text:'쿵. 왼발. 잠깐 멈춤. 쿵. 오른발.\n\n놈은 빠르지 않다. 대신 몸통 렌즈와 다리 센서가 서로의 빈틈을 메운다. 아무 데나 치면 경보만 울릴 것이다.\n\n당장 뛰쳐나가고 싶은 마음을 눌렀다. 한 번만 더 보자. 같은 걸음을 반복한다면 틈도 다시 올 것이다.',
 choices:[
  {label:'발을 내딛는 박자를 끝까지 센다', combatRoll:.64, tactic:'관찰', foreseeable:{lasting:'다음 교전에서 교란 타이밍으로 이어진다'}, out:[
    {p:1, text:'세 번째 걸음마다 오른쪽 앞다리에 체중이 몰린다. 그때 몸통이 아주 조금 아래로 처진다.\n\n짧지만, 센서 앞의 다른 열원에 고개가 돌아갈 만큼은 되는 틈이다.', fx:{time:4,combatEdge:1,combatPressure:-1,combatRead:{label:'세 번째 걸음 뒤 몸통이 처지는 순간',tactics:['교란']},chain:'combat_walker_strike'}, sfx:'heartbeat'},
    {p:1, text:'마침 그 순간이 지나간 뒤였다. 보행기는 우리 쪽을 더 오래 바라봤고, 경보음이 먼저 들렸다.\n\n놈이 폐차 쪽으로 몸을 틀었다. 움직일 시간이 줄었다.', fx:{combatEdge:-2,combatPressure:2,combatRead:{label:'두 번째 박자 뒤 읽기가 늦어짐',tactics:[]},chain:'combat_walker_strike'}, sfx:'warning'}]},
  {label:'민지가 유압관의 흔들림을 찾는다', combatRoll:.67, tactic:'정비', req:{healthyComp:'minji'}, foreseeable:{lasting:'다음 교전에서 근접 제압으로 이어진다'}, out:[
    {p:1, text:'민지는 무릎 대신 다리 안쪽의 가느다란 관을 가리켰다.\n\n"저기 밸브를 꺾으면 서는 게 아니라 주저앉아요. 넘어지는 방향만 조심해요."\n\n우리는 놈이 쓰러질 자리를 먼저 비웠다.', fx:{combatEdge:2,combatRead:{label:'유압관이 접히며 오른쪽으로 주저앉는 방향',tactics:['근접']},chain:'combat_walker_strike',mood:{minji:2}}, sfx:'tool'},
    {p:1, text:'민지가 느슨한 관을 찾기 전에 보행기의 렌즈가 우리 쪽으로 돌아왔다.\n\n다리 안쪽이 몸통에 가렸다. 놈이 한 걸음 가까워지자 경보음도 빨라졌다.', fx:{combatEdge:-2,combatPressure:2,combatRead:{label:'시점이 늦어져 준비 동작이 길어짐',tactics:[]},chain:'combat_walker_strike',mood:{minji:1}}, sfx:'tool'}]},
  {label:'강우가 관절 사각을 짚는다', combatRoll:.6, tactic:'사격', req:{healthyComp:'kangwoo'}, foreseeable:{lasting:'다음 교전에서 사격 각도로 이어진다'}, out:[
    {p:1, text:'강우의 손가락이 오른쪽 앞다리, 몸통 렌즈, 다시 오른쪽 앞다리를 찍었다.\n\n"한 발로 세우고, 다음에 움직여. 두 번째 발을 미리 쓰지 마."\n\n말수가 짧아질수록 그가 확실하다는 뜻이었다.', fx:{combatEdge:2,combatRead:{label:'오른쪽 앞다리 관절이 완전히 드러나는 한 박자',tactics:['사격']},chain:'combat_walker_strike',mood:{kangwoo:2}}, sfx:'bolt'},
    {p:1, text:'강우가 손을 들었지만 관절은 이미 몸통 뒤로 가려졌다. 렌즈가 우리 쪽에 멈췄다.\n\n강우가 손을 내리고 엄폐물 뒤로 몸을 낮췄다. 다음 각도를 기다릴 여유가 없다.', fx:{combatEdge:-2,combatPressure:2,combatRead:{label:'사격 타이밍을 하나 놓침',tactics:[]},chain:'combat_walker_strike'}, sfx:'bolt'}]},
  {label:'더 다가오기 전에 끝낸다', combatRoll:.44, tactic:'돌입', risk:'각도가 나쁘다', foreseeable:{exposure:'몸을 먼저 드러낸다',lasting:'다음 교전의 전세와 압박으로 이어진다'}, out:[
    {p:1, text:'생각할 시간을 끊고 먼저 몸을 일으켰다.\n\n렌즈가 폐차 쪽으로 돌아가는 동안 분리대 안쪽까지 파고들었다. 놈도 우리 위치를 잡았지만, 총구가 따라오기 전 밸브까지 닿을 짧은 거리를 먼저 벌었다.', fx:{combatEdge:2,combatPressure:1,combatRead:{label:'렌즈가 되돌아오기 전 분리대 안쪽 사각',tactics:['근접']},chain:'combat_walker_strike'}, sfx:'warning'},
    {p:1, text:'보행기는 우리 의도를 놓치지 않았다. 렌즈가 우리 쪽으로 돌아왔고, 경보가 즉시 시작됐다.\n\n각도가 어긋나면서 더 불리한 자리로 밀렸다.', fx:{combatEdge:-2,combatPressure:2,combatRead:{label:'거리 계산이 틀어져 기동 시간이 줄어듦',tactics:['돌입']},chain:'combat_walker_strike'}, sfx:'impact'}]},
 ]},

{id:'combat_walker_strike', type:'추적', w:0, fixed:true, ai:1,
 title:'렌즈가 돌아오는 순간', scene:'combat-walker-watch-v1',
 combat:{phase:3,total:3,step:'교전',threat:'4족 초계 보행기',terrain:'오른쪽 앞다리와 비워 둔 전도 방향',
  objective:'제압하거나 달구지까지 살아서 물러난다',stakes:'총구가 돌아오면 차와 사람이 함께 노출된다',intent:'붉은 렌즈가 먼저 사람을 고정하고 한 박자 뒤 총구가 같은 방향으로 따라온다',counters:{'사격':'렌즈나 관절을 먼저 끊는다','교란':'렌즈가 목표를 고정하지 못하게 한다'}}, sfx:'warning',
 text:'렌즈 안쪽에서 붉은 점이 켜진다.\n\n<span class="ai">"미등록 인원. 행동을 중지하십시오."</span>\n\n말은 정중했지만 총구는 그렇지 않았다. 지금 고른 한 동작 뒤에는 되감기가 없다.',
 choices:[
  {label:'석궁으로 몸통 렌즈를 끊는다', tactic:'사격', terrainFit:1, req:{item:'석궁',item2:'볼트'}, foreseeable:{expense:'볼트 1발'}, combatRoll:.54, out:[
    {p:1, scene:'combat-walker-disabled-v2', text:'숨을 멈추고 당겼다.\n\n퓩. 볼트가 렌즈 테두리에 박혔다. 붉은 점이 허공을 두 번 훑더니 꺼졌다. 보행기는 한쪽 무릎을 접고 그대로 멎었다.\n\n가까이 가서 멎은 렌즈를 확인하고서야 숨을 내쉬었다.', fx:{item:{'볼트':-1,'부품':1},scrap:6,combatEnd:1,note:{type:'사건',title:'렌즈를 끊은 한 발',body:'보행기의 보폭을 읽고 몸통 렌즈를 끊었다. 싸움은 발사보다 오래 준비됐다.',links:['천리안']}}, sfx:'crossbow'},
    {p:1, text:'줄이 손가락을 스쳤다. 볼트는 렌즈 옆 철판에서 튕겼다.\n\n경고탄이 폐차 문짝을 찢었다. 달구지까지 뛰어들어 후진으로 빠졌다. 손바닥이 벌어졌지만 운전대는 놓치지 않았다.', fx:{item:{'볼트':-1},fuel:-4,van:-7,pursuit:1,injury:{who:'driver',label:'손바닥 열상',days:2},combatEnd:1}, sfx:'impact'}]},
  {label:'쇠파이프로 다리 밸브를 꺾는다', tactic:'근접', terrainFit:2, req:{item:'쇠파이프'}, risk:'근접 부상', foreseeable:{lasting:'근접한 위치가 결과까지 이어진다'}, combatRoll:.45, out:[
    {p:1, scene:'combat-walker-disabled-v2', text:'다리가 내려오는 박자에 맞춰 안쪽으로 파고들었다.\n\n쇠파이프를 밸브와 프레임 사이에 끼우고 온몸으로 눌렀다. 금속이 비명을 질렀고, 보행기는 우리가 비워 둔 쪽으로 쓰러졌다.', fx:{scrap:7,item:{'부품':1},fatigue:8,combatEnd:1}, sfx:'metal'},
    {p:1, text:'밸브는 휘었지만 다리는 멈추지 않았다.\n\n옆으로 구르는 순간 발끝이 어깨를 스쳤다. 경고탄이 머리 위 폐차 문짝에 박혔다. 나는 그 아래로 기어 달구지까지 물러났다.', fx:{fatigue:10,van:-4,pursuit:1,injury:{who:'driver',label:'어깨 타박',days:3},combatEnd:1}, sfx:'hit'}]},
  {label:'화염병으로 센서 앞에 열벽을 만든다', tactic:'교란', terrainFit:1, noise:1, req:{item:'화염병'}, foreseeable:{expense:'화염병 1개 · 연료 소모',exposure:'불빛과 연기가 남는다'}, combatRoll:.64, out:[
    {p:1, text:'병은 보행기가 아니라 그 앞 아스팔트에서 깨졌다.\n\n검은 연기와 불꽃이 센서를 가렸다. 놈이 빈 열원을 향해 몸통을 돌리는 동안 달구지는 반대편으로 빠져나갔다.', fx:{item:{'화염병':-1},fuel:-2,moodAll:2,combatEnd:1}, sfx:'fire'},
    {p:1, text:'바람이 불길을 너무 빨리 눕혔다. 센서가 다시 달구지를 잡았다.\n\n경고탄 하나가 적재함 외벽을 뚫었다. 불길이 번지기 전에 떨쳐냈지만 차 안에는 탄내가 오래 남았다.', fx:{item:{'화염병':-1},fuel:-4,van:-9,pursuit:1,combatEnd:1}, sfx:'hit'}]},
  {label:'강우가 앞다리 관절에 한 발 쓴다', tactic:'사격', terrainFit:2, noise:1, req:{healthyComp:'kangwoo',item:'탄약'}, foreseeable:{expense:'탄약 1발',exposure:'총성이 남는다'}, combatRoll:.62, out:[
    {p:1, scene:'combat-walker-disabled-v2', text:'"오른발 들면 간다."\n\n쿵. 오른발이 들렸다. 탕.\n\n관절핀 하나가 정확히 빠져나왔다. 보행기가 옆으로 무너지자 강우는 탄피보다 먼저 우리 얼굴부터 확인했다. "다 있지?" 그제야 소총을 내렸다.', fx:{item:{'탄약':-1,'부품':1},scrap:5,mood:{kangwoo:5},combatEnd:1,note:{type:'사건',title:'한 발 뒤의 확인',body:'강우는 보행기를 쓰러뜨린 뒤 탄피보다 먼저 사람 수를 셌다.',links:['강우']}}, sfx:'rifle'},
    {p:1, text:'방아쇠를 당기는 순간 보행기가 몸을 틀었다. 탄은 관절 옆을 긁었다.\n\n강우가 두 번째 탄 대신 우리를 밀어 엄폐시켰다. 파편이 그의 옆구리를 때렸다. 그는 끝까지 걸어서 차에 탔다.', fx:{item:{'탄약':-1},fuel:-3,pursuit:1,injury:{who:'kangwoo',label:'옆구리 파편상',days:3},combatEnd:1}, sfx:'hit'}]},
  {label:'제압을 포기하고 달구지로 물러난다', tactic:'이탈', prep:1, foreseeable:{expense:'연료 4L · 차체 내구 3',exposure:'번호판과 도주로가 기록된다',lasting:'관측 기록이 이후 검문에 남는다'}, out:[{p:1, text:'몸을 낮춰 달구지까지 뒤로 빠졌다. 문을 닫자마자 기어를 넣었다.\n\n보행기는 따라오지 않았다. 대신 붉은 렌즈가 번호판 높이에서 한 박자 멈췄다. 읽은 것이다.\n\n사정거리 밖까지 가서야 핸들을 쥔 손을 펴 봤다. 오늘은 살아서 빠져나온 것으로 됐다.', fx:{fuel:-4,van:-3,moodAll:-2,pursuit:1,combatEnd:1,note:{type:'사건',title:'읽힌 번호판',body:'보행기 제압을 포기하고 물러났다. 물러나는 동안 렌즈가 번호판 높이에서 멈췄다.',links:['천리안','달구지']}}, sfx:'escape'}]},
 ]},

{id:'patrol_swarm', type:'추적', w:9, region:['north'], needFlag:'armed_age',
 title:'세 개의 그림자', scene:'combat-drone-swarm',
 combat:{phase:1,total:3,step:'정찰',
   threat:'초계 쿼드 편대',terrain:'오래된 터널과 고가 아래 폐차 지대',pressure:1,
   objective:'편대가 닫히기 전에 도주선을 고른다',stakes:'세 기체가 사격 각도를 닫으면 차가 포위된다',intent:'양옆 기체가 차선을 벌려 달구지를 가운데 지휘기 앞으로 몬다',counters:{'이탈':'좁은 터널로 편대 폭을 줄인다','엄폐':'폐차 사이에서 한 줄로 들어오게 한다'}}, sfx:'drone',
