/* ── 후속: 커피 두 잔 (대양 외상 갚기) ── */
{id:'exp_coffee', minParty:1, type:'탐색', w:8, once:true, needFlag:'van_owner_done',
 title:'폐카페의 금고',
 text:'로스터리 카페 폐허. 머신은 죽었고 잔은 다 깨졌는데—\n\n창고에서 밀봉 원두 봉투가 나왔다. 질소 충전 포장. 볶은 날짜는 오래전이지만 밀봉은 살아 있다.\n\n누가 봉투를 코에 대더니 눈이 커졌다. "…이거 아직 커피 냄새 나."\n\n커피. 커피 두 잔. 다들 동시에 같은 외상 장부를 떠올렸다.',
 choices:[
  {label:'원두를 챙긴다', out:[{p:1, text:'봉투를 보물처럼 모셨다. 짐칸이 아니라 조수석 서랍— 남산행 편지 옆자리다.\n\n「수리비는 커피 두 잔. 외상.」\n\n외상이라고 적어 둔 쪽지가 서랍 안에서 편지와 나란히 흔들렸다.', fx:{item:{'커피 원두':1}, flag:'coffee_found', moodAll:3, note:{type:'사건',title:'질소 충전의 기적',body:'여러 해를 버틴 밀봉 원두. 조수석 서랍, 편지 옆자리. 외상 갚을 준비 완료.',links:['정비공 대양']}}}]},
 ]},

{id:'vanowner_coffee', type:'조우', w:12, once:true, needFlag:'coffee_found',
 title:'외상 청산',
 text:'장터에서 낯익은 뒷모습— 고무 대야에 고구마. 대양이다.\n\n"어, 그 차." 대양이 손을 들다가, 우리가 내민 것을 보고 멈췄다.\n\n원두 봉투. 그리고 물 끓인 주전자.\n\n"…이 냄새." 대양의 표정이 이십 년쯤 젊어졌다.',
 choices:[
  {label:'두 잔을 내린다', out:[{p:1, text:'깡통을 뚫어 만든 드리퍼로, 세상에서 제일 정성스러운 두 잔이 내려졌다.\n\n대양은 첫 모금을 오래 물고 있었다. "그 양반이랑 마신 게 마지막이었는데. 커피란 걸."\n\n두 잔째를 비우고 대양이 주머니에서 꼬깃한 종이를 꺼냈다— 외상 장부(라기보다 영수증 뒷면)였다. 그리고 두 줄을 그었다.\n\n"청산. 이자는—" 대양이 남은 원두 봉투를 도로 밀어줬다. "이자는 됐고, 원금도 반만 받지. 나머지 반은 남산 가서 마셔. 그 양반 몫으로."\n\n장부는 우리가 기념으로 받았다. 일지에 붙일 자리는 이미 정해져 있었다.', fx:{time:50, moodAll:8, flag:'coffee_paid', note:{type:'사건',title:'외상 청산',body:'이십몇 년 묵은 커피 두 잔을 갚았다. 원금 반은 남산에서, 할아버지 몫으로. 장부는 일지에.',links:['정비공 대양','할아버지','남산']}}}]},
 ]},

/* ── 후속: 한별의 서고 (library_done) ── */
{id:'library_scribe', type:'조우', w:10, once:true, needFlag:'library_done',
 title:'소장 요청',
 text:'이동 도서관을 다시 만났다. 이번엔 버스에 사다리가 걸쳐 있고, 한별이 지붕에서 방수포를 고치고 있다.\n\n"마침! 잘 왔어요!" 한별이 내려와 손을 닦더니, 이상하게 격식을 차린 자세로 말했다.\n\n"부탁이 있는데— 여러분 일지요. 그거, 필사해서 소장하고 싶어요. 도서관에."',
 choices:[
  {label:'"우리 일지를? 왜요?"', out:[{p:1, text:'"기록이잖아요. 지금 이 시대를 길에서 직접 쓴." 한별이 버스 안 서가를 가리켰다. "여긴 다 옛날 책이에요. 세상이 무너지기 전 이야기. 그다음 이야기를 쓴 책이— 없어요. 여러분 기록이 첫 권이에요."\n\n"글씨 엉망인데 괜찮아요?"\n\n"네? 아, 필사는 제가 해요. 오늘은 앞부분만 옮길게요. 몇 시간 빌려주실 수 있어요?" 한별은 아까부터 계속 손을 닦고 있었다.\n\n버스 곁에 자리를 잡았다. 다섯 시간 동안 한별이 일지 앞부분을 정성껏 필사하고, 원본을 돌려줬다. 표지엔 손글씨 제목.\n\n「서울까지 400km — 어느 차의 기록 (제1권, 미완)」\n\n"미완이 중요해요." 한별이 책등을 쓰다듬었다. "완결되면 2권 필사하러 갈 테니까, 어디서든 살아 있어요."', fx:{time:300, moodAll:7, flag:'library_scribed', note:{type:'사건',title:'제1권, 미완',body:'우리 일지 앞부분이 이동 도서관 소장 도서가 됐다. 원본은 돌려받았다. 조건: 2권 필사를 위해 살아 있을 것.',links:['이동 도서관']}}}]},
  {label:'"부끄러운데…"', out:[{p:1, text:'"부끄러운 기록이 제일 정확한 기록이에요." 사서의 반박은 짧고 이길 수 없었다.\n\n결국 필사를 허락했다. 단, 내가 민망해하는 대목에는 짧은 각주를 붙이는 조건으로.\n\n네 시간 동안 한별이 앞부분을 옮겼다. 각주까지 다 쓴 뒤 원본을 내게 돌려줬다.', fx:{time:240, moodAll:5, flag:'library_scribed', note:{type:'사건',title:'각주 조건부 소장',body:'일지 앞부분을 필사해 소장했다. 민망한 대목에는 각주를 달고, 원본은 돌려받았다.',links:['이동 도서관']}}}]},
 ]},

/* ── 후속: L의 두 번째 (freq400_done) ── */
{id:'freq_L2', type:'발견', w:8, once:true, needFlag:'freq400_done', region:['north'],
 title:'두 번째 릴',
 text:'북부의 낡은 소방 망루. 꼭대기에 낯익은 솜씨의 안테나가 보인다— 구리선과 낚싯대.\n\n급수탑에서 봤던 것과 같은 방식이다. 이번 것엔 릴테이프가 하나 더 걸려 있다. 라벨: 「여기까지 온 사람에게」',
 choices:[
  {label:'재생한다', out:[{p:1, text:'"여기까지 들었다면, 거의 다 왔습니다." 같은 목소리. 숨소리가 섞인.\n\n"한 가지 정정합니다. 목록이 명단이라고 생각했는데— 아닐지도 모릅니다. 그건 아마—"\n\n테이프가 거기서 끊겼다. 물리적으로. 누가 끊은 건지 낡아서 끊긴 건지 알 수 없게.\n\n남은 릴엔 이어붙인 흔적과 매직 글씨. "뒷부분은 직접 확인하세요. 저도 그러러 갑니다. — L"', fx:{flag:'freq_L2_heard', pursuit:1, note:{type:'소문',title:'끊긴 테이프',body:'"목록은 명단이 아닐지도 모릅니다. 그건 아마—" 녹음은 여기서 끊겼다. L도 직접 확인하러 간다는 글씨를 남겼다. 행선지는 적혀 있지 않다.',links:['천리안','주파수 4-0-0']}}}]},
 ]},

/* ── 후속: 만수 상회 개업 (단골 4회+) ── */
{id:'mansu_opening', minParty:1, type:'조우', w:11, once:true, needFlagMin:['mansu',4], noFlag:'mansu_hurt', nearNode:['busan','miryang','daegu','muju','jeonju','daejeon','suwon','gwangju'],
 title:'만수 상회',
 text:'정착지 어귀에 새 간판이 걸려 있다. 페인트 냄새가 아직 난다.\n\n「만수 상회 — 트럭 시절 단골 우대」\n\n가게 앞에서 만수가 개업 테이프를 만지작거리고 있다. 개업식인데 하객이 없다.\n\n"어— 어!! 왔네!! 최다 단골!!" 만수가 우리를 보고 테이프를 흔들었다.',
 choices:[
  {label:'개업을 축하하고 물건도 산다 (고철 2)', req:{scrap:2}, out:[{p:1, text:'달구지 일행이 하객 전원이었다. 가위를 아무도 안 챙겨서 테이프는 손으로 끊게 됐다.\n\n"원래 이거 누가 끊는 거지?" "제일 높은 사람이요." "그럼 만수 씨죠." "나 사장인데, 그럼 내가 나한테 끊어주는 건가?" 결론은 안 났고 모두 같이 잡아당겨 요란하게 끊겼다.\n\n"트럭이 너무 낡아서. 이제는 내가 찾아가는 게 아니라, 손님이 와야지." 만수가 가게를 둘러봤다. 트럭 짐칸이 통째로 진열대가 돼 있었다.\n\n고철 두 개를 내고 식량과 부품을 샀다. 만수는 첫 손님이라며 봉투를 묵직하게 채웠다. 개업 선물로는 소식벽에 쓸 홍보 문구를 골랐다. "만수 상회 개업. 트럭 시절 그 만수 맞음. 여전히 안 속임."\n\n"안 속임이 제일 좋은 광고네." 만수가 진지하게 감동했다.', fx:{scrap:-2, food:3, item:{'부품':1}, moodAll:6, flag:'mansu_shop', note:{type:'사건',title:'만수 상회 개업식',body:'달구지 일행이 하객 전원. 테이프 커팅은 요란했다. 홍보 문구: "여전히 안 속임."',links:['만수']}}}]},
  {label:'물건은 사지 않고 개업을 축하한다', out:[{p:1, text:'물건 대신 개업식에 손을 보탰다. 만수와 함께 테이프를 잡아당기니 생각보다 큰 소리가 났다.\n\n"가위 없어도 되네. 소리는 이쪽이 낫다!"\n\n진열대 사이로 들어간 만수가 빈 벽을 보며 머리를 긁었다. 소식벽에 붙일 광고가 아직 없단다. 종이 한 장을 받아 적었다.\n\n"만수 상회 개업. 트럭 시절 그 만수 맞음. 여전히 안 속임."\n\n"그거면 됐어. 오늘은 그게 개업 선물이야."\n\n만수가 종이를 가게 문 옆에 붙였다. 물건을 사지는 않았지만, 빈손으로 온 기분은 아니었다.', fx:{moodAll:3, flag:'mansu_shop', note:{type:'사건',title:'만수 상회 개업식',body:'물건 대신 개업식과 홍보 문구를 도왔다. 만수가 광고를 가게 문 옆에 붙였다.',links:['만수']}}}]},
 ]},

/* ── 2인 케미 이벤트 ── */
{id:'duo_mechsong', type:'동행', w:7, once:true, needsComp:'minji', needsComp2:'leo',
 title:'정비의 리듬',
 text:'정차 정비 중. 민지의 라체트 소리가 일정하다. 딸깍, 딸깍, 딸깍.\n\n레오가 그 박자에 기타를 얹기 시작했다.\n\n민지가 노려봤다— 그런데 손은 박자를 안 놓치고 있다.',
 choices:[
  {label:'지켜본다', out:[{p:1, text:'딸깍(라체트), 둥(기타), 딸깍, 둥둥.\n\n10분 뒤엔 완전한 합주가 됐다. 민지는 끝까지 인정 안 했지만 마지막 볼트를 조일 때 라체트를 빠르게 세 번 딸깍— 멋을 부렸다. 정비사의 앙코르였다.\n\n곡명은 레오가 붙였다. 「19mm의 왈츠」. "볼트 사이즈예요. 이게 오늘의 키(key)였거든요."', fx:{van:8, time:40, mood:{minji:3, leo:3}, moodAll:4, note:{type:'사건',title:'19mm의 왈츠',body:'라체트와 기타의 합주. 정비사의 앙코르 딸깍 세 번 포함. 인정은 미발급.',links:['민지','레오']}}}]},
 ]},

{id:'duo_nightround', type:'동행', w:7, once:true, needsComp:'parkss', needsComp2:'kangwoo', night:true,
 title:'야간 회진조',
 text:'밤의 정차. 강우가 차 둘레를 돌고, 박 선생이 그 뒤를 따라 돈다.\n\n"경계에 왜 따라와." "회진이야. 담요 확인." "…같이 돌지."\n\n그렇게 세상에서 제일 이상한 2인조가 결성됐다. 한 명은 바깥을 보고, 한 명은 안쪽을 본다.',
 choices:[
  {label:'자는 척하며 듣는다', out:[{p:1, text:'두 사람의 대화가 차 문틈으로 드문드문 넘어왔다.\n\n"발 시렵겠네." "담요 하나 더." "약국 할 때도 밤엔 이랬어. 셔터 내리고 나면 꼭 누가 두드렸거든. 급하다고." "……." "…자네는 군에서도 이랬나." "아니. 군에선 바깥만 봤지." "지금이 낫네." "…그렇지. 지금이 낫다."\n\n반쯤 감은 눈으로 듣다가, 두 사람이 문을 여는 소리에 눈을 마저 감았다. 발끝에 담요 한 장이 더 덮였다. 들었다는 말은 하지 않았다.', fx:{fatigue:-5, moodAll:5, mood:{parkss:3, kangwoo:3}, note:{type:'사건',title:'야간 회진조',body:'바깥을 보는 사람과 안쪽을 보는 사람. "지금이 낫다." 내 발끝에 담요 한 장이 더 덮였다.',links:['박 선생','강우']}}}]},
 ]},

{id:'duo_appraisal', type:'동행', w:7, once:true, needsComp:'jaeyi', needsComp2:'eunsu',
 title:'전파상 감정쇼',
 text:'재이가 폐품 더미에서 낡은 라디오 세 대를 주워 왔다. 은수가 눈을 빛냈다.\n\n"감정 들어갑니다." 재이가 외관·희소성 담당, 은수가 성능·회로 담당.\n\n즉석 감정쇼 개막이다.',
 choices:[
  {label:'관람한다', out:[{p:1, text:'1호기: "케이스 A급!" "회로 사망. 부품용." — 고철행.\n\n"A급이라면서요?" "겉이요. 겉만 A급. 고철로 220원." "…그램당요?" "개당요."\n\n2호기: "흔한 모델." "근데 이 개조 흔적 보세요. 누가 단파 개조를 해놨어요. 장인이에요." — 소장 결정.\n3호기: 전원을 넣자— 지익, 하고 살아났다. 두 감정사가 하이파이브를 했다.\n\n"협업 감정의 시대네요." 재이가 선언했고, 은수는 명함 문구를 궁리하다 두 번 고쳤다. 「고물과 전파 — 보이는 값과 들리는 값」, 아니 「들리는 값과 보이는 값」. 수첩을 덮으려다 순서가 또 마음에 걸렸는지, 연필을 다시 꺼냈다.', fx:{scrap:4, item:{'라디오 진공관':1}, mood:{jaeyi:3, eunsu:3}, moodAll:3, note:{type:'사건',title:'고물과 전파',body:'협업 감정 1호·2호·3호기. 단파 개조 장인의 흔적 소장 결정.',links:['재이','은수']}}}]},
 ]},

{id:'duo_mixtape', type:'동행', w:7, once:true, needsComp:'leo', needsComp2:'eunsu', night:true,
 title:'채보',
 text:'은수가 주파수를 돌리다 어딘가에서 새어 나오는 노래를 잡았다. 잡음 반, 멜로디 반.\n\n"이 노래 뭐지? 처음 듣는데 좋다."\n\n레오가 기타를 당겨 앉았다. "잡아둘게요. 전파는 사라져도 채보는 남으니까."',
 choices:[
  {label:'같이 흥얼거린다', out:[{p:1, text:'은수가 주파수를 붙들고, 레오가 코드를 받아 적었다. 노래가 끊기면 둘이 기억을 맞춰 빈칸을 메웠다.\n\n"여기 가사가 \'돌아오는 길\'이었나, \'돌아가는 길\'이었나." "돌아오는. 확실해요. 관제사 귀예요."\n\n"…아니요, 정정할게요." 은수가 헤드폰 한쪽을 벗었다. "두 번 다 그 대목에 잡음이 겹쳤어요. 확실하지 않아요."\n\n"그럼 둘 다 적어두죠. 원곡자가 나중에 고쳐주면 되고."\n\n완성된 채보엔 제목 칸이 비어 있다. 원곡자를 만나면 물어보기로 했다. 세상 어딘가에서 이 노래를 틀던 사람을, 언젠가.', fx:{mood:{leo:3, eunsu:3}, moodAll:4, note:{type:'사건',title:'제목 없는 채보',body:'전파에서 건진 노래. 제목 칸은 원곡자를 만날 때까지 공란.',links:['레오','은수']}}}]},
 ]},

/* ── 위기 확충 ── */
{id:'crisis_boar', minParty:1, type:'위기', w:5, region:['south','mid'],
 title:'도로의 주인',
 text:'커브를 돌자 브레이크. 도로 한복판에 멧돼지 가족이 있다.\n\n어미 하나, 새끼 다섯. 어미가 이쪽을 본다. 비키려는 기색이 전혀 없다.\n\n여러 해가 지나면 도로의 소유권도 바뀐다.',
 choices:[
  {label:'시동 끄고 기다린다', out:[{p:1, text:'20분을 기다렸다. 새끼들이 아스팔트에서 뒹굴고, 어미가 갓길 풀을 뒤지는 동안.\n\n마침내 가족이 숲으로 들어갔다. 어미가 마지막에 한 번 돌아봤다. 통행 허가의 눈빛이었다.\n\n"저쪽이 주인이고 우리가 손님이야, 이제." 아무도 반박하지 않았다.', fx:{time:20, moodAll:2, note:{type:'사건',title:'통행 허가',body:'멧돼지 가족의 도로. 20분 대기 후 통행 허가(어미 눈빛 결재).'}}}]},
  {label:'경적을 울린다', out:[
   {p:1, text:'빵— 소리에 새끼들이 흩어지고, 어미가— 돌진해 왔다.\n\n후진 전속력. 어미는 50m를 쫓아오고 멈췄다. 백미러 속에서 한참 이쪽을 노려보다 가족을 데리고 사라졌다.\n\n"…우리가 잘못했네." 아무도 반박하지 않았다. 결국 20분을 돌아갔다.', fx:{time:35, fuel:-2, moodAll:-2, van:-2}}]},
 ]},

{id:'crisis_battery', minParty:1, type:'위기', w:5,
 title:'걸리지 않는 시동',
 text:'정차를 마치고 키를 돌렸다.\n\n틱. 틱틱.\n\n…엔진이 침묵한다. 배터리다. 세워둔 사이 뭔가가 전기를 조금씩 마셨다— 범인 후보: 문틈 실내등, 라디오 대기전력, 혹은 그냥 수명.',
 choices:[
  {label:'밀어서 시동', out:[{p:1, text:'전원 하차. "하나, 둘, 셋!"\n\n내리막까지 30m를 밀었다. 클러치를 붙이자 엔진이 부르릉 살아났다. 운전석에 올라탄 뒤에야 할아버지 수첩의 문장이 떠올랐다. 「밀어서도 걸리는 차를 타라.」\n\n대답할 숨은 없었다. 범퍼에 기대 한동안 웃기만 했다.', fx:{time:30, fatigue:8, moodAll:3, note:{type:'사건',title:'밀어서 시동',body:'할아버지 수첩대로 차를 밀어 시동을 되살렸다.',links:['할아버지']}}}]},
  {label:'민지의 응급 충전', req:{comp:'minji'}, out:[{p:1, text:'민지가 태양광 패널(있다면)이나 폐차 배터리를 직결해 응급 충전을 했다.\n\n"범인은 실내등. 아니, 실내등이랑 문틈 둘 다야. 문이 덜 닫혀서 계속 켜져 있었던 거니까." 민지가 문틈에 테이프를 붙였다. "재판 끝. 집행 완료."', fx:{time:40, mood:{minji:3}}}]},
 ]},

{id:'crisis_glass', type:'위기', w:5,
 title:'유리밭',
 text:'앞쪽 도로가 햇빛에 반짝인다. 예쁘다— 가 아니라, 위험하다.\n\n유리밭이다. 전복된 유리 운반 트럭의 잔해가 100m에 걸쳐 깔려 있다. 여러 해 동안 아무도 안 치운.',
 choices:[
  {label:'빗자루 작전', out:[{p:1, text:'빗자루와 판자로 바퀴 폭만큼의 길을 냈다. 40분의 청소.\n\n문득 누가 시작했는지, 낸 길을 바퀴 폭이 아니라 도로 폭으로 넓히고 있었다. "다음 차는 안 세워도 되게."\n\n소식벽 정신이다. 길에도 답장이 있는 법이다.', fx:{time:70, fatigue:8, moodAll:3, note:{type:'사건',title:'유리밭 개통',body:'바퀴 폭으로 시작해 도로 폭으로 끝난 청소. 다음 차는 안 세워도 된다.'}}}]},
  {label:'조심조심 통과', out:[
   {p:2, text:'최저속으로, 큰 조각을 피해 지그재그 100m. 식은땀 나는 곡예 운전이었지만 무사 통과.', fx:{time:15}},
   {p:1, text:'뒷바퀴가 결국 하나 밟았다. 펑크는 면했지만 트레드에 유리가 박혀, 다음 정차 때 뽑는 수술이 필요했다.', fx:{time:30, van:-3}}]},
 ]},

{id:'crisis_flood', minParty:1, type:'위기', w:5, needRain:true,
 title:'물 건너는 길',
 text:'낮은 다리(세월교)가 불어난 물에 반쯤 잠겼다. 물살이 다리 위를 훑고 지나간다.\n\n수심은 얕아 보인다. 보이는 것과 건널 수 있는 것은 다른 문제다.',
 choices:[
  {label:'물이 빠지길 기다린다', out:[{p:1, text:'두 시간을 기다렸다. 그동안 라면을 끓였고, 물 구경을 했고, 나뭇가지 경주(각자 하나씩 상류에서 띄워 하류 도착순)를 세 판 했다.\n\n물이 다리 아래로 내려간 뒤 안전하게 건넜다. 기다림도 기술이다.', fx:{time:120, moodAll:3, note:{type:'사건',title:'나뭇가지 경주',body:'세월교 대기 2시간. 나뭇가지 경주 3판(2판은 판정 시비로 무효).'}}}]},
  {label:'지금 건넌다', out:[
   {p:1, text:'탈출에 대비해 창문을 열고, 저속을 일정하게 유지하며 밀고 나갔다. 물살이 문짝을 두드리는 15초.\n\n건넜다. 배기구에서 물이 콸콸 쏟아졌다. 차가 한동안 젖은 개처럼 털털댔다.', fx:{time:5, van:-4, fatigue:4, moodAll:2}},
   {p:1, text:'중간에서 엔진이 컥, 하고 물을 먹었다. 필사의 재시동— 걸렸다. 나머지 절반은 관성과 기도로 건넜다.\n\n강 건너서 30분간 엔진을 말렸다. 다신 안 하기로 못을 박았다.', fx:{time:45, van:-8, fuel:-2, moodAll:-3}}]},
 ]},

{id:'crisis_pileup', minParty:1, type:'위기', w:5, region:['mid','north'],
 title:'그날의 정체',
 text:'고속도로 구간. 오래전 그날의 연쇄 추돌이 그대로 얼어붙어 있다.\n\n수십 대가 뒤엉킨 100m. 차선은 전멸. 갓길만이 실낱같이 뚫려 있다— 폭이 차와 거의 같다.',
 choices:[
  {label:'갓길 실낱을 통과한다', out:[{p:1, text:'사이드미러 접고, 유도수 두 명이 앞서 걸으며 수신호. 시속 5km의 100m.\n\n차들 사이를 지나는 동안 아무도 차 안을 들여다보지 않았다. 보지 않는 것이 애도인 순간도 있다.\n\n통과 후 누가 뒤를 향해 고개를 숙였다. 전원이 따라 했다. 그리고 말없이 속도를 냈다.', fx:{time:30, fatigue:5, moodAll:-2, note:{type:'사건',title:'그날의 정체',body:'얼어붙은 연쇄 추돌 100m. 보지 않는 것이 애도인 순간. 통과 후 묵례.'}}}]},
  {label:'국도로 우회한다', out:[{p:1, text:'한 시간을 돌았다. 아무도 아깝다고 하지 않았다.\n\n어떤 길은 지나가지 않는 게 지나가는 방법이다.', fx:{time:60, fuel:-3}}]},
 ]},

/* ── 날씨 확충 ── */
{id:'wx_ghostlight', type:'조우', w:6, needWx:'fog', night:true,
 title:'안개 속 헤드라이트',
 text:'짙은 안개. 전방에 헤드라이트 두 개가 나타났다.\n\n마주 오는 차다— 오랜만에? 심장이 뛰었다. 상향등을 두 번 깜빡였다.\n\n저쪽도 두 번 깜빡였다. 정확히 같은 간격으로.',
 choices:[
  {label:'천천히 접근한다', out:[
   {p:2, text:'거리가 줄수록 불빛이 이상했다. 너무 안 움직인다.\n\n고장 난 차인가 싶어 속도를 더 줄였다. 그런데 불빛은 내 차가 움직이는 만큼만 따라 움직인다.\n\n폐버스 유리에 내 헤드라이트가 비친 거였다.\n\n내 불빛에 내가 인사를 했네. 상향등을 끄고 버스 옆을 천천히 지나갔다.', fx:{note:{type:'사건',title:'안개 속의 우리',body:'마주 오는 차의 정체는 폐버스 유리에 비친 우리. 우리가 우리에게 인사했다.'}}},
   {p:1, text:'진짜 차였다. 짐 실은 트럭이 안개 속을 기어 남쪽으로 가고 있었다.\n\n창문을 내리고 스치는 순간 서로 손을 들었다. "북쪽 조심하세요!" "남쪽 무사히 가세요!"\n\n안개 속 5초의 조우. 그런데 하루치 기운이 났다.', fx:{moodAll:4, note:{type:'사건',title:'안개 속 5초',body:'여러 해 만의 마주 오는 차. "북쪽 조심하세요!" "남쪽 무사히 가세요!"'}}}]},
 ]},

{id:'wx_struck_tree', type:'탐색', w:6, needWx:'storm',
 title:'벼락 맞은 나무',
 text:'쩌적— 번쩍이 동시에 왔다. 무섭게 가깝다.\n\n다음 커브에서 그 현장을 만났다. 길가 고목이 세로로 쪼개져 연기를 올리고 있다. 비가 불씨를 다투어 끄는 중이다.',
 choices:[
  {label:'쪼개진 속을 본다', out:[{p:1, text:'벼락이 지나간 단면이 숯처럼 검고 매끈했다. 그리고 놀랍게— 속이 빈 둥치 안에서 마른 장작 같은 심재가 나왔다. 벼락도 못 태운 속살이다.\n\n벼락 맞은 나무는 액막이가 된다는 말을 떠올리고 한 토막을 기념으로 실었다.\n\n이만큼 겪었으면 액땜은 다 하지 않았나. 그래도 나무토막은 도로 내려놓지 않았다.', fx:{scrap:2, moodAll:3, note:{type:'사건',title:'벼락의 보증서',body:'벼락 맞은 고목의 심재 한 토막. 액막이 겸 보증서로 탑승.'}}}]},
  {label:'멀리 돌아간다', out:[{p:1, text:'벼락 두 번 맞은 자리는 없다지만, 실험해볼 마음도 없다. 조용히 우회했다.', fx:{time:10}}]},
 ]},

{id:'wx_bigwash', type:'동행', w:6, needWx:'clear', minParty:2,
 title:'만국기의 날',
 text:'구름 한 점 없는 쾌청. 바람도 알맞다.\n\n"오늘이다." 누가 선언했다. 빨래의 날이다.\n\n개울가에 차를 세우고, 로프를 나무 사이에 걸었다.',
 choices:[
  {label:'대세탁을 집행한다', out:[{p:1, text:'두 시간의 대세탁. 로프에 옷가지가 만국기처럼 걸리자 야영지가 축제 분위기가 났다.\n\n마른 옷에선 해 냄새가 났다. 해 냄새의 정체는 과학적으로 뭐라던데, 아무도 검색할 수 없으므로 그냥 해 냄새로 하기로 했다.\n\n뽀송한 옷을 입은 사람은 착해진다. 차에 탄 사람들 전원이 유의미하게 친절해졌다.', fx:{time:150, water:-2, fatigue:-8, moodAll:7, note:{type:'사건',title:'만국기의 날',body:'쾌청 대세탁. 해 냄새의 정체는 미상(검색 불가로 종결). 전원 친절해짐.'}}}]},
 ]},

{id:'wx_frogs', needsDog:true, type:'발견', w:5, needRain:true, night:true,
 title:'개구리 대합창',
 text:'밤 비가 그친 논길. 창문을 여니—\n\n와글와글와글와글.\n\n개구리 수만 마리의 합창이 논 전체에서 올라온다. 기세로 치면 야구장 응원석급이다.',
 choices:[
  {label:'헤드라이트를 끄고 듣는다', out:[{p:1, text:'합창은 파도처럼 몰려왔다 물러났다 했다. 한쪽이 그치면 다른 쪽이 받았다. 어떻게 저렇게 차례를 맞추지. 한동안 창밖에 귀를 기울였다.\n\n보리가 창밖에 대고 한 번 짖자— 논 전체가 2초간 조용해졌다가 다시 터졌다. 보리야, 네 차례였어? 보리는 대답 대신 코를 창틀에 걸쳤다.', fx:{time:15, moodAll:4, note:{type:'사건',title:'야구장급 합창',body:'비 갠 밤 논의 개구리 대합창. 보리가 짖자 잠깐 멎었다가 다시 시작됐다.'}}}]},
 ]},

/* ── 밤 확충 ── */
{id:'night_owl', type:'발견', w:5, night:true, once:true,
 title:'부엉이',
 text:'야영 준비 중, 머리 위에서 소리가 났다.\n\n부엉. 부엉.\n\n올려다보니 죽은 가로등 꼭대기에 수리부엉이 한 마리. 가로등의 새 입주자다. 불 대신 눈이 켜져 있다.',
 choices:[
  {label:'서로 구경한다', out:[{p:1, text:'부엉이는 우리를 30분쯤 감시(관찰이라기엔 눈빛이 진지했다)하다가, 소리 없이 날아올라 어둠 속으로 출근했다.\n\n"가로등이 밤에 눈 달린 건 처음 보네."\n\n밤새 멀리서 부엉 소리가 들렸다. 이상하게 경비를 세운 것처럼 든든했다.', fx:{moodAll:3, note:{type:'사건',title:'가로등 입주자',body:'죽은 가로등의 수리부엉이. 불 대신 눈이 켜진 가로등. 밤새 무료 경비.'}}}]},
 ]},

{id:'night_convoy', type:'조우', w:5, night:true, once:true,
 title:'밤의 호송대',
 text:'밤 주행 중, 백미러에 불빛들이 나타났다. 하나, 둘… 다섯.\n\n차량 다섯 대의 호송대가 뒤따라온다. 트럭 둘, 승합 둘, 그리고 앰뷸런스 하나.\n\n추월 차선으로 나란히 붙더니, 선두 차가 창문을 내렸다.',
 choices:[
  {label:'창문을 내린다', out:[{p:1, text:'"어디까지 가요?!" 바람 소리 너머로 외침이 왔다.\n\n"서울!"\n\n"뭐요?!"\n\n"서-울-이-요!"\n\n"아! 우린 강릉! 병원 차려요! 의사 셋 실었어요!"\n\n"둘이요?" "셋! 셋!"\n\n1분간의 병렬 주행 동안 정보가 교환됐다. 우리는 아는 정착지를, 저쪽은 동해안 소식을. 헤어질 때 다섯 대가 차례로 경적을 한 번씩 울렸다. 빵, 빵, 빵, 빵, 빵. 다섯 발의 예포였다.\n\n"강릉에 병원이 생긴대." 그 문장이 그날 밤 내내 차 안을 따뜻하게 했다.', fx:{moodAll:5, note:{type:'소문',title:'강릉행 호송대',body:'의사 셋을 실은 다섯 대. 강릉에 병원이 생긴다. 예포 다섯 발.'}}}]},
 ]},

{id:'night_samedream', type:'동행', w:5, night:true, minParty:2, once:true,
 title:'같은 꿈',
 text:'긴 밤 주행 중, 누가 끝없는 국도를 달리는 꿈을 꿨다고 했다. 그러자 다른 두 동료도 각자 국도 꿈을 꿨다고 맞장구쳤다. 한 사람의 꿈에는 휴게소까지 나왔다.\n\n전원이 국도 꿈을 꿨다. 매일 국도만 보면 그럴 만도 하다. 아마도.',
 choices:[
  {label:'꿈 내용을 대조한다', out:[{p:1, text:'꿈을 맞춰 보니 겹치는 건 국도뿐이었다. 나머지는 제각각이었다. 누구는 꿈에서도 연비 걱정을 했고, 누구는 꿈 휴게소에서 호두과자를 샀는데 맛이 안 났다고 억울해했다.\n\n꿈에서 맛이 나면 돌아오기 싫어질 테니 오히려 무섭다는 말까지 나왔다. 말을 꺼낸 사람도 설명하다 자기가 무슨 소리를 하는지 모르겠다며 웃었다.\n\n농담으로 시작해서 조금 진지해진 밤이었다. 그래도 국도는 꿈이 아니라, 맛이 나는 쪽 세상에서 계속됐다.', fx:{moodAll:3, note:{type:'사건',title:'국도 꿈 전원 일치',body:'겹친 건 국도뿐. 교훈: 맛이 나는 쪽 세상에서 달릴 것.'}}}]},
 ]},

/* ── v1.6 탐색 ── */
{id:'exp_hardware', type:'탐색', w:6,
 title:'철물점',
 text:'만물의 성지, 철물점이다.\n\n못 서랍 서른 칸, 볼트 너트의 은하계, 로프와 철사와 경첩과 온갖 공구. 먼저 다녀간 사람들이 있었지만 철물점은 바다다— 퍼내도 남는다.',
 choices:[
  {label:'체계적으로 쓸어담는다', out:[{p:1, text:'차에 당장 맞는 규격부터 골라 우선순위 조달을 시작했다. 스테인리스 호스클램프, 절연테이프, 규격 볼트, WD 비스무리한 방청유.\n\n"철물점 주인은 세상이 두 번 망해도 굶어 죽지 않는다"는 옛말이 사실인 게, 계산대 뒤 골방에 라면이 스무 개 있었다. 주인장 몫으로 열 개는 남겼다.', fx:{time:40, scrap:6, item:{'부품':2}, food:2, note:{type:'사건',title:'철물점 조달 작전',body:'만물의 성지. 라면 절반은 주인장 몫으로 존치.'}}}]},
 ]},

{id:'exp_noodleworks', type:'탐색', w:6,
 title:'제면소',
 text:'국숫집들에 면을 대던 제면소. 천장에 면 건조대가 빨래처럼 걸려 있다.\n\n기계는 죽었지만 절반은 수동이다. 반죽 밀대, 절단 롤러. 그리고 창고에 밀가루 포대 몇이 습기를 피해 살아남았다.',
 choices:[
  {label:'국수를 뽑는다', out:[{p:1, text:'반죽 한 시간, 밀기 30분, 롤러에 넣고 돌리자— 국수가 나왔다. 굵기가 칼국수와 우동 사이 어딘가의 신종이었지만 국수는 국수다.\n\n그날 저녁은 잔치국수(고명: 오미자청 조금, 참기름, 말린 나물). 면을 직접 뽑아 먹으면 후루룩 소리가 두 배로 당당해진다.', fx:{time:120, food:4, moodAll:6, note:{type:'사건',title:'신종 국수',body:'제면소 수동 롤러로 뽑은 칼국수-우동 사이의 무언가. 당당한 후루룩.'}}}]},
  {label:'밀가루만 챙긴다', out:[{p:1, text:'멀쩡한 포대 하나를 실었다. 밀가루는 가능성이다— 수제비도 전도 빵도 될 수 있는.', fx:{food:3}}]},
 ]},

{id:'exp_outdoor', type:'탐색', w:6,
 title:'등산용품점',
 text:'등산로 입구의 아웃도어 매장. 오래전 세일 현수막이 아직 걸려 있다. 「전 품목 40%」\n\n선반은 반쯤 털렸지만 등산객이 아니면 안 가져갈 것들이 남았다.',
 choices:[
  {label:'실속을 챙긴다', out:[{p:1, text:'수통, 코펠, 침낭 하나, 등산 양말 뭉치(양말은 문명이다), 그리고 손난로용 하이킹 파우치.\n\n계산대에 고철을 조금 올려놨다. 40% 세일가 기준으로 계산한, 아무도 안 받을 값이었지만 그래야 도둑이 아니라 손님이다.', fx:{water:1, moodAll:3, scrap:-2, fatigue:-4, note:{type:'사건',title:'40% 세일',body:'등산용품점. 계산대에 고철 지불(셀프 계산). 양말은 문명이다.'}}}]},
 ]},

{id:'exp_towyard', type:'탐색', w:6,
 title:'견인차 차고지',
 text:'견인차 여섯 대가 나란히 잠든 차고지. 벽에 근무표와 무전기 충전대, 그리고 지도가 붙어 있다.\n\n지도엔 빨간 펜 표시가 가득하다— 오래전 그날, 출동 나갔던 지점들이다.',
 choices:[
  {label:'지도를 살핀다', out:[{p:1, text:'빨간 동그라미들이 그날의 사고 지도를 그리고 있었다. 우리가 지나온 길, 지나갈 길 위에.\n\n한 지점에 동그라미 대신 별표와 메모. 「여기 견인 불가. 사람만.」\n\n사람만. 그날 어느 견인기사는 차를 버리고 사람부터 실었다. 별표 위치를 우리 지도에도 옮겨 적었다. 이유는 설명하기 어렵지만, 좋은 자리 같아서.', fx:{revealNear:1, moodAll:2, note:{type:'사건',title:'여기 견인 불가. 사람만.',body:'그날 어느 기사의 선택이 남긴 별표. 좋은 자리로 분류.'}}}]},
  {label:'부품을 수확한다', out:[{p:1, text:'견인차는 부품의 보고다. 윈치 케이블, 유압 부속, 대형 배터리(반쯤 살았다).\n\n달구지에 윈치가 생기는 날을 꿈꾸며 케이블을 감아 실었다.', fx:{scrap:5, item:{'부품':2}, time:40}}]},
 ]},

/* ── v1.6 조우 ── */
{id:'meet_cowherd', minParty:1, type:'조우', w:6, region:['south','mid'],
 title:'소 모는 사람',
 text:'도로를 소 여덟 마리가 걷고 있다. 뒤에서 노인이 회초리 대신 라디오를 들고 따라간다. 라디오에선 트로트가 나온다.\n\n"소가 트로트를 좋아해. 걸음이 박자를 타거든." 노인이 진지하게 설명했다.',
 choices:[
  {label:'소떼의 속도에 맞춘다', out:[{p:1, text:'시속 4km의 동행이 시작됐다. 노인은 장에 소를 팔러 가는 게 아니라— 소들과 풀 좋은 북쪽 골짜기로 이사 가는 중이라고 했다.\n\n"소는 재산이 아니라 식구야. 세상 망하고 나서야 다들 그걸 알더라."\n\n갈림길에서 소 여덟 마리가 차례로 차 옆을 지나갔다. 마지막 소가 창문에 콧김을 한 번 뿜었다. 작별 인사로 접수했다.', fx:{time:30, moodAll:4, note:{type:'인물',title:'소 모는 사람',body:'트로트로 소를 모는 노인. "소는 재산이 아니라 식구야." 콧김 작별 인사 접수.'}}}]},
 ]},

{id:'meet_pansori', type:'조우', w:6, once:true, region:['south','mid'],
 title:'소리꾼',
 text:'정자나무 아래서 북소리가 났다. 둥. 둥.\n\n갓 쓴 노인이 북을 잡았고, 그 앞에 관객— 없다. 그런데 소리를 시작했다.\n\n"이런 난세에 만난 길손들이 반갑구나아—" 즉흥이다. 우리 얘기다.',
 choices:[
  {label:'추임새를 넣는다', out:[{p:1, text:'"얼쑤!" 어설픈 추임새에 소리꾼의 눈이 빛났다.\n\n"거기서 넣는 게 아니여." "…네?" "뭐, 넣었으니 됐고."\n\n즉흥 판소리 「달구지 노래」가 시작됐다. 부산서 온 차 한 대가 고개를 넘고 물을 건너— 지나온 길이 가락을 타자 이상하게 대단한 이야기처럼 들렸다.\n\n"소리가 뭐냐. 남의 일생을 대신 울고 웃어주는 게 소리다." 노인이 북채를 놓았다. "너희 일생은 아직 소리 반 마당이야. 마저 살고 오너라. 완창은 그때 해주마."', fx:{time:40, moodAll:6, note:{type:'인물',title:'소리꾼',body:'즉흥 「달구지가」 반 마당. 완창은 마저 살고 온 뒤에. 예약 완료.',links:['달구지']}}}]},
 ]},

{id:'meet_scribe', type:'조우', w:6, once:true,
 title:'대필가',
 text:'장터 구석, 좌판에 종이와 만년필과 팻말.\n\n「대필 — 편지·유언·연서·사과문. 맞춤법 보장」\n\n안경 쓴 중년이 무릎에 담요를 덮고 앉아 있다. "요즘은 사과문이 제일 많아요. 세상이 좁아져서, 미운 사람이랑도 계속 봐야 하거든."',
 choices:[
  {label:'편지 한 통을 의뢰한다 (고철 2)', req:{scrap:2}, out:[{p:1, text:'받는 사람을 정하는 데 제일 오래 걸렸다. 결국— 미래의 우리에게 쓰기로 했다.\n\n한 문장씩 부르면 대필가가 다듬었다. 부르다 말고 고치고, 고쳤다가 도로 돌리기를 몇 번.\n\n"서울 도착한 우리에게. 도착했으면 됐고, 못 했어도 여기까지 온 건 진짜다."\n\n"…그 마지막 문장, 빼는 게 낫지 않을까요."\n\n"뺄까요?"\n\n"…아뇨. 두세요."\n\n봉투에 「남산에서 개봉」이라고 적혔다. 조수석 서랍이 점점 우체국이 되어간다.', fx:{scrap:-2, moodAll:4, note:{type:'사건',title:'미래의 우리에게',body:'대필가가 다듬은 다섯 문장. 남산에서 개봉. 조수석 서랍=우체국화 진행 중.',links:['남산']}}}]},
  {label:'맞춤법 상담만 받는다', out:[{p:1, text:'일지의 헷갈리던 맞춤법 몇 개를 공짜로 교정받았다. "돼요/되요"에서 두 명이 틀린 게 들통났다. 상담료는 서로의 침묵으로 지불됐다.', fx:{moodAll:2}}]},
 ]},

{id:'meet_mapmaker', type:'조우', w:6, once:true,
 title:'지도장이',
 text:'갓길에 세운 오토바이. 사이드카에 제도판이 실려 있다.\n\n한 사람이 도로를 스케치하고 있다— 무너진 육교, 새로 난 샛길, 물 나오는 곳을 기호로 그려 넣으며.\n\n"오래전 지도는 다 거짓말이 됐어요. 거짓말까진 아니고— 아무튼 이젠 안 맞아요. 누가 다시 그려야죠."',
 choices:[
  {label:'정보를 교환한다', out:[{p:1, text:'우리 일지의 길 정보와 지도장이의 신작 지도가 달구지 보닛 위에서 만났다.\n\n"이 고개는 이제 막혔군요. 그럼 우회로부터— 아니, 우회로도 제가 확인을 못 했으니 점선으로 두죠."\n\n말하면서 이미 지우개를 찾고 있었다. 우리가 지난 우물과 무너진 길을 짚어 주자 지도장이는 눈앞에서 지도를 고쳐 그렸다. 종이를 두 번 뒤집었고, 아까 물어본 걸 한 번 또 물었다.\n\n한 시간 뒤, 아직 표시되지 않은 샛길 하나를 답례로 내줬다.\n\n"직접 확인한 길이에요. 저도 한 번밖에 안 가봤고요. 다음 갈림길에서만 쓰세요."', fx:{time:60, revealNear:1, moodAll:3, flag:'mapmaker_met', note:{type:'인물',title:'지도장이',body:'거짓말이 된 옛 지도를 직접 다니며 고쳐 그리는 사람. 확인한 샛길 하나를 나눠 받았다.'}}}]},
 ]},

{id:'meet_welldigger', minParty:1, type:'조우', w:6, once:true, region:['mid','north'],
 title:'우물 파는 사람',
 text:'마을 어귀에서 곡괭이 소리가 난다. 남자 혼자 우물을 파고 있다. 이미 어깨 깊이다.\n\n"상수도가 죽었으니 우물의 시대죠." 남자가 흙을 퍼 올리며 말했다. "한 마을에 하나씩. 열두 개째입니다."',
 choices:[
  {label:'교대로 판다', out:[{p:1, text:'"이거 얼마나 더 파요?"\n\n"글쎄요."\n\n"…글쎄요?"\n\n"파봐야 압니다. 열한 번이 다 달랐어요."\n\n두 시간을 교대로 팠다. 어깨가 빠질 즈음— 바닥이 축축해지더니 물이 배어 나왔다.\n\n"터졌다!" 우물 바닥에서 올려다본 하늘이 동그랬다.\n\n남자는 우물마다 파준 사람 이름을 돌에 새긴다고 했다. 열두 번째 우물 돌엔 낯선 이름들이 한 줄 더 들어갔다. 마을이 되살아나면, 누군가 물을 마시며 그 이름들을 읽을 것이다.', fx:{time:130, fatigue:15, water:3, moodAll:6, note:{type:'사건',title:'열두 번째 우물',body:'어깨 깊이에서 터진 물. 우물돌에 달구지 일행의 이름이 새겨졌다. 물마다 이름이 남는다.'}}}]},
  {label:'물만 얻어 간다', out:[{p:1, text:'"열한 번째 우물 물이에요." 남자가 두레박을 내렸다. 갓 나온 우물물은 이가 시리게 차고 달았다.', fx:{water:2, moodAll:2}}]},
 ]},

/* ── v1.6 발견 (히든 대체 경로) ── */
{id:'find_trucker_log', type:'발견', w:6, once:true, hiddenTarget:'any',
 title:'트럭커의 수첩',
 text:'폐휴게소 트럭 운전석에서 운행 수첩을 발견했다.\n\n기름값, 화물 내역, 휴게소 평점(별점제다. 국밥 맛 기준)— 그리고 마지막 장에 손그림 지도.\n\n「단속 안 뜨는 쉼터. 물 있음. 조용함.」',
 choices:[
  {label:'쉼터 위치를 옮겨 적는다', out:[{p:1, text:'트럭커들의 비밀 쉼터라면 신뢰도는 검증 완료다. 그들은 길에서 자는 프로였으니까.\n\n수첩은 운전석에 도로 놓았다. 별점 데이터가 아까웠지만(국밥 3.5 이상만 감), 수첩은 트럭의 일부다.', fx:{reveal:'any', note:{type:'소문',title:'트럭커의 쉼터',body:'프로가 검증한 자리. 물 있음. 조용함. 국밥 별점 데이터는 트럭에 존치.'}}}]},
 ]},

{id:'find_arrows', type:'발견', w:6, once:true, hiddenTarget:'any',
 title:'초록 화살표',
 text:'가드레일에 초록 스프레이 화살표가 있다. 몇 킬로 가자 또 하나. 또 하나.\n\n일정한 간격, 같은 초록. 누가 어딘가로 가는 길을 표시해뒀다— 혹은 누군가를 데려가려고.',
 choices:[
  {label:'화살표를 따라간다', out:[
   {p:2, text:'화살표는 샛길로 꺾여 한참을 안내하더니— 좋은 곳에서 끝났다. 마지막 화살표 옆 바위에 초록 글씨. 「잘 왔음. 쉬다 가세요.」\n\n앞서 이 길을 간 누군가가, 뒤에 올 모두에게 남긴 표지였다.', fx:{reveal:'any', moodAll:3, note:{type:'소문',title:'초록 화살표',body:'익명의 길 안내. 종점의 인사: "잘 왔음. 쉬다 가세요."'}}},
   {p:1, text:'화살표는 어느 지점에서 뚝 끊겼다. 마지막 화살표 밑에 스프레이 캔이 떨어져 있었다. 다 쓴.\n\n물감이 다해서 멈춘 안내. 캔을 주워 차에 실었다. 언젠가 초록 스프레이를 구하면— 이 안내를 이어 그리기로 했다.', fx:{moodAll:2, note:{type:'사건',title:'끊긴 화살표',body:'스프레이가 다해 멈춘 길 안내. 캔 수거. 언젠가 이어 그릴 것.'}}}]},
 ]},

{id:'find_windchime', type:'발견', w:5, once:true, hiddenTarget:'any',
 title:'풍경 소리',
 text:'바람결에 맑은 소리가 실려 온다. 뎅그렁. 뎅그렁.\n\n바람에 우는 작은 종이다. 소리는 골짜기 쪽에서 온다. 절이 있을 자리는 아닌데.',
 choices:[
  {label:'소리를 따라간다', out:[{p:1, text:'골짜기 안, 누군가 살던 흔적에 풍경 수십 개가 걸려 있었다. 처마에, 빨랫줄에, 나뭇가지에.\n\n집주인은 없고 풍경만 남아 바람이 불 때마다 집 전체가 연주를 했다. 문패 대신 나무판: "소리 나는 집. 길 잃으면 소리 따라오세요."\n\n등대의 소리 버전이었다. 지도에 표시했다— 소리 나는 집 근처에 뭐가 있는지, 가보면 안다.', fx:{reveal:'any', moodAll:3, note:{type:'소문',title:'소리 나는 집',body:'풍경 수십 개의 집. "길 잃으면 소리 따라오세요." 소리로 짓는 등대.'}}}]},
 ]},

/* ── v1.6 정경 ── */
{id:'vg_petrichor', type:'정경', w:3, needRain:true,
 title:'비 냄새',
 text:'첫 빗방울이 마른 아스팔트에 닿는 순간, 그 냄새가 올라왔다.\n\n흙과 먼지와 여름이 섞인, 이름을 아는 사람은 드물지만 모르는 사람은 없는 냄새.',
 choices:[{label:'…', out:[{p:1, text:'"이 냄새 이름이 있대. 뭐였더라."\n\n아무도 기억하지 못했고, 아무도 아쉬워하지 않았다. 이름 없이도 완전한 것들이 있다.', fx:{moodAll:2}}]}]},

{id:'vg_ivy', minParty:1, type:'정경', w:3,
 title:'방음벽의 담쟁이',
 text:'고속도로 방음벽을 담쟁이가 절반쯤 덮었다.\n\n오래전엔 낙서가 있던 자리다. 지금은 초록이 낙서 위를 덮으며 제 글씨를 쓰는 중이다.',
 choices:[{label:'…', out:[{p:1, text:'"10년 뒤엔 초록 벽이겠다."\n\n10년 뒤를 아무렇지 않게 말할 수 있게 된 것을, 말하고 나서야 다들 알아챘다.', fx:{moodAll:2}}]}]},

{id:'vg_banner', type:'정경', w:3,
 title:'현수막',
 text:'육교에 현수막이 걸려 있다. 빛이 바래 반쯤 지워졌다.\n\n「축 결혼 — 김OO ♡ 박OO」\n\n오래전 봄의 날짜. 식은 올렸을까.',
 choices:[{label:'…', out:[{p:1, text:'"올렸을 거야." 근거 없는 확신이 차 안의 공식 입장으로 채택됐다.\n\n어딘가에서 몇 번째 봄을 함께 맞았기를. 현수막이 바람에 한 번 펄럭였다. 동의로 간주했다.', fx:{moodAll:2}}]}]},

{id:'vg_carstack', minParty:1, type:'정경', w:3,
 title:'폐차 탑',
 text:'폐차장 압축기 옆에 눌린 차들이 5층으로 쌓여 있다.\n\n맨 꼭대기 차 지붕에 들풀이 자라 작은 정원이 됐다. 세상에서 제일 높은 화단이다.',
 choices:[{label:'…', out:[{p:1, text:'차의 최후가 화분이라면, 그건 나쁜 결말은 아니다.\n\n달구지가 들으라고 한 말은 아니었지만, 다들 대시보드를 한 번씩 쓰다듬었다.', fx:{moodAll:1}}]}]},

{id:'vg_paddymirror', type:'정경', w:3, region:['south','mid'],
 title:'무논 거울',
 text:'물을 댄 논이 하늘을 완벽하게 비추고 있다.\n\n구름이 논 안에서 흐르고, 왜가리 한 마리가 하늘 위를 걷는다. 위아래가 잠깐 헷갈리는 풍경이다.',
 choices:[{label:'…', out:[{p:1, text:'논에 비친 차가 우리와 나란히 달렸다. 거꾸로 매달린 채, 씩씩하게.\n\n"저쪽 세상 우리도 서울 가나 보다." 그쪽도 무사하길 빌어줬다.', fx:{moodAll:2}}]}]},

{id:'vg_cairns', minParty:1, type:'정경', w:3, region:['mid','north'],
 title:'돌탑 군락',
 text:'고갯마루에 돌탑 수십 기가 서 있다. 옛날 것도 있고— 돌이 아직 하얀 새것도 있다.\n\n여러 해 사이에도 사람들은 여길 지나며 돌을 얹었다. 빌 것이 많은 시대라서.',
 choices:[{label:'…', out:[{p:1, text:'잠깐 세우고 한 명씩 돌을 얹었다. 소원은 각자라 묻지 않았다.\n\n고개를 넘는 뒷거울 속에서 돌탑들이 배웅했다.', fx:{time:5, moodAll:2}}]}]},

/* ── v2.0 업그레이드 연계 이벤트 ── */
{id:'up_winch_rescue', type:'조우', w:9, once:true, needUp:'winch',
 title:'도랑에 빠진 트럭',
 text:'커브 아래 도랑에 1톤 트럭이 뒷바퀴를 빠뜨린 채 걸려 있다. 운전자가 삽으로 흙을 파다가 우리 앞범퍼를 보고 삽을 놓쳤다.\n\n"그거… 윈치죠? 그거 윈치 맞죠?!"',
 choices:[
  {label:'윈치를 건다', out:[{p:1, text:'케이블을 걸고 드럼을 감았다. 위이잉— 트럭이 진흙을 뚝뚝 흘리며 도로로 올라왔다.\n\n운전자는 감격해서 짐칸의 쌀 포대를 반이나 퍼주려 했다. 반의 반으로 합의를 봤다.\n\n"윈치 단 차는 참 오랜만에 봐요. 요즘 세상에 남 꺼내주려고 돈 쓰는 사람이 어딨다고."\n\n있다. 여기.', fx:{time:30, food:3, moodAll:5, note:{type:'사건',title:'윈치의 첫 실전',body:'도랑의 1톤 트럭 구조. "남 꺼내주려고 돈 쓰는 사람" — 있다, 여기.'}}}]},
 ]},

{id:'up_awning_guest', type:'조우', w:8, once:true, needUp:'awning',
 title:'차양 아래 손님',
 text:'정차하고 차양을 펼치자마자, 지팡이 짚은 노인이 그늘 안으로 자연스럽게 들어와 앉았다.\n\n"카페 개업했나?" 노인이 태연하게 물었다.\n\n아니라고 하기엔 그늘이 너무 카페 같았다.',
 choices:[
  {label:'물이라도 대접한다', out:[{p:1, text:'노인은 물 한 잔을 마시며 30분간 이 동네 30년 치 이야기를 풀었다. 어느 다리가 언제 무너졌고, 어느 우물이 아직 사는지.\n\n"그늘 값이야." 노인이 일어나며 말했다. 그늘 값 치고는 후했다.', fx:{water:-1, time:30, revealNear:1, moodAll:3, note:{type:'사건',title:'그늘 값',body:'차양 아래 첫 손님. 물 한 잔에 동네 30년 치 정보.'}}}]},
 ]},

{id:'up_stove_visitor', type:'조우', w:8, once:true, needUp:'stove', night:true,
 title:'연기를 보고 온 사람',
 text:'야영 준비 중, 어둠 속에서 발소리. 배낭을 멘 여행자가 조심스럽게 불빛 가장자리에 섰다.\n\n"굴뚝 연기가 보여서요. …난로 있는 차는 처음 봐요. 잠깐만 쬐어도 될까요?"',
 choices:[
  {label:'국 한 그릇 말아준다', out:[{p:1, text:'여행자는 국그릇을 두 손으로 감싸고 오래 데우고 나서야 먹기 시작했다.\n\n답례로 남쪽 소식과 북쪽 소문을 한 보따리 풀었다. 떠날 때 여행자가 굴뚝을 다시 올려다봤다.\n\n"이 차, 멀리서 보면 집 같아요."\n\n그 말이 그날 밤 난로보다 따뜻했다.', fx:{food:-1, moodAll:5, revealNear:1, note:{type:'사건',title:'집 같은 차',body:'굴뚝 연기를 보고 온 여행자. "멀리서 보면 집 같아요."',links:['달구지']}}}]},
  {label:'불만 쬐고 가게 한다', out:[{p:1, text:'여행자는 15분간 말없이 불을 쬐고, 꾸벅 인사하고 어둠으로 돌아갔다.\n\n따뜻함은 나눠도 줄지 않는다. 난로의 유일한 마법이다.', fx:{moodAll:2}}]},
 ]},

{id:'up_beehive_swarm', type:'동행', w:8, once:true, needUp:'beehive',
 title:'분봉 소동',
 text:'주행 중 지붕에서 웅웅 소리가 커졌다. 정차하고 올려다보니— 벌통 옆에 벌 수백 마리가 공처럼 뭉쳐 있다.\n\n분봉이다. 여왕벌이 새 살림을 나려는 것이다. 달구지 지붕에서.',
 choices:[
  {label:'조심스럽게 새 통을 만들어준다', out:[
   {p:2, text:'박스와 판자로 급조한 제2벌통에 벌 뭉치를 조심조심 옮겼다. 쏘인 사람 1명(운 나쁜 사람), 성공.\n\n달구지는 이제 2가구 벌 아파트다. 꿀 생산량 증가가 기대된다. 옆 마을 양봉가가 알면 기절할 성장세다.', fx:{time:60, fatigue:5, food:2, moodAll:4, note:{type:'사건',title:'2가구 벌 아파트',body:'지붕 분봉 성공. 쏘임 1건. 달구지 부동산 가치 상승.'}}},
   {p:1, text:'옮기다가 여왕벌이 마음을 바꿨는지, 벌 뭉치가 통째로 날아올라 가로수로 이사 갔다.\n\n"…전세 뺐네." 남은 벌통이라도 잘 달래기로 했다. 꿀은 원래 벌 마음이다.', fx:{time:40, moodAll:2}}]},
 ]},

{id:'up_lightbar_find', type:'발견', w:7, once:true, needUp:'lightbar', night:true, hiddenTarget:'any',
 title:'라이트바 아래 드러난 이정표',
 text:'밤 국도. 라이트바를 켜자 낮처럼 밝아진 갓길에— 맨눈으론 절대 못 봤을 것이 잡혔다.\n\n수풀에 반쯤 묻힌 손글씨 이정표. 화살표가 산길 쪽을 가리키고 있다.',
 choices:[
  {label:'이정표를 읽는다', out:[{p:1, text:'"이 위에 좋은 곳 있음. 밤에 온 사람만 믿으세요."\n\n밤에 온 사람만 믿으라는 이정표를 밤에 발견했다. 조건 충족이다. 지도에 옮겨 적었다.', fx:{reveal:'any', moodAll:2, note:{type:'소문',title:'밤에 온 사람만',body:'라이트바가 잡아낸 수풀 속 이정표. 조건: 밤에 올 것. 충족.'}}}]},
 ]},

{id:'up_snorkel_ford', minParty:1, type:'탐색', w:7, once:true, needUp:'snorkel', needRain:true,
 title:'잠긴 지하차도',
 text:'폭우에 잠긴 지하차도. 수심은 범퍼 위, 보통 차라면 무덤이다.\n\n하지만 우리에겐 스노클이 있다. 그리고 지하차도 건너엔— 물에 잠겨서 아무도 못 건드린 편의점 창고가 보인다.',
 choices:[
  {label:'천천히 도하한다', out:[
   {p:2, text:'스노클이 숨을 쉬는 동안 달구지는 잠수함처럼 물을 갈랐다. 창고는 소문대로— 물 위 선반이 고스란했다.\n\n통조림과 생수를 한가득. 물을 건너가 물을 얻어 왔다.', fx:{time:40, food:3, water:3, moodAll:4, note:{type:'사건',title:'잠수함 달구지',body:'스노클 도하로 잠긴 창고 개척. 물을 건너 물을 얻음.'}}},
   {p:1, text:'중간에 바닥 웅덩이가 예상보다 깊어서 잠깐 다들 숨을 참았다. 스노클은 침착했다.\n\n건넜지만 창고는 선객이 다녀간 뒤였다. 대신 지하차도 벽의 수위 낙서를 봤다. 「여기까지 찼었음 — 오래전 여름」. 우리 머리 위였다.', fx:{time:30, van:-2, moodAll:1}}]},
 ]},

{id:'up_mudtires_pass', type:'조우', w:7, once:true, needUp:'mudtires',
 title:'끊긴 길의 소문',
 text:'갓길에서 지도를 살피던 오토바이 여행자가 우리 바퀴를 보고 휘파람을 불었다.\n\n"그 타이어면… 저 산판길 넘을 수 있겠는데요? 포장도로는 다 끊겼는데 산길는 살아 있거든요. 아는 사람만 아는 길."',
 choices:[
  {label:'임도 정보를 받는다', out:[{p:1, text:'여행자가 지도에 연필로 임도 세 가닥을 그려줬다.\n\n"바퀴 좋은 차만 아는 길이 따로 있어요. 세상이 끊긴 게 아니라, 아스팔트만 끊긴 거예요."\n\n지도가 한 겹 두꺼워졌다.', fx:{revealNear:1, moodAll:3, note:{type:'소문',title:'임도의 세계',body:'세상이 끊긴 게 아니라 아스팔트만 끊겼다. 바퀴 좋은 차의 지도는 한 겹 더 두껍다.'}}}]},
 ]},

{id:'up_sidebox_lend', type:'조우', w:7, once:true, needUp:'sidebox',
 title:'공구 좀 빌립시다',
 text:'갓길에 세워진 승합차. 보닛을 연 남자가 맨손으로 뭔가를 돌려보려다 포기하고 있다.\n\n우리 사이드 공구함을 본 순간 남자의 눈빛이 변했다.\n\n"저기… 10mm 소켓 있습니까. 딱 10mm만."',
 choices:[
  {label:'공구함을 연다', out:[{p:1, text:'10mm는 세상 모든 공구함에서 사라지는 전설의 사이즈지만— 우리 공구함엔 있었다. 정리가 돼 있으니까.\n\n남자는 수리를 마치고 소켓을 두 손으로 반납했다. "10mm를 갖고 계신 분은 처음 봅니다." 존경이 담긴 목례와 함께 사례로 부품을 나눠받았다.', fx:{time:20, item:{'부품':1}, moodAll:3, note:{type:'사건',title:'전설의 10mm',body:'세상에서 제일 잘 사라지는 소켓을 보유·대여. 존경의 목례 수령.'}}}]},
 ]},

/* ── v2.0 일반 ── */
{id:'meet_busstop_grandmas', type:'조우', w:7, once:true, region:['south','mid'],
 title:'오지 않는 버스',
 text:'시골 버스 정류장에 할머니 셋이 나란히 앉아 있다. 보따리까지 완벽한 장날 차림새다.\n\n"버스 기다리시는 거예요?" "응." "…버스 안 다닌 지 여러 해인데요." "알어. 그래도 여기가 젤 시원해."\n\n정류장은 버스가 없어도 정류장이었다.',
 choices:[
  {label:'장터까지 모셔다드린다', out:[{p:1, text:'할머니 셋과 보따리 셋이 탔다. 뒷좌석이 순식간에 장날 버스가 됐다.\n\n가는 길 내내 참견(운전이 곱다, 차가 높다, 총각/처녀는 밥은 먹고 다니냐)을 들었다. 중간에 한 분이 "여기서 세워" 하셔서 세웠더니 "아니, 저기서" 하셨다. 결국 두 번 세웠다.\n\n내리실 때 보따리에서 찐 옥수수 세 개가 나왔다.\n\n"버스비여." 거스름돈은 없다고 했다.', fx:{time:25, food:2, moodAll:6, note:{type:'사건',title:'여러 해 만의 버스',body:'정류장 할머니 셋 수송 작전. 버스비=찐 옥수수 3개, 거스름돈 없음.'}}}]},
 ]},

{id:'exp_selfwash', needFlag:'van_named', needsDog:true, minParty:1, type:'탐색', w:6, once:true,
 title:'셀프 세차장',
 text:'동전 세차장. 기계는 죽었지만 지하수 수동 펌프가 살아 있고, 솔과 스펀지도 걸려 있다.\n\n달구지를 봤다. 여러 해 치 흙먼지 위에 낙서(누가 손가락으로 "닦자"라고 써놨다. 내부 소행이다)가 선명하다.',
 choices:[
  {label:'대세차를 집행한다', out:[{p:1, text:(S)=>{
    const crew=S.dog
      ? '전원 출동 한 시간. 펌프질 담당, 솔질 담당, 보리 담당(보리는 물줄기와 교전).'
      : '전원 출동 한 시간. 펌프질 담당과 솔질 담당을 번갈아 맡았다.';
    return crew+'\n\n먼지가 벗겨지자 옆구리의 「달구지」와 별 일곱, 발바닥 하나가 처음 그린 날처럼 선명해졌다.\n\n"…우리 차 잘생겼네." 만장일치였다.';
   }, fx:{time:60, fatigue:6, van:3, moodAll:6, note:{type:'사건',title:'대세차',body:'여러 해 치 먼지 아래서 별 일곱과 발바닥 하나를 다시 발굴했다.',links:['달구지']}}}]},
 ]},

{id:'comp_van_pride', type:'동행', w:6, needFlag:'van_parts_named', minParty:2,
 title:'달구지 자랑 대회',
 text:'정비를 마친 기념으로 누가 물었다. "달구지에서 제일 좋은 부분이 어디게?"\n\n전원이 동시에 다른 답을 말했다. 대회가 필요해졌다.',
 choices:[
  {label:'개최한다', out:[{p:1, text:'후보: 조수석(수첩 자리라서), 지붕(하늘이 있어서), 백미러(지나온 게 보여서), 경적(고함씨라서), 엔진(할아버지라서).\n\n투표 결과는 무효 처리됐다. 전원이 자기 후보에 투표했기 때문이다.\n\n"결론: 다 좋다." 싱거운 결론에 다들 만족했다. 자랑 대회는 원래 결론이 싱거워야 한다.', fx:{time:15, moodAll:5, note:{type:'사건',title:'제1회 달구지 자랑 대회',body:'전원 자기 후보 투표로 무효. 결론: 다 좋다.',links:['달구지']}}}]},
 ]},

{id:'meet_parts_peddler', type:'조우', w:6,
 title:'부품 행상',
 text:'자전거 리어카에 부품을 실은 행상. 진열이 기묘하게 전문적이다 — 호스는 호스끼리, 베어링은 크기순.\n\n"찾는 거 말씀만 하세요. 없으면 다음 주에 구해다 드리고."\n\n다음 주라니. 정기 노선이 있는 행상이다.',
 choices:[
  {label:'부품을 흥정한다 (고철 5)', req:{scrap:5}, out:[{p:1, text:'상태 좋은 부품 하나를 골랐다. 행상이 신문지에 싸며 말했다.\n\n"이 국도, 월요일마다 지나갑니다. 단골 하시면 예약도 받아요."\n\n무너진 세상에 정기 노선이 살아 있다. 그것도 부품 배달로.', fx:{scrap:-5, item:{'부품':1}, note:{type:'인물',title:'월요일의 부품 행상',body:'정기 노선 보유. 예약 가능. 진열은 크기순.'}}}]},
  {label:'구경만 한다', out:[{p:1, text:'크기와 마모도까지 맞춰 둔 베어링 진열을 한참 구경했다. 물건을 다루는 솜씨만 봐도 행상이 얼마나 오래 이 길을 다녔는지 알 수 있었다.', fx:{moodAll:1}}]},
 ]},

{id:'night_morse', type:'발견', w:5, once:true, night:true, region:['mid','north'],
 title:'맞은편 산의 불빛',
 text:'밤. 맞은편 산 중턱에서 불빛이 깜빡인다.\n\n불규칙한 것 같은데— 반복된다. 길게, 짧게, 길게.\n\n"저거 신호 아니야?"',
 choices:[
  {label:'헤드라이트로 답한다', out:[
   {p:2, text:'같은 패턴으로 라이트를 깜빡여줬다.\n\n산의 불빛이 잠깐 멈추더니— 빠르게 세 번 깜빡였다. 기쁨처럼 보이는 세 번이었다.\n\n뜻은 끝내 몰랐지만, 대화는 성립했다. 세상 어느 산엔 밤마다 불빛으로 말을 거는 사람이 있고, 오늘 처음 대답을 받았을 것이다.', fx:{moodAll:4, note:{type:'사건',title:'산과의 문답',body:'뜻 모를 불빛 신호에 같은 패턴으로 응답. 기쁨 같은 세 번이 돌아왔다.'}}},
   {p:1, text:'답하려는데 불빛이 꺼졌다. 그리고 다시 켜지지 않았다.\n\n신호였는지, 그냥 누군가의 손전등이었는지. 밤 산은 대답이 없었다.', fx:{}}]},
 ]},

{id:'vg_tunnelfan', type:'정경', w:3,
 title:'터널 환풍기',
 text:'긴 터널 천장에서 웅— 소리가 난다.\n\n환풍기가 돌고 있다. 오랫동안, 아무도 안 지나는 터널의 공기를 성실하게 갈아주면서.',
 choices:[{label:'…', out:[{p:1, text:'쟤도 천리안이 돌리는 걸까. 그냥 고장 나지 않은 채 계속 도는 건가.\n\n어느 쪽이든 터널 공기는 생각보다 맑았다. 성실함의 출처는 안 따지기로 했다.', fx:{}}]}]},

{id:'wx_dustart', type:'정경', w:3, needWx:'dust',
 title:'황사 캔버스',
 text:'황사가 앞유리에 고운 흙막을 입혔다.\n\n차를 세우고 내려 옆유리에 손가락으로 동그라미를 그렸다. 먼지가 묻어나며 유리색이 드러났다.',
 choices:[{label:'…', out:[{p:1, text:'해, 구름, 달구지. 손가락 끝이 누렇게 될 때까지 그렸다.\n\n타기 전에 창을 천으로 닦았다. 그림은 사라졌는데, 먼지는 벌써 다시 내려앉는다.', fx:{moodAll:2}}]}]},

/* ═══════════ v2.4 1:1 대화 — 민지 ═══════════ */
{id:'talk_mj_01', type:'대화', w:4, once:true, needsComp:'minji',
 title:'민지 — 라체트',
 text:'민지가 라체트를 분해해서 닦고 있다. 부품이 수술 도구처럼 줄 맞춰 놓여 있다.\n\n"공구는 매일 닦아야 돼. 안 닦으면 그… 아니다, 설명 길다. 아무튼 닦아야 돼. …왜 그렇게 봐."',
 choices:[
  {label:'"나도 가르쳐줘"', out:[{p:1, text:'민지가 3초쯤 의심하더니 걸레를 던져줬다.\n\n"기름때는 문지르지 말고 눌러서 찍어내. …아니, 그렇게 말고. 그… 이리 줘봐. 이렇게. 알겠지?"\n\n"방금 거랑 뭐가 달라?"\n\n"달라. …오, 근데 손놀림은 나쁘지 않네."\n\n라체트 반쪽을 맡았다. 승진이다.', fx:{mood:{minji:3}}}]},
  {label:'"수술하는 줄 알았어"', out:[{p:1, text:'"수술 맞아. 얘 관절염이야."\n\n"관절이… 있어?"\n\n"조인트. 관절이지 그럼." 민지가 라체트를 딸깍딸깍 돌려 보였다. "소리 들어봐. 아까보다 젊어졌지."\n\n반 박자 늦게 끄덕였는데, 진짜 그런 것 같아서 무서웠다.', fx:{mood:{minji:2}, moodAll:1}}]},
 ]},
{id:'talk_mj_02', type:'대화', w:4, once:true, needsComp:'minji',
 title:'민지 — 첫차',
 text:'"대장님 첫차는 뭐였어?" 민지가 불쑥 물었다.\n\n"내가 직접 몰던 거?"\n\n"응. 처음부터 이 차였어?"\n\n생각해보니 달구지가 첫차다. 그렇게 말하자 민지가 피식 웃었다.',
 choices:[
  {label:'"민지 넌?"', out:[{p:1, text:'"고물 스쿠터. 오빠가 고쳐준 거." 민지가 창밖을 봤다. "브레이크가 밀려서 언덕에서 죽을 뻔했는데… 아니, 이 얘기를 왜 하고 있지. 아무튼. 그날 정비를 배우기로 했어. 죽기 싫어서 시작한 게 직업이 됐네."\n\n"대장님은 첫차를 잘 만났네. 첫차가 인생 차인 사람은 드물어."', fx:{mood:{minji:3}, note:{type:'인물',title:'민지의 스쿠터',body:'브레이크 밀리던 고물 스쿠터. 죽기 싫어서 배운 정비가 직업이 됐다.',links:['민지']}}}]},
  {label:'"첫차치곤 너무 크지"', out:[{p:1, text:'"처음부터 짐칸까지 관리하려면 바빴겠네."\n\n민지가 대시보드를 툭툭 쳤다. "할아버지가 쓰던 차랬지. 대장님 손에 맞게 바꾼 데도 많겠다."', fx:{mood:{minji:2}, moodAll:1}}]},
 ]},
{id:'talk_mj_03', type:'대화', w:4, once:true, needsComp:'minji',
 title:'민지 — 손',
 text:'민지 손등에 새 상처가 났다. 본인은 눈치도 못 챈 모양이다.',
 choices:[
  {label:'반창고를 내밀고 손을 내달라고 한다', out:[{p:1, text:'민지가 상처를 내려다보더니 손등을 내밀었다.\n\n"…좀 살살 붙여. 따갑다."\n\n"알았어. 손 좀 가만히 둬."\n\n"…고마워. 정비사 손은 원래 이래."\n\n"원래 그런 건 없어." 잔소리가 나도 모르게 튀어나왔다. 민지가 웃음을 터뜨렸다.', fx:{mood:{minji:4}}}]},
  {label:'"아프지도 않냐"', out:[{p:1, text:'"어? 언제 났지, 이거."\n\n민지는 상처를 신기하게 들여다봤다. "집중하면 몰라. 아픈 건 나중에 몰아서 아파."\n\n그 말이 상처 얘기가 아닌 것 같아서, 잠깐 조용했다.', fx:{mood:{minji:2}}}]},
 ]},
{id:'talk_mj_04', type:'대화', w:4, once:true, needsComp:'minji',
 title:'민지 — 단것',
 text:'식사 후, 민지가 주머니에서 꼬깃한 사탕 하나를 꺼내 반으로 쪼갰다. 정확히 반.\n\n"먹을래?"',
 choices:[
  {label:'받는다', out:[{p:1, text:'딸기맛이었다. …자두였나. 포장지가 낡아서 맛 이름까지는 자신이 없었다. 민지는 자기 반쪽을 오래오래 녹여 먹었다.\n\n"정비 끝나면 단게 당겨. 몸이 아는 거야, 고생했다고."\n\n이후로 좋은 사탕이 생기면 민지 몫을 챙기게 됐다.', fx:{mood:{minji:3}}}]},
  {label:'"너 다 먹어"', out:[{p:1, text:'"…그럼 반쪽은 저금." 민지가 반쪽을 도로 포장지에 쌌다.\n\n"단건 나눠 먹거나 아껴 먹거나야. 한 번에 다 먹는 건 낭비고."\n\n사탕 경제학이었다.', fx:{mood:{minji:2}}}]},
 ]},
{id:'talk_mj_05', type:'대화', w:4, once:true, needsComp:'minji',
 title:'민지 — 소리',
 text:'"눈 감아봐." 민지가 갑자기 말했다. "엔진 소리만 들어. 뭐가 들려?"',
 choices:[
  {label:'집중해서 듣는다', out:[{p:1, text:'"…가끔 칙, 하고 새는데. 벨트 쪽인가?"\n\n"거기 말고 조금 아래."\n\n"2번? 아까 손으로 만졌을 땐 진동 비슷했는데."\n\n"응. 저 소리가 계속 나. 아직 작아서 나도 놓칠 뻔했어." 민지가 엔진 쪽을 가리켰다. "다음에 세우면 같이 열어보자. 혼자 들으면 자꾸 헷갈려."\n\n한 번 더 귀를 기울였다. 칙. 이제 어느 쪽에서 나는지 알겠다.', fx:{mood:{minji:4}, note:{type:'사건',title:'2번 실린더의 기분',body:'민지와 함께 2번 실린더 쪽 소리를 확인했다. 다음 정차 때 함께 점검하기로 했다.',links:['민지','달구지']}}}]},
  {label:'"엔진 소리지 뭐"', out:[{p:1, text:'"하아." 민지가 세상 깊은 한숨을 쉬었다. "쟤가 저렇게 말이 많은데."\n\n그 뒤 엔진 소리 통역(2번 실린더의 불만, 벨트의 안부)을 들었다. 결론: 엔진은 수다쟁이다.', fx:{mood:{minji:1}, moodAll:1}}]},
 ]},
{id:'talk_mj_06', type:'대화', w:4, once:true, needsComp:'minji', needBond:['minji',5],
 title:'민지 — 88.9',
 text:'민지가 라디오를 88.9에 맞춰놓고 잡음을 듣고 있다. 오래.\n\n돌리려는 기색이 없다.',
 choices:[
  {label:'옆에서 같이 듣는다', out:[{p:1, text:'잡음을 한동안 같이 들었다. 민지가 먼저 입을 열었다.\n\n"오빠랑 정한 채널이야. 잡히는 날이 있고 아닌 날이 있어. …잡히는 날엔, 살아 있다는 뜻이라고 정했어."\n\n"오늘은?"\n\n민지는 바로 답하지 않았다. 다이얼에 손만 얹고 있다가—\n\n"…잡음." 민지가 라디오를 껐다. "내일 또 들으면 돼."\n\n라디오 위에 올린 손은 바로 떨어지지 않았다. 나도 채널을 바꾸지 않았다.', fx:{mood:{minji:5}, note:{type:'사건',title:'내일 또 들으면 돼',body:'88.9의 잡음. 잡히는 날=살아 있다는 뜻. 민지의 기다리는 법.',links:['민지','민규']}}}]},
  {label:'조용히 자리를 비켜준다', out:[{p:1, text:'뒷자리로 옮겨 앉았다. 민지는 얼마 뒤에 라디오를 끄고, 아무 일 없었다는 듯 정비 수첩을 폈다.\n\n"…고마워." 뭐가 고마운지는 말하지 않았다. 알 것 같아서 묻지 않았다.', fx:{mood:{minji:4}}}]},
 ]},
{id:'talk_mj_07', type:'대화', w:4, once:true, needsComp:'minji', needBond:['minji',5],
 title:'민지 — 운전 교습',
 text:'"대장님, 운전 자세 나빠." 민지가 선언했다. "어깨에 힘 들어가 있어. 그러면 오래 못— 아니, 어깨만이 아니네. 허리도 그래."\n\n즉석 교습이 시작될 분위기다.',
 choices:[
  {label:'배운다', out:[{p:1, text:'"팔꿈치 좀 굽혀. 핸들 잡으면 어깨가 이렇게 올라가잖아."\n\n"이렇게?"\n\n"응. 손목도 조금 풀고. 아, 힘 빼라는 게 손 놓으라는 건 아니고."\n\n차를 세운 채 핸들을 잡아 봤다. 민지는 내 팔과 등받이 사이를 보고 의자를 한 칸 당겼다.\n\n"이제 브레이크 끝까지 밟아 봐. 무릎 펴지지 않게."\n\n발을 떼고 다시 밟았다. 이번엔 몸이 앞으로 딸려 나가지 않았다. 민지는 고개를 끄덕이다 내 손을 가리켰다.\n\n"어깨는 됐는데, 손은 또 꽉 쥐네. 손가락 자국 나겠다."', fx:{mood:{minji:3}, moodAll:1, note:{type:'사건',title:'운전석 한 칸',body:'민지와 운전석을 맞추고 핸들과 브레이크를 잡아 봤다. 어깨보다 손의 힘을 빼는 게 어려웠다.',links:['민지']}}}]},
  {label:'"내 자세가 어때서"', out:[{p:1, text:'"어깨. 목. 손목. 다 말해줘?"\n\n민지는 내 손 모양을 그대로 따라 했다. 어깨까지 귀 옆으로 올리자 나도 웃음이 났다. 핸들을 조금 느슨하게 잡았다.', fx:{mood:{minji:2}}}]},
 ]},
{id:'talk_mj_08', type:'대화', w:4, once:true, needsComp:'minji', needBond:['minji',12],
 title:'민지 — 정비소',
 text:'"서울 끝나면 뭐 할 거야?" 내가 물었더니, 민지가 의외로 바로 답했다.\n\n"정비소. 오빠랑 하기로 했었거든. 간판 이름까지 정해놨어."',
 choices:[
  {label:'"이름 뭔데"', out:[{p:1, text:'"…비밀." 민지가 웃었다. "오빠 만나면, 둘이 같이 말해줄게. 그게 조건이야."\n\n"힌트도 없어?"\n\n"없어. …아니, 하나 줄게. 두 글자는 아니야."\n\n조건. 오빠를 만난다는 걸 전제로 말하는 민지의 화법을, 나는 좋아한다.\n\n"손님 1호는 달구지 해줄게. 평생 무료."', fx:{mood:{minji:5}, note:{type:'소문',title:'이름 없는 정비소',body:'간판 이름은 남매가 같이 말해주는 조건. 1호 손님 예약: 달구지(평생 무료).',links:['민지','민규','달구지']}}}]},
  {label:'"나 취직시켜줘"', out:[{p:1, text:'"이력서 내. 경력란에 \'달구지 411km\' 쓰면 서류는 통과."\n\n면접관이 벌써 둘이라는 게 함정이지만, 취업 약속을 받아냈다. 세상이 끝나고 얻은 첫 내정이다.', fx:{mood:{minji:4}, moodAll:2}}]},
 ]},
{id:'talk_mj_09', type:'대화', w:4, once:true, needsComp:'minji', needBond:['minji',12], night:true,
 title:'민지 — 무서운 것',
 text:'밤. 민지가 정비 수첩(할아버지 것)을 빌려 읽다가 문득 말했다.\n\n"난 고장은 안 무서워. 고칠 수 있으니까. 무서운 건…"\n\n민지가 말을 골랐다.',
 choices:[
  {label:'기다린다', out:[{p:1, text:'"…부품이 없는 거." 민지가 수첩을 덮었다. "고칠 줄 아는데 손에 아무것도 없는 거. 그건 진짜 무서워."\n\n"그래서 그렇게 모아 두는구나."\n\n"어. 무서워서 모아." 말해놓고 민지가 잠깐 멈췄다. "…방금 거 꽤 솔직했다. 못 들은 걸로 해."\n\n민지가 덮었던 수첩을 다시 폈다. 나는 공구함 옆에 앉아 페이지 끝을 눌러 주었다.', fx:{mood:{minji:5}, note:{type:'인물',title:'민지의 공포',body:'고장이 아니라 빈손이 무섭다. 그래서 모은다.',links:['민지']}}}]},
  {label:'"녹슨 볼트?"', out:[{p:1, text:'"그건 무서운 게 아니라 화나는 거고."\n\n농담으로 받았더니 민지도 픽 웃고 말을 접었다. 다음에 다시 물어봐야지, 생각했다.', fx:{mood:{minji:1}}}]},
 ]},
{id:'talk_mj_10', type:'대화', w:4, once:true, needsComp:'minji', needBond:['minji',20],
 title:'민지 — 반쪽 공구함',
 text:'민지가 자기 공구함을 열더니, 한참 들여다보다가 렌치 하나를 꺼내 내밀었다.\n\n"이거, 대장님 가져."\n\n오빠가 사준 공구함의 렌치다. 세트가 깨진다.',
 choices:[
  {label:'"세트잖아. 못 받아"', out:[{p:1, text:'"세트니까 주는 거야." 민지가 렌치를 내 손에 쥐여줬다.\n\n"아니, 그게 무슨…"\n\n"오빠 만나면 세트 다시 맞추면 돼. 그때까지 대장님이 한 짝 갖고 있어. …그러면 잃어버릴 수가 없잖아. 렌치도, 대장님도."\n\n말문이 막혔다. 민지는 벌써 공구함을 닫고 있었다. "17mm야. 제일 많이 쓰는 거."', fx:{mood:{minji:6}, item:{'부품':1}, note:{type:'사건',title:'17mm의 약속',body:'세트를 일부러 깨서 나눠 가졌다. 다시 맞추는 날까지. "그러면 잃어버릴 수가 없잖아."',links:['민지','민규']}}}]},
  {label:'말없이 받아서 품에 넣는다', out:[{p:1, text:'받았다. 무게가 렌치 무게가 아니었다.\n\n"떨어뜨리면 죽는다." 민지가 씩 웃었다. 협박까지 다정한 날이었다.', fx:{mood:{minji:6}, item:{'부품':1}, note:{type:'사건',title:'17mm',body:'민지의 세트에서 나온 한 짝. 무게가 렌치 무게가 아니었다.',links:['민지']}}}]},
 ]},

/* ═══════════ v2.4 1:1 대화 — 박선생 ═══════════ */
{id:'talk_pss_01', type:'대화', w:4, once:true, needsComp:'parkss',
 title:'박선생 — 아재개그',
 text:'"운전하다 가장 무서운 게 뭔지 아나?"\n\n박 선생의 눈이 반짝인다. 함정이다. 아재개그다.',
 choices:[
  {label:'걸려준다 — "뭔데요?"', out:[{p:1, text:'"차 마시자는 말이야. 차에서."\n\n"…네?"\n\n"차. 마시는 차하고 타는 차하고." 박 선생이 손가락으로 두 번 짚었다. "설명하면 안 되는 건데. 벌써 설명했네."\n\n달구지 안에 잠깐 아무 소리도 안 났다. 박 선생은 보온병 뚜껑을 돌려 땄다.\n\n"됐고, 자네 컵 어딨나. 차 식겠다." 진짜 차를 주려던 거였다.', fx:{mood:{parkss:3}, moodAll:1}}]},
  {label:'선수 친다 — "차 마시자는 말이죠"', out:[{p:1, text:'박 선생이 보온병을 든 채 멈췄다.\n\n"…자네 이거 어디서 배웠나."\n\n"선생님 표정 보고요."\n\n"내가 그런 표정을 짓나." 보온병 옆면에 얼굴을 비춰 보더니 웃었다. "안 되겠네. 다른 거 생각해 와야겠어."\n\n내 컵을 먼저 채워 주고 자기 몫을 따랐다. 차는 농담보다 나았다.', fx:{mood:{parkss:4}, moodAll:1}}]},
 ]},
{id:'talk_pss_02', type:'대화', w:4, once:true, needsComp:'parkss',
 title:'박선생 — 약상자',
 text:'박 선생이 약상자를 정리하고 있다. 알약 개수를 세고, 수첩에 적고, 다시 세고.\n\n"잠깐. 이번엔 세는 동안 말 걸지 말게. 아까 어디까지 셌더라."',
 choices:[
  {label:'"제가 세는 거 도울게요"', out:[{p:1, text:'해열제 스물넷, 소독약 반 병, 붕대 세 롤…\n\n"스물넷이요?"\n\n"스물셋. 아니, 넷 맞네. 하나가 굴러갔었어."\n\n상자 모서리에 낀 알약을 꺼내 줄 끝에 놓았다. 박 선생은 수첩의 숫자를 고쳤다.\n\n"이제 자네도 우리 약국 직원이야. 무급이지만." 뚜껑을 닫다가 붕대 한 롤을 따로 꺼내 손 닿는 칸에 넣었다.', fx:{mood:{parkss:3}, note:{type:'사건',title:'무급 직원 임명',body:'약상자 재고 조사를 도왔다. 빠져 있던 알약 하나를 찾아 수첩의 숫자를 고쳤다.',links:['박 선생']}}}]},
  {label:'"어차피 또 셀 거잖아요"', out:[{p:1, text:'"맞아. 또 셀 거야." 박 선생은 태연했다.\n\n"세는 동안엔 딴생각이 안 나거든. 이건 재고 관리 겸… 뭐라고 하나. 그, 나한테 내리는—"\n\n말이 거기서 멈췄다. 박 선생은 다시 알약을 세기 시작했고, 문장은 끝내 안 돌아왔다.', fx:{mood:{parkss:2}}}]},
 ]},
{id:'talk_pss_03', type:'대화', w:4, once:true, needsComp:'parkss',
 title:'박선생 — 잔소리의 기술',
 text:'"물 마셔라. 스트레칭해라. 어깨 펴라."\n\n오늘의 잔소리 3종 세트가 발사됐다.',
 choices:[
  {label:'"잔소리도 처방이에요?"', out:[{p:1, text:'"당연하지. 제일 싸고, 제일 안 먹는 약이야."\n\n"…그게 약이에요?"\n\n"약국 할 때 알았어. 사람들이 약보다 잔소리가 필요해서 오더라고. 약은 핑계고. 서 씨라고, 파스만 사러 오던 양반이 있었는데 그 양반이—" 박 선생이 창밖을 보다 말을 접었다. "됐고. 물 마셔라."\n\n오늘의 잔소리가 4종 세트가 됐다.', fx:{mood:{parkss:3}, note:{type:'인물',title:'제일 싸고 제일 안 먹는 약',body:'잔소리는 처방이다. 사람들은 약보다 잔소리가 필요해서 약국에 온다.',links:['박 선생']}}}]},
  {label:'순순히 물을 마신다', out:[{p:1, text:'"오." 박 선생이 진심으로 놀랐다. "처방 순응도 100%인 환자는 자네가 처음이야. …아니, 둘째군. 우리 딸이 있었지."\n\n그러고는 사탕을 하나 꺼내 놨다. "모범 환자한테 주는 거야."\n\n딸 얘기는 그걸로 끝이었다.', fx:{mood:{parkss:3}, food:1}}]},
 ]},
{id:'talk_pss_04', type:'대화', w:4, once:true, needsComp:'parkss',
 title:'박선생 — 손맛',
 text:'박 선생이 저녁 당번인 날은 다 아는 비밀이 하나 있다. 같은 재료인데 맛이 다르다.\n\n"비결이요? 있지. 근데 안 가르쳐줘."',
 choices:[
  {label:'끈질기게 묻는다', out:[{p:1, text:'끈질기게 졸랐더니 비결이 나왔다.\n\n"간을 두 번에 나눠서 해. 처음에 반, 마지막에 반."\n\n"…그게 다예요?"\n\n"그게 다야. 뭘 더 바라나." 박 선생이 국자로 냄비를 두 번 두드렸다. "약도 그래. 한 번에 다 쓰면 독이고."\n\n비결을 알고 먹었는데도 여전히 맛이 달랐다. 그건 설명이 안 됐다.', fx:{mood:{parkss:3}, moodAll:1}}]},
  {label:'"장가 잘 가시겠어요"', out:[{p:1, text:'"갔었어. 잘." 박 선생이 국자를 내려놓았다.\n\n"아내가 해준 걸 하도 얻어먹었거든. 어깨너머로… 배웠다기보단 훔쳤지. 지금 내 손맛의 8할은 그 사람 거야. 아니, 9할인가."\n\n"몇 할인데요?"\n\n"세어본 적 없어." 그때 눌어붙는 냄새가 났고, 박 선생이 화들짝 냄비를 저었다. "아이고, 얘기하다 다 태우겠네."', fx:{mood:{parkss:4}, note:{type:'인물',title:'손맛의 8할',body:'어깨너머로 배운 아내의 간. 지금도 박 선생의 밥상에 남아 있다.',links:['박 선생']}}}]},
 ]},
{id:'talk_pss_05', type:'대화', w:4, once:true, needsComp:'parkss', night:true,
 title:'박선생 — 불면',
 text:'밤, 박 선생이 혼자 깨어 있다. 물컵을 무릎에 올려놓은 채다.\n\n"잠이 안 와서. 자네는 왜 깼나."',
 choices:[
  {label:'"같이 있어드릴게요"', out:[{p:1, text:'둘이서 식은 보리차를 나눠 마셨다. 박 선생은 별말 안 했고, 나도 안 했다.\n\n"약 먹으면 자기는 자지. 그런데… 눈 뜨면 또 그대로니까. 그게 싫어서 못 자는 날도 있어."\n\n"약국에도 그런 손님 왔어요?"\n\n"왔지. 수면제 달라고. 사놓고 다음 날 또 와. 약이 안 듣냐 물으면, 아직 안 먹었대. …나도 그땐 왜 그러는지 잘 몰랐어." 박 선생이 컵을 돌렸다.\n\n내가 빈 컵을 내려놓는데 박 선생의 컵도 기울었다. 받아 놓고 보니, 먼저 코를 골고 있었다.', fx:{mood:{parkss:4}, note:{type:'사건',title:'식은 보리차',body:'잠이 오지 않는 박 선생 곁에서 보리차를 나눠 마셨다. 잠든 손에서 컵을 받아 놓았다.',links:['박 선생']}}}]},
  {label:'"양이라도 세보세요"', out:[{p:1, text:'"삼천 마리까지 세봤어. 삼천한 마리째에 알았지. 양은 수면제가 아니라 재고 조사라는 걸."\n\n농담을 하는 걸 보니 괜찮은 밤인 모양이다. 아닌 밤엔 농담이 안 나온다.', fx:{mood:{parkss:2}}}]},
 ]},
{id:'talk_pss_06', type:'대화', w:4, once:true, needsComp:'parkss', needBond:['parkss',5],
 title:'박선생 — 단골들',
 text:'"우리 약국 단골 중에 김 노인이라고 있었어."\n\n박 선생이 묻지도 않은 이야기를 시작했다. 이 양반이 이러는 날은 드물다.',
 choices:[
  {label:'듣는다', out:[{p:1, text:'"매일 와. 약은 일주일치를 사놓고. 왜 오냐면— 얘기할 데가 없어서 와. 나는 그걸 알면서 혈압약 얘기를 30분씩 해줬고."\n\n"…혈압약 얘기가 30분이나 나와요?"\n\n"나오지. 짜게 먹지 마라부터 시작하면." 박 선생이 웃었다가 접었다. "그날 이후로 못 봤어. 피난 갔는지, 어떻게 됐는지."\n\n"북쪽 가다 보면 만날지도 모르지. 세상이 좁아졌으니까." 창밖을 오래 보다가 덧붙였다. "…그런 계산으로 따라나선 것도 있어, 사실."', fx:{mood:{parkss:5}, note:{type:'인물',title:'김 노인',body:'얘기할 데가 없어 매일 오던 단골. 박 선생이 북쪽으로 가는 이유 중 하나.',links:['박 선생']}}}]},
  {label:'"단골 많으셨겠어요"', out:[{p:1, text:'"동네 약국은 단골 장사야. 근데 단골이라는 말이— 다시 생각하면 좀 이상하지. 아픈 게 단골이 되면 안 되는 건데 말이야."\n\n"그럼 손님 없는 날이 좋으셨겠네요."\n\n"기뻤지. 장사는 망해도." 박 선생이 웃다가 덧붙였다. "월세 날엔 조금 덜 기뻤고. 그건 또 그거대로."', fx:{mood:{parkss:3}}}]},
 ]},
{id:'talk_pss_07', type:'대화', w:4, once:true, needsComp:'parkss', needBond:['parkss',5],
 title:'박선생 — 나이',
 text:'"자네, 내 나이 몇으로 보이나."\n\n위험한 질문이 왔다.',
 choices:[
  {label:'5살 깎아 말한다', out:[{p:1, text:'"허허. 아부도 처방이지." 알면서도 기분은 좋아했다.\n\n"늙는 건 말이야, 몸이 느려지는 게— 아니지, 몸도 느려져. 그건 그거고. 겁이 느는 게 진짜야."\n\n"겁이요?"\n\n"그래서 겁이 늘 때마다 하나씩 저질러 보는 거야. 이 여행도 그중 하나고." 그러고는 무릎을 두어 번 두드렸다. "저지르고 나면 무릎이 항의를 하지만."', fx:{mood:{parkss:3}, note:{type:'인물',title:'겁이 늘 때마다 저지른다',body:'늙음=겁이 느는 것. 그래서 저지른 여행.',links:['박 선생']}}}]},
  {label:'정직하게 말한다', out:[{p:1, text:'"…정직이 늘 미덕은 아니야." 박 선생이 창유리에 비친 제 얼굴을 봤다.\n\n"몇으로 보이냐고 물어놓고 이러는 것도 웃기지만."\n\n"…죄송해요."\n\n"됐어. 이 나이에 이 고생이면 젊게 사는 거지 뭐." 그러고는 물병을 건넸다. "자네나 마셔라. 얼굴이 말랐어."', fx:{mood:{parkss:2}, moodAll:1}}]},
 ]},
{id:'talk_pss_08', type:'대화', w:4, once:true, needsComp:'parkss', needBond:['parkss',12], noFlag:'pss_met',
 title:'박선생 — 가방의 주인',
 text:'박 선생이 왕진 가방을 무릎에 올려놓고 오래 쓰다듬고 있다.\n\n"…언젠가 얘기해준다고 했지. 이 가방 주인."',
 choices:[
  {label:'조용히 앉는다', out:[{p:1, text:'"수진이. 실습생. 나보다 나은 약사가 될 애였어."\n\n"그날, 내가 창고 정리를 시켰어. 안쪽에 있으라고. 안전하라고." 박 선생이 가방 손잡이를 쓸었다. "…정신 차려보니 약국 앞이 온통 사람이었고, 다시 들어가 보니 창고엔 이 가방만 있었어."\n\n"…수진 씨는요."\n\n"몰라. 살았는지, 어디서 제 몫의 약을 짓고 있는지. 오래 몰라." 말이 거기서 한 번 끊겼다. "그래서 들어. 매일. 주인 찾아 돌려줄 때까진 내 어깨가 얘 자리야."\n\n박 선생이 가방을 고쳐 멨다. "…오늘 몫 시작하지. 자네 어깨 좀 보자. 자세가 나빠."\n\n어깨를 내주는 동안, 그가 가방끈을 두 번 더 고쳐 쥐는 걸 봤다.', fx:{mood:{parkss:6}, note:{type:'인물',title:'수진의 가방',body:'그날 이후 소식이 끊긴 실습생의 가방. 박 선생은 주인에게 돌려줄 때까지 매일 그것을 든다.',links:['박 선생']}}}]},
 ]},
{id:'talk_pss_09', type:'대화', w:4, once:true, needsComp:'parkss', needBond:['parkss',12],
 title:'박선생 — 북쪽 약국',
 text:'"서울 일 끝나면, 난 거기서 약국을 열까 해."\n\n박 선생이 지나가듯 폭탄선언을 했다.',
 choices:[
  {label:'"서울에서요?"', out:[{p:1, text:'"북쪽이 제일 아플 거 아냐. 제일 아픈 데가 약국 자리지."\n\n"남산 일 끝나자마자요?"\n\n"간판이라도 걸어 놔야지. 쉬고 싶어지기 전에." 박 선생은 벌써 자리를 고르는 눈치였다. "여하튼 간판도 정했어. \'있을 건 있는 약국\'."\n\n"…없을 건 없다는 뜻이기도 하고." 스스로 해설까지 붙이고는 흡족해했다. 아무도 안 웃었는데도.', fx:{mood:{parkss:4}, note:{type:'소문',title:'있을 건 있는 약국',body:'개업 예정지: 제일 아픈 곳. 입지 기준은 상권이 아니라 통증.',links:['박 선생','남산']}}}]},
  {label:'"1호 손님 할게요"', out:[{p:1, text:'"자넨 손님 말고 직원 해."\n\n"월급은 주시는 거죠?"\n\n"경력은 인정해줄게. 그, 뭐라고 하나— 호봉. 호봉을 쳐줄게."\n\n월급 얘기를 다시 꺼내자 박 선생은 약국 자리부터 구해야 한다며 지도를 폈다.', fx:{mood:{parkss:3}, moodAll:1}}]},
 ]},
{id:'talk_pss_10', type:'대화', w:4, once:true, needsComp:'parkss', needBond:['parkss',20],
 title:'박선생 — 처방전',
 text:'박 선생이 종이 한 장을 접어 내밀었다. 진짜 처방전 양식이다. 어디서 났는지.\n\n"자네 처방전이야. 잃어버리지 말고."',
 choices:[
  {label:'펼쳐 읽는다', out:[{p:1, text:'처방전엔 약 이름이 없었다. 대신 박 선생의 글씨.\n\n"진단: 어깨에 이것저것 너무 많이 얹고 다님.\n처방: 밥 거르지 말고, 하루에 한 번은 남한테 맡길 것. 복용 기간: 내가 그만 쓰라고 할 때까지.\n— 담당 약사 박OO"\n\n"약효 끝내주는 거야, 그거. 내가 30년 걸려 조제한 거니까." 박 선생은 창밖을 보며 헛기침을 했다. 쑥스러움을 들키는 게 제일 싫은 양반이라.\n\n처방전은 수첩 사이에 끼웠다. 남산행 편지 옆에.', fx:{mood:{parkss:6}, moodAll:2, note:{type:'사건',title:'평생 처방전',body:'"하루에 한 번은 남한테 맡길 것. 복용 기간: 내가 그만 쓰라고 할 때까지." 30년 조제. 수첩에 보관.',links:['박 선생']}}}]},
 ]},

/* ═══════════ v2.4 1:1 대화 — 강우 ═══════════ */
{id:'talk_kw_01', type:'대화', w:4, once:true, needsComp:'kangwoo',
 title:'강우 — 침묵',
 text:'강우 옆에 앉았다. 강우는 아무 말이 없다. 나도 아무 말 안 했다.\n\n무슨 말이라도 꺼낼까 하다가 두 번 관뒀다.',
 choices:[
  {label:'계속 아무 말 안 한다', out:[{p:1, text:'강우가 먼저 입을 열었다.\n\n"…대장은 침묵을 잘 견디는군."\n\n"네? 아, 미안해요. 딴생각하느라 못 들었어요."\n\n"…됐다."\n\n그게 다였다. 그런데 어조가, 칭찬이었다.\n\n강우가 다시 창밖을 봤다. 나도 굳이 다음 말을 찾지 않았다.', fx:{mood:{kangwoo:4}, note:{type:'인물',title:'침묵 면접',body:'강우 옆에 말없이 앉아 있었다. 먼저 말을 건 쪽은 강우였다.',links:['강우']}}}]},
  {label:'"무슨 생각 해요?"', out:[{p:1, text:'"경계."\n\n"…뭘요?"\n\n"전부."\n\n"전부가… 어디부터 어디까진데요?"\n\n대답은 없었다. 대신 강우가 내 쪽 창문의 잠금을 슬쩍 확인해주고 갔다. 저 사람의 대답은 행동으로 온다.', fx:{mood:{kangwoo:2}}}]},
 ]},
{id:'talk_kw_02', type:'대화', w:4, once:true, needsComp:'kangwoo',
 title:'강우 — 커피 취향',
 text:'따뜻한 물을 나누다가 물었다. "커피 좋아해요?"\n\n강우가 멈췄다. 너무 오래 멈춰서, 못 들었나 싶어 한 번 더 물을 뻔했다. 이 사람에게 잡담은 고난도 훈련이다.',
 choices:[
  {label:'대답을 기다린다', out:[{p:1, text:'"…자판기 커피." 마침내 답이 나왔다. "부대 앞에 있었다. …300원. 아니, 350이었나. 300원이다."\n\n"설탕 프림 다 들어간 거요?" "전부 다." 강우의 입가가 아주 미세하게 풀렸다.\n\n"세상 돌아오면, 그거 한 잔 뽑고 싶군." 강우의 소원 목록 1호를 알아냈다. 300원짜리. 350원일 수도 있고.', fx:{mood:{kangwoo:4}, note:{type:'인물',title:'300원의 소원',body:'강우의 소원 1호: 부대 앞 자판기 커피(설탕 프림 전부).',links:['강우']}}}]},
  {label:'"물어본 제가 잘못이죠"', out:[{p:1, text:'"아니." 강우가 의외로 정정했다. "…연습 중이다. 잡담."\n\n연습이라는 말에 웃음이 났고, 강우는 못 본 척했다. 연습 상대가 됐다는 건 나쁘지 않은 신호다.', fx:{mood:{kangwoo:3}}}]},
 ]},
{id:'talk_kw_03', type:'대화', w:4, once:true, needsComp:'kangwoo',
 title:'강우 — 스트레칭',
 text:'차를 세우면 강우가 혼자 몸을 푸는 걸 다들 안다. 오늘은 용기 내서 옆에 섰다.\n\n"…따라 하게?"',
 choices:[
  {label:'"가르쳐줘요"', out:[{p:1, text:'군대식 체조가 시작됐다. 목— 어깨— 허리— 구령은 없는데 박자가 정확하다.\n\n"이거 몇 개씩 해요?"\n\n"……."\n\n"강우 씨?"\n\n"세는 거 아니다."\n\n어깨를 돌리자 우두둑 소리가 났다. 동작 몇 개를 따라 했을 뿐인데 조금 개운했다.\n\n"운전자는 몸이 장비다. 정비해라." 강우식 운전 전 점검이었다.', fx:{mood:{kangwoo:3}, fatigue:-4, note:{type:'사건',title:'몸이 장비다',body:'강우의 체조 입문. 운전자는 몸을 정비해야 한다.',links:['강우']}}}]},
  {label:'구경만 한다', out:[{p:1, text:'구경도 운동이라고 우기다가, 결국 목 돌리기 하나는 따라 하게 됐다.\n\n"내일은 두 개." 강우가 말했다. 이 사람의 커리큘럼은 도망갈 수 없다.', fx:{mood:{kangwoo:2}}}]},
 ]},
{id:'talk_kw_04', type:'대화', w:4, once:true, needsComp:'kangwoo',
 title:'강우 — 지도 읽기',
 text:'강우가 내 지도를 빌려 보더니 연필로 점 몇 개를 찍었다.\n\n"여기, 여기, 여기. 매복하기 좋은 지형."',
 choices:[
  {label:'"어떻게 알아요?"', out:[{p:1, text:'"내가 매복한다면 고를 자리니까."\n\n"…아. …아, 그렇네."\n\n간단하고 서늘한 논리였다. 강우의 수업이 이어졌다. 커브 안쪽을 조심할 것, 다리 앞에서 속도 줄이지 말 것, 시야가 좋은 곳이 저격에도 좋다는 것. 중간에 하나를 놓쳐 다시 물었더니 강우는 처음부터 다시 말했다. 요약이 없는 사람이다.\n\n"외우지 마라. 몸에 붙여라." 지도가 한 겹 무서워졌고, 한 겹 안전해졌다.', fx:{mood:{kangwoo:3}, note:{type:'사건',title:'매복의 지리학',body:'"내가 매복한다면 고를 자리니까." 지도가 무서워진 만큼 안전해졌다.',links:['강우']}}}]},
  {label:'"무섭게 왜 그래요"', out:[{p:1, text:'"무서운 게 안전한 거다."\n\n강우는 연필을 돌려주고 자리로 돌아갔다. 지도의 점 세 개는 지우지 않기로 했다.', fx:{mood:{kangwoo:1}}}]},
 ]},
{id:'talk_kw_05', type:'대화', w:4, once:true, needsComp:'kangwoo',
 title:'강우 — 요리 반전',
 text:'강우가 식사를 준비한다. 군대식 국이겠거니 했는데—\n\n칼질 소리가 심상치 않다. 타타타타탁. 전문가의 리듬이다.',
 choices:[
  {label:'"어디서 배웠어요?"', out:[{p:1, text:'"취사병 출신." 강우가 아무렇지 않게 말했다. "이등병 때. 파 오백 단 썰면 이렇게 된다."\n\n"오백 단이요? 하루에?"\n\n"…한 주에. 아무튼 많이."\n\n그날 국은 역대급이었다. 파수꾼이 아니라 주방장을 영입했던 건지도 모른다.\n\n"전투보다 취사가 부대 사기에 기여한다. 통계다." 진지한 얼굴로 만든 국이 진지하게 맛있었다.', fx:{mood:{kangwoo:4}, moodAll:2, note:{type:'인물',title:'취사병 강우',body:'파 오백 단의 칼질. "전투보다 취사가 사기에 기여한다. 통계다."',links:['강우']}}}]},
  {label:'말없이 보조를 선다', out:[{p:1, text:'"양파." "네." "물." "…물이 어디 갔지." "왼쪽에요." "…아, 왼쪽. 내가 놓고 잊었군. 아무튼 물."\n\n둘이서 군대식 주방이 돌아갔다. 완성된 국을 맛본 강우가 짧게 말했다. "…합격."\n\n내 그릇에 건더기가 조금 더 들어왔다.', fx:{mood:{kangwoo:3}, moodAll:1}}]},
 ]},
{id:'talk_kw_06', type:'대화', w:4, once:true, needsComp:'kangwoo', needBond:['kangwoo',5],
 title:'강우 — 웃는 법',
 text:'별것 아닌 농담에 웃음이 터졌는데 강우만 무표정이었다. 나중에 조용히 물었다. "재미없었어요?"\n\n"재미있었다."\n\n"…근데 왜 안 웃어요?"',
 choices:[
  {label:'진지하게 묻는다', out:[{p:1, text:'강우가 얼마간 있다 답했다.\n\n"웃는 걸 오래 안 하면, 잊는다. …잊는 건 아니고. 얼굴이 늦는다." 강우는 자기 뺨을 손가락으로 가리켰다. "근육 문제다. 마음 문제가 아니라."\n\n"그럼 연습하면 되겠네요." "…그런가." 강우가 입꼬리를 올려 보다가 손으로 뺨을 문질렀다. 나는 웃음을 참고 고개만 끄덕였다.', fx:{mood:{kangwoo:5}, note:{type:'인물',title:'얼굴 스트레칭',body:'강우는 얼굴 근육 문제라고 했다. 연습해 보라는 말에 입꼬리를 한 번 올려 봤다.',links:['강우']}}}]},
  {label:'"속으론 웃었죠?"', out:[{p:1, text:'"크게."\n\n무표정으로 크게 웃었다고 말하는 사람 앞에서, 나는 진짜로 크게 웃었다. 강우 몫까지.', fx:{mood:{kangwoo:3}, moodAll:1}}]},
 ]},
{id:'talk_kw_07', type:'대화', w:4, once:true, needsComp:'kangwoo', needBond:['kangwoo',5],
 title:'강우 — 개인 정비',
 text:'강우가 군번줄을 닦고 있다. 두 개를, 하나씩, 정성껏.\n\n눈이 마주쳤다. 보통이라면 여기서 대화가 끝나는데— 오늘은 강우가 자리를 좁혀 앉았다.',
 choices:[
  {label:'옆에 앉는다', out:[{p:1, text:'"매주 닦는다. 녹슬면… 이름이 안 보이게 되니까."\n\n내 수첩도 꺼냈다. 강우는 묻지 않고 헝겊의 깨끗한 쪽을 찢어 건넸다. 군번줄과 할아버지 수첩의 쇠 모서리를 나란히 닦았다.\n\n"…좋은 습관이다." 그날 대화는 그걸로 끝이었다.', fx:{mood:{kangwoo:5}, note:{type:'사건',title:'나란히 유품 정비',body:'군번줄과 정비 수첩을 나란히 닦았다. 말 대신 깨끗한 헝겊을 나눴다.',links:['강우','할아버지']}}}]},
 ]},
{id:'talk_kw_08', type:'대화', w:4, once:true, needsComp:'kangwoo', needBond:['kangwoo',12],
 title:'강우 — 후임',
 text:'"물어봐도 되는지 모르겠는데…" 내가 운을 떼자 강우가 먼저 말했다.\n\n"두 번째 군번줄. …그거지."',
 choices:[
  {label:'끄덕인다', out:[{p:1, text:'"박일병. 스물둘. 겁이 많았다. 겁이 많아서 제일 꼼꼼했다."\n\n강우는 창밖을 보며 말을 이었다. "제3방어선에서 내가 박 일병에게 반대쪽을 맡겼다. 판단은 정확했다. 결과가 틀렸을 뿐."\n\n"판단이 맞았는데 결과가 틀리면, 누구 잘못입니까."\n\n무슨 말이든 해야 할 것 같아 입을 뗐다가, 아무 말도 고르지 못했다. 강우가 먼저 군번줄을 쥐었다. "됐어. 서울 가서 걔 부모님께 돌려드리고, 그때 다시 묻지."', fx:{mood:{kangwoo:6}, note:{type:'인물',title:'박일병',body:'겁이 많아 제일 꼼꼼했던 스물둘. 강우는 두 번째 군번줄과 오래된 질문을 서울로 가져간다.',links:['강우','남산']}}}]},
 ]},
{id:'talk_kw_09', type:'대화', w:4, once:true, needsComp:'kangwoo', needBond:['kangwoo',12],
 title:'강우 — 무서운 것',
 text:'"강우 씨도 무서운 게 있어요?"\n\n어렵게 꺼낸 질문에, 강우는 의외로 바로 답했다.\n\n"있다."',
 choices:[
  {label:'"뭔데요?"', out:[{p:1, text:'"익숙해지는 거."\n\n강우가 드물게 긴 문장을 시작했다. 중간에 한 번 말을 골랐다. "총성에 익숙해지고, 폐허에 익숙해지고, 사람 잃는 것에… 익숙해지고. 나중엔 아무렇지도 않아져."\n\n뒷자리에서 냄비 뚜껑이 덜컹 떨어졌다. 강우가 그쪽을 보고 입꼬리를 아주 조금 올렸다. "저런 건 아직 좋군."', fx:{mood:{kangwoo:5}, note:{type:'인물',title:'익숙함이라는 공포',body:'강우가 가장 무서워하는 것은 사람을 잃는 데 익숙해지는 것. 달구지의 소란은 아직 반갑다.',links:['강우']}}}]},
 ]},
{id:'talk_kw_10', type:'대화', w:4, once:true, needsComp:'kangwoo', needBond:['kangwoo',20],
 title:'강우 — 뒷자리',
 text:'"잠깐 쉬어라." 강우가 뒷자리 담요를 털었다.\n\n"밖은 내가 볼 테니. 명령이다."',
 choices:[
  {label:'"명령이면 할 수 없죠"', out:[{p:1, text:'담요를 등에 받치고 뒷자리에 기대 앉았다. 강우가 문 옆에 자리를 잡자 나도 모르게 어깨에 힘이 풀렸다.\n\n눈을 감자 강우가 문 쪽에서 나직이 말했다. 혼잣말인지, 들으라는 말인지.\n\n"…경계는 내가 선다. 대장은 쉬어. 그러라고 같이 다니는 거다."\n\n눈을 감은 채 등을 담요에 더 깊이 기댔다. 밖에서 소리가 났지만 이번에는 일어나 확인하지 않았다.', fx:{mood:{kangwoo:6}, fatigue:-15, note:{type:'사건',title:'곁을 지키는 사람',body:'강우가 문 옆을 지키는 동안 뒷자리에 기대 쉬었다. 밖에서 소리가 나도 내가 먼저 확인할 필요는 없었다.',links:['강우']}}}]},
 ]},

/* ═══════════ v2.4 1:1 대화 — 레오 ═══════════ */
{id:'talk_leo_01', type:'대화', w:4, once:true, needsComp:'leo',
 title:'레오 — 코드 하나',
 text:'"기타 배워볼래요?" 레오가 기타를 불쑥 내밀었다. "코드 하나면 노래 백 곡은 돼요."',
 choices:[
  {label:'배운다', out:[{p:1, text:'레오가 내 손가락을 지판에 하나씩 얹어줬다. "이게 A마이너. 세상에서 제일 쓸쓸하고 제일 만만한 코드."\n\n처음 두 번은 둔탁한 소리만 났다. "손가락 아픈데요." "네, 그게 정상이에요."\n\n세 번째에 띵— 소리가 나자 레오가 박수를 쳤다. "축하해요, 이제 뮤지션이에요. 뮤지션의 정의는 소리를 낸 사람이거든요."\n\n기준이 후한 세계에 입문했다.', fx:{mood:{leo:4}, moodAll:1, flag:'leo_chord1', note:{type:'사건',title:'A마이너 입문',body:'제일 쓸쓸하고 제일 만만한 코드. 뮤지션의 정의=소리를 낸 사람.',links:['레오']}}}]},
  {label:'"전 듣는 담당 할게요"', out:[{p:1, text:'"오, 그거 중요한 포지션인데." 레오가 진지해졌다. "듣는 사람 없으면 노래는 그냥 소음이에요. 아니, 소음도 듣는 사람이 있어야 소음인가? …아무튼. 여러분이 저를 뮤지션으로 만들어주는 거예요."\n\n청중 1호 자리는 생각보다 명예로운 자리였다.', fx:{mood:{leo:3}}}]},
 ]},
{id:'talk_leo_02', type:'대화', w:4, once:true, needsComp:'leo',
 title:'레오 — 별명 공장',
 text:'"대장님은 별명이 뭐였어요?" 레오가 물었다. 대답도 하기 전에 눈이 반짝인다.\n\n"아니다, 제가 지어줄게요. 저 별명 잘 지어요."',
 choices:[
  {label:'맡겨본다', out:[{p:1, text:'레오는 나를 보다가 핸들을 보다가, 다시 나를 봤다. 후보를 두 개쯤 말하려다 고개를 저었다.\n\n"…\'키잡이\'. 아, 너무 사극인가. 근데 운전수는 재미없잖아요. 키잡이로 해요."\n\n혼자 고개까지 끄덕였다. "나중에 그렇게 불렀는데 안 돌아보면 다시 지을 거예요. 대답 잘하세요."\n\n옆에서 작게 키잡이를 불러 봤다. 쳐다봤더니 이번엔 모르는 척 기타를 튕겼다.', fx:{mood:{leo:4}, note:{type:'사건',title:'키잡이',body:'레오가 지어준 별명. 안 돌아보면 다시 짓겠다고 했다.',links:['레오']}}}]},
  {label:'"보리 별명이나 지어줘요"', out:[{p:1, text:'"보리는 별명이 열두 개예요. 요일별로 달라요. 월요일엔 털뭉치, 화요일엔 코감독…"\n\n진짜로 열두 개를 다 외웠다. 이 사람의 사랑은 목록형이다.', fx:{mood:{leo:3}, moodAll:1}}]},
 ]},
{id:'talk_leo_03', type:'대화', w:4, once:true, needsComp:'leo',
 title:'레오 — 하모니카',
 text:'레오가 기타 케이스 주머니에서 낡은 하모니카를 꺼냈다. 닳은 모서리가 손바닥 안에 감겼다.\n\n"아, 그거… 아빠 거예요."',
 choices:[
  {label:'"불 줄 알아요?"', out:[{p:1, text:'"조금요." 레오가 하모니카를 닦았다. 닦을 데가 없어 보이는데도 계속 닦다가, 입에 댔다.\n\n트로트도 발라드도 아닌, 오래된 노래가 나왔다. 두 소절만. 세 번째 소절 어귀에서 멈췄다.\n\n"…오늘은 여기까지요. 아빠가 이것만 불었어요. 술 마시면. 잘 부는 노래가 하나면 충분하대요, 사람은." 레오는 하모니카를 도로 주머니에 넣었다. "저는 아직 제 한 곡을 찾는 중이고요."\n\n400km가 그 한 곡이 되려나. 묻지는 않았다.', fx:{mood:{leo:4}, note:{type:'인물',title:'아빠의 하모니카',body:'잘 부는 노래가 하나면 충분하다. 레오는 아직 자기 한 곡을 찾는 중.',links:['레오']}}}]},
  {label:'조심히 다뤄준다', out:[{p:1, text:'하모니카를 두 손으로 받아 살펴보고 돌려줬다. 레오가 씩 웃었다.\n\n"물건 소중히 다루는 사람, 노래도 소중히 들어요. 통계예요." 근거는 없고 확신은 넘치는, 레오다운 통계였다.', fx:{mood:{leo:3}}}]},
 ]},
{id:'talk_leo_04', type:'대화', w:4, once:true, needsComp:'leo',
 title:'레오 — 신청곡',
 text:'"신청곡 받아요." 레오가 기타를 고쳐 안았다. "뭐든. 모르는 노래면 즉석에서 만들어드려요."',
 choices:[
  {label:'옛날 노래를 신청한다', out:[{p:1, text:'제목을 말하자 레오가 첫 소절을 더듬더듬 찾아냈다. "이건가? …아니네. 잠깐만요. …이거다."\n\n가사가 틀리고 코드가 미끄러졌지만— 다 부를 때쯤엔 나도 같이 부르고 있었다. 노래는 정확한 것보다 같이 부르는 게 이기는 거라고, 레오가 말했다.', fx:{mood:{leo:3}, moodAll:2}}]},
  {label:'"오늘 기분을 노래로 불러줘요"', out:[{p:1, text:'"어려운 주문이네요. 좋아요."\n\n레오가 창밖을 한 번 보고, 나를 한 번 보고, 즉흥곡을 시작했다. 가사에 오늘 아침 메뉴와 어제 고개의 커브와 내 하품이 들어갔다.\n\n엉망이고 완벽했다. "제목은 \'오늘\'이에요. 내일 부르면 못 알아들을 노래." 일회용 노래는 사치스러웠다.', fx:{mood:{leo:4}, moodAll:2, note:{type:'사건',title:'일회용 노래 「오늘」',body:'내일 부르면 못 알아들을 즉흥곡. 사치스러운 일회용.',links:['레오']}}}]},
 ]},
{id:'talk_leo_05', type:'대화', w:4, once:true, needsComp:'leo',
 title:'레오 — 보리와의 계약',
 text:'"보리랑 저랑 어떻게 만났는지 얘기했던가요?"\n\n레오가 보리(자고 있다)를 보며 물었다.',
 choices:[
  {label:'"안 했어요. 해줘요"', out:[{p:1, text:'"공연하는데 앞에 와서 앉더라고요. 그 공연 관객이 셋이었나, 넷이었나. 아무튼 보리까지 넷. 끝까지 듣고, 끝나니까 가만히 보는 거예요. 그래서 말했죠. \'너 매니저 할래?\'"\n\n"조건은 저녁 반 그릇. 보리가 앞발을 내밀었어요. 계약 성립." 레오가 웃었다. "저 친구는 제 첫 정규 계약이에요. 아직까지 위약 없고요."\n\n자던 보리 꼬리가 잠결에 흔들렸다. 계약 이행 중이라는 뜻으로 접수됐다.', fx:{mood:{leo:4}, note:{type:'인물',title:'정규 계약 1호',body:'조건: 저녁 반 그릇. 앞발 날인. 오랫동안 무위약.',links:['레오','보리']}}}]},
 ]},
{id:'talk_leo_06', type:'대화', w:4, once:true, needsComp:'leo', needBond:['leo',5],
 title:'레오 — 밝음의 정체',
 text:'"레오는 무서운 거 없어요?" 지나가듯 물었는데, 레오의 기타 소리가 잠깐 멎었다.\n\n"…있죠. 많죠."',
 choices:[
  {label:'"근데 왜 맨날 웃어요?"', out:[{p:1, text:'"안 웃으면 티 나잖아요." 레오가 기타 줄을 한 번 훑었다. 끝 음이 떨렸다.\n\n"처음 공연할 때도 그랬어요. 손이 안 멈춰서 그냥 관객한테 웃었거든요. 그랬더니 한 분이 웃어줬어요. 좀 낫더라고요."\n\n줄을 다시 눌렀다. 이번엔 소리가 길게 났다. "대장님도 가끔 웃어줘요. 재미없어도. 아, 너무 재미없으면 말은 해주시고요."\n\n나는 고개를 끄덕였다. 레오는 잠깐 내 쪽을 보고, 멈췄던 노래를 이어 갔다.', fx:{mood:{leo:5}, note:{type:'인물',title:'직업 정신',body:'무서움을 감추려고 웃는다. 첫 공연 때 웃어 준 관객 한 명을 기억하고 있었다.',links:['레오']}}}]},
 ]},
{id:'talk_leo_07', type:'대화', w:4, once:true, needsComp:'leo', needBond:['leo',5],
 title:'레오 — 가사 회의',
 text:'"400km 2절이 막혔어요." 레오가 수첩을 내밀었다. 가사가 절반쯤 쓰이다 멎어 있다.\n\n"대장님이라면 여기 뒤에 뭐라고 쓸 거예요?"',
 choices:[
  {label:'진지하게 한 줄 보탠다', out:[{p:1, text:'오래 고민해서 한 줄을 냈다. 레오가 소리 내어 불러보더니 눈이 커졌다.\n\n"…이거 되는데요? 어? 이거 되는데? 이거 써도 돼요?" "얼마든지요." "그럼 대장님도 이제 공동 작사가예요. 저작권료는 고철로 정산할게요."\n\n내 한 줄이 노래에 박혔다. 세상 어딘가에서 이 노래가 불릴 때마다, 그 한 줄은 내 것이다.', fx:{mood:{leo:5}, note:{type:'사건',title:'공동 작사가',body:'400km 2절에 내 한 줄이 박혔다. 저작권료는 고철 정산 예정.',links:['레오']}}}]},
  {label:'"막힐 땐 쉬어야죠"', out:[{p:1, text:'"오— 그것도 프로의 답이네요." 레오가 수첩을 덮었다.\n\n"쉬는 것도 작사의 일부래요. 아빠가 그랬어요. 잘 쉬는 사람이 잘 만든다고." 레오는 덮은 수첩을 옆에 놓고 손가락을 하나씩 폈다. 나도 잠깐 가사 생각을 접었다.', fx:{mood:{leo:2}, moodAll:1}}]},
 ]},
{id:'talk_leo_08', type:'대화', w:4, once:true, needsComp:'leo', needBond:['leo',12],
 title:'레오 — 아빠',
 text:'레오가 하모니카를 손안에서 굴리다 이야기를 꺼냈다.\n\n"아빠는 트럭 기사였어요. 전국을 돌았죠. 지금 우리처럼."',
 choices:[
  {label:'듣는다', out:[{p:1, text:'"어릴 땐 그게 싫었어요. 맨날 없으니까. 근데 오면 꼭 어디 노래를 배워왔어요. 목포 노래, 강릉 노래. 아니, 강릉이었나 삼척이었나. …아무튼 동해안 어디요. \'노래가 기념품이야\' 그러면서."\n\n"그날, 아빠는 길 위에 있었어요. 어디였는지 몰라요. 그래서 저는…" 레오가 기타 줄을 골랐다. "전국을 돌면서 노래를 모아요. 어딘가에서 아빠가 배운 노래랑 마주칠 것 같아서. 노래는 기념품이니까, 어디선가 남아 있을 거니까."\n\n레오의 지도는 노래로 그려져 있었다.', fx:{mood:{leo:6}, note:{type:'인물',title:'노래가 기념품이야',body:'트럭 기사 아빠의 수집법. 레오는 아빠가 배운 노래와 마주치려고 전국의 노래를 모은다.',links:['레오']}}}]},
 ]},
{id:'talk_leo_09', type:'대화', w:4, once:true, needsComp:'leo', needBond:['leo',12],
 title:'레오 — 무대 공포',
 text:'"고백할 게 있는데요." 레오가 목소리를 낮췄다. "저 사실… 무대 공포증 있어요."\n\n매일 노래하는 사람의 입에서 나온 말이라 잠깐 농담인 줄 알았다.',
 choices:[
  {label:'"근데 어떻게 매일 해요?"', out:[{p:1, text:'"한 사람만 봐요." 레오가 손가락 하나를 폈다.\n\n"백 명 앞이어도, 그 한 명한테 부르는 거라고 생각해요. 오늘은 대장님 봤고요."\n\n"저요? 전 가사 생각하느라…"\n\n"그러니까요. 그 표정 보니까 가사 틀려도 안 들킬 것 같아서."\n\n"…틀렸어요?"\n\n"두 번요. 못 들었죠?" 레오가 기타 케이스를 닫으며 웃었다. 나는 어떤 대목이었나 혼자 되짚어 봤다.', fx:{mood:{leo:5}, note:{type:'인물',title:'한 명에게 부르는 법',body:'무대 공포의 해법: 한 사람에게 부른다고 생각한다. 오늘은 내 쪽을 보며 불렀다고 했다.',links:['레오']}}}]},
 ]},
{id:'talk_leo_10', type:'대화', w:4, once:true, needsComp:'leo', needBond:['leo',20], noFlag:'seoul_open',
 title:'레오 — 3절',
 text:'"결정했어요." 레오가 수첩을 탁 덮으며 선언했다.\n\n"400km 3절은 서울 도착해서 쓸 거예요. 근데 조건이 있어요."',
 choices:[
  {label:'"무슨 조건요?"', out:[{p:1, text:'"3절 첫 줄은 대장님이 써요."\n\n"…제가요? 왜요?"\n\n"제일 앞에서 운전한 사람이 제일 먼저 본 걸 쓰는 게 맞으니까요. 저는 조수석에서만 봤잖아요." 레오가 새끼손가락을 내밀었다. "도착하면. 첫 줄. 약속."\n\n"저 가사 못 쓰는데요."\n\n"한 줄인데요, 뭐. 이상하면 제가 고쳐요. 그게 프로듀서고요."\n\n걸었다. 서울에 가야 할 이유가 또 하나 늘었다. 이번 건 마감이 있는 이유다.', fx:{mood:{leo:6}, note:{type:'사건',title:'3절 첫 줄 계약',body:'서울 도착 시 3절 첫 줄 집필 의무 발생(새끼손가락 날인). 마감 있는 동행 사유.',links:['레오','남산']}}}]},
 ]},

/* ═══════════ v2.4 1:1 대화 — 재이 ═══════════ */
{id:'talk_jy_01', type:'대화', w:4, once:true, needsComp:'jaeyi',
 title:'재이 — 감정 수업',
 text:'"이거 얼마짜리게요?" 재이가 길에서 주운 녹슨 문고리를 내밀었다. "아, 힌트 없어요. 힌트 있으면 재미없으니까."\n\n시험이다.',
 choices:[
  {label:'진지하게 감정해본다', out:[{p:1, text:'"음… 고철 반 덩이?"\n\n"땡. 두 덩이." 재이가 문고리 뒤쪽을 문질러 보였다. "여기 노란 거 보여요? 황동이에요. 겉만 보면 철로 알기 쉬워요."\n\n"그럼 닦아서 파는 게 낫겠네요."\n\n"맞아요. 그건 맞혔어요." 재이가 문고리를 내 손에 다시 놓고 걸레를 찾았다.', fx:{mood:{jaeyi:4}, note:{type:'사건',title:'문고리 감정',body:'겉만 보고 철로 알았던 문고리는 황동이었다. 뒤쪽을 닦아 재질을 확인했다.',links:['재이']}}}]},
  {label:'"모르겠는데요"', out:[{p:1, text:'"뒤집어 봐요. 여기만 닦아도 보여요."\n\n재이가 문고리를 돌려 노란 부분을 짚었다. "황동이에요. 고철 두 덩이쯤. 도금인 걸 금이라고 사는 사람도 있는데, 그러면 그날 장사는 끝이죠." 재이는 천 조각으로 나머지 때를 닦았다.', fx:{mood:{jaeyi:3}}}]},
 ]},
{id:'talk_jy_02', type:'대화', w:4, once:true, needsComp:'jaeyi',
 title:'재이 — 첫 수집품',
 text:'"제 첫 수집품이 뭐게요?" 재이가 퀴즈를 냈다. 힌트: 지금도 갖고 있음.',
 choices:[
  {label:'"열쇠요?"', out:[{p:1, text:'"땡. 열쇠는 수집품이 아니에요." 재이의 목소리가 살짝 낮아졌다가 돌아왔다.\n\n"정답은 병뚜껑. 여섯 살 때 아빠 창고에서 주운 사이다 뚜껑." 재이가 지갑을 뒤졌다. 안쪽 칸, 그 안쪽 칸. "어디 갔— 아, 여기 있다." 납작하게 눌린 별 모양.\n\n"아빠가 그랬어요. 줍는 순간 쓰레기가 물건이 된다고. 제 인생 이론이에요."', fx:{mood:{jaeyi:4}, note:{type:'인물',title:'사이다 뚜껑',body:'여섯 살의 첫 수집품. 줍는 순간 쓰레기가 물건이 된다.',links:['재이']}}}]},
  {label:'"병뚜껑 같은 거요?"', out:[{p:1, text:'"…어떻게 알았어요?" 재이의 동공이 흔들렸다.\n\n"찍었는데요." "소름. 대장님 고물상 하세요. 이 바닥은 촉이 반이거든요."\n\n스카우트 제안을 받았다. 내 대답도 듣기 전에 재이가 병뚜껑 상자를 보여 줬다.', fx:{mood:{jaeyi:4}, moodAll:1}}]},
 ]},
{id:'talk_jy_03', type:'대화', w:4, once:true, needsComp:'jaeyi',
 title:'재이 — 흥정의 기술',
 text:'"다음 정착지에서 제가 흥정하는 거 잘 봐요." 재이가 어깨를 폈다. "오늘 기술 하나 공개할 거니까."',
 choices:[
  {label:'"미리 가르쳐줘요"', out:[{p:1, text:'"첫째, 갖고 싶은 건 세 번째로 물어봐요. 첫 번째로 물으면 값이 두 배 돼요."\n\n"둘째… 둘째 뭐였지. 아, 걸어 나갈 준비. 걸어 나갈 준비가 된 사람이 이겨요. 셋째가 제일 중요한데—" 재이가 뜸을 들이다 씩 웃었다. "정말 좋은 물건이면 흥정하지 마요. 부르는 값 주고 사요. 그 주인이랑은 오래 봐야 하니까."\n\n흥정의 기술 최종장이 흥정 포기라는 게 이 바닥의 깊이다.', fx:{mood:{jaeyi:4}, note:{type:'사건',title:'흥정 3원칙',body:'셋째가 백미: 정말 좋은 물건이면 흥정하지 말 것. 주인과 오래 봐야 하니까.',links:['재이']}}}]},
 ]},
{id:'talk_jy_04', type:'대화', w:4, once:true, needsComp:'jaeyi',
 title:'재이 — 버리는 법',
 text:'재이의 전리품 자루가 터지기 직전이다. 짐칸 정리 얘기가 나온 지 사흘째다.\n\n"버리는 게 제일 어려워요, 이 직업은."',
 choices:[
  {label:'"기준이 있어요?"', out:[{p:1, text:'"안 쓸 거면 빼야죠. 일단은요." 재이가 자루를 열었다.\n\n"이 볼트는 남는 규격. 빼고. 이 숟가락은 그 국숫집 할머니가 준 거라 못 빼요. 이 경첩은… 잠깐만요." 경첩 하나에서 손이 멈췄다. 그래도 자루는 반으로 줄었다.\n\n"경첩은 다음에요. 오늘 이렇게 많이 뺐잖아요."\n\n재이는 바닥의 볼트를 다시 집었다. "이건 저 숟가락 걸 때 쓰면 되겠다."', fx:{mood:{jaeyi:4}, scrap:2, note:{type:'인물',title:'남겨 둔 숟가락',body:'재이는 짐을 반으로 줄이면서도 국숫집 할머니가 준 숟가락은 남겼다.',links:['재이']}}}]},
  {label:'"셋 셀 동안 반으로 줄여 봐요"', out:[{p:1, text:'"셋이요?! 너무해—" 하면서도 재이는 진짜로 반을 줄였다. 프로는 마감에 강하다.\n\n버린 것 중 두 개를 몰래 다시 줍는 것까지가 프로다.', fx:{mood:{jaeyi:2}, scrap:2}}]},
 ]},
{id:'talk_jy_05', type:'대화', w:4, once:true, needsComp:'jaeyi',
 title:'재이 — 선물 고르기',
 text:'"만약에요," 재이가 물었다. "누구한테 선물을 해야 하면, 뭘 고를 거예요?"\n\n질문이 묘하게 구체적이다. 누구 주려고 그러나.',
 choices:[
  {label:'"받는 사람이 자기 돈으론 안 살 물건이요"', out:[{p:1, text:'"아, 그런 거." 재이가 자기 상자를 내려다봤다. "아빠도 그 얘기 했어요. 꼭 필요한 거면 자기가 먼저 사 버린다고."\n\n"그럼 너무 필요한 것만 찾지는 말아야겠네요." 재이는 상자를 열어 물건 두 개를 꺼냈다가 하나를 다시 넣었다. 나는 누구에게 줄 건지 묻지 않았다.', fx:{mood:{jaeyi:4}}}]},
  {label:'"고철이요. 실용적이잖아요"', out:[{p:1, text:'"무겁잖아요!" 재이가 웃었다. "민지 씨한테 줄 거면 좋아하겠네요. 아니, 그럴 거면 쓸 만한 부품으로 주고요." 재이는 자기 상자 안을 다시 들여다봤다.', fx:{mood:{jaeyi:2}, moodAll:1}}]},
 ]},
{id:'talk_jy_06', type:'대화', w:4, once:true, needsComp:'jaeyi', needBond:['jaeyi',5],
 title:'재이 — 도둑과 수집가',
 text:'"저는 고물을 주울 때, 도둑질 같아 보일까 봐 신경 써요." 재이가 문득 진지해졌다.\n\n"도둑이랑 수집가의 차이가 뭘까요. …아니, 진짜 몰라서 묻는 거예요."',
 choices:[
  {label:'"주인이 있는지 없는지요?"', out:[{p:1, text:'"그것도 맞는데, 아빠 답은 달랐어요." 재이가 손가락을 세웠다.\n\n"\'도둑은 값을 보고 가져가고, 수집가는 버려진 걸 안타까워서 데려간다.\' 그래서 저는 물건한테 꼭 물어봐요. 너 버려진 거 맞냐고. …이상해 보여도 제 규칙이에요."\n\n말을 마친 재이는 길가의 녹슨 도시락통 앞에 쪼그려 앉았다. 손대기 전에 주위를 한 바퀴 살폈다.', fx:{mood:{jaeyi:5}, note:{type:'인물',title:'수집가의 윤리',body:'물건에게 먼저 묻는다 — 너 버려진 거 맞냐고. 재이는 손대기 전에 주위를 살핀다.',links:['재이']}}}]},
 ]},
{id:'talk_jy_07', type:'대화', w:4, once:true, needsComp:'jaeyi', needBond:['jaeyi',5],
 title:'재이 — 박물관',
 text:'"꿈이 뭐냐고 물어봐 줘요." 재이가 대놓고 요청했다.\n\n"…꿈이 뭐예요?"\n\n"물어봐 줘서 고마워요. 박물관이요."',
 choices:[
  {label:'"무슨 박물관이요?"', out:[{p:1, text:'"\'보통 물건 박물관\'. 국보 말고요. 밥숟가락, 버스 토큰, 다 쓴 몽당연필… 아, 토큰은 벌써 세 개 있다. 아무튼 그런 것만 모으는 데."\n\n"사라지고 나니까 그런 게 제일 보고 싶더라고요." 재이가 전리품 자루를 두드렸다. "지금은 임시 수장고예요. 발로 차면 관람료 받아요."\n\n마침 굴러다니던 숟가락이 발에 걸렸다. 재이는 바로 손을 내밀었다.', fx:{mood:{jaeyi:5}, note:{type:'소문',title:'보통 물건 박물관',body:'밥숟가락과 버스 토큰을 모으는 박물관. 지금의 임시 수장고는 달구지 안 전리품 자루다.',links:['재이']}}}]},
 ]},
{id:'talk_jy_08', type:'대화', w:4, once:true, needsComp:'jaeyi', needBond:['jaeyi',12],
 title:'재이 — 열쇠',
 text:'재이가 목에 건 열쇠를 만지작거리다가, 처음으로 먼저 말을 꺼냈다.\n\n"창고 말인데요. 아빠 창고."',
 choices:[
  {label:'듣는다', out:[{p:1, text:'"아빠는 고물상이었는데, 창고 하나는 절대 안 팔았어요. \'이건 파는 게 아니라 모으는 창고\'라고. 어릴 땐 몰랐죠. 그날— …그날 이후에 알았어요."\n\n"창고엔… 제 것들이 있어요. 첫 신발, 그림, 상장. 아빠는 저를 수집하고 있던 거예요. 6살부터, 쭉."\n\n재이가 열쇠를 꼭 쥐었다. "김천 가면… 아니에요. 가게 되면 그때 말할게요." 창고의 좌표가 마음속에서 아직 정리 중인 모양이었다.', fx:{mood:{jaeyi:6}, note:{type:'인물',title:'아빠의 수집품',body:'창고에 수집된 것: 재이의 6살부터 전부. 아빠는 딸을 수집하는 수집가였다.',links:['재이']}}}]},
 ]},
{id:'talk_jy_09', type:'대화', w:4, once:true, needsComp:'jaeyi', needBond:['jaeyi',12],
 title:'재이 — 시세 없는 목록',
 text:'"값 없는 물건 목록, 업데이트했어요." 재이가 수첩을 펼쳤다. 정말로 목록이 있다.\n\n1번: 아빠 창고 열쇠. 2번: 사이다 뚜껑. 3번부터가 새로 적힌 것들이다.',
 choices:[
  {label:'"3번이 뭔데요?"', out:[{p:1, text:'"3번, 달구지 조수석 이용권(평생). 4번, 처음 받은 \'정품 인정\' 한마디. 5번, 비 온 날 창문에 남은 발자국…"\n\n"…발자국이요?"\n\n"보리 거요. 앞발. 지름 4센티쯤 되고, 유리에 기름기가 있어서 아직 안 지워졌어요."\n\n목록은 아홉 개까지 늘어 있었다. 전부 이 차에서 생긴 것들이었다.\n\n"문제는 다 안 팔려요. 부자인데 현금이 없네." 재이가 목록을 접어 제일 안쪽 주머니에 넣었다.', fx:{mood:{jaeyi:6}, moodAll:2, note:{type:'사건',title:'시세 없는 목록 3~9번',body:'달구지에서 생긴 아홉 가지가 값 없는 물건 목록에 올랐다.',links:['재이','달구지']}}}]},
 ]},
{id:'talk_jy_10', type:'대화', w:4, once:true, needsComp:'jaeyi', needBond:['jaeyi',20],
 title:'재이 — 감정 의뢰',
 text:'"감정 의뢰 하나 받아주실래요?" 재이가 정색하고 말했다.\n\n"제 눈이요. 이 여행이요. …말이 이상하네. 그러니까, 잘 산 물건인지."',
 choices:[
  {label:'정식으로 감정한다', out:[{p:1, text:'재이의 방식대로 감정해봤다. 녹 밑을 보고, 이야기를 세었다.\n\n"판정. 시세 없음. 사유: 이야기가 너무 많아서 값을 매길 수 없음."\n\n재이는 수첩에 적었다. 「10번. 이 여행. 감정인: 대장님.」 그리고 내 손에 연필을 쥐여줬다.\n\n서명하자 재이가 수첩을 낚아챘다. "됐어요. 이제 반품 안 됩니다."', fx:{mood:{jaeyi:6}, moodAll:2, note:{type:'사건',title:'감정서 10번',body:'이 여행은 이야기가 너무 많아 시세 없음. 감정인 서명까지 끝났다.',links:['재이']}}}]},
 ]},

/* ═══════════ v2.4 1:1 대화 — 은수 ═══════════ */
{id:'talk_es_01', type:'대화', w:4, once:true, needsComp:'eunsu',
 title:'은수 — 헤드폰 반쪽',
 text:'은수가 헤드폰 한쪽을 내밀었다.\n\n"…들어볼래요? 지금 좋은 게 잡혀서."',
 choices:[
  {label:'받아서 낀다', out:[{p:1, text:'잡음 사이로 아주 먼 데서 음악이 흘렀다. 어느 나라 말인지도 모를 노래.\n\n"소리 괜찮아요? 크면 말하고요. …단파예요. 밤엔 전파가 멀리 와요. 지구 반대편일 수도 있어요. 반대편까지는 아닌가. 아무튼 멀어요."\n\n지구 반대편에도 누가 살아서 노래를 튼다. 그 사실을 한쪽 귀로 나눠 들었다. "이래서 제가 밤을 좋아해요." 은수가 말했다.', fx:{mood:{eunsu:4}, note:{type:'사건',title:'한쪽 귀의 지구 반대편',body:'밤 단파로 들은 모르는 나라의 노래. 헤드폰 반쪽의 동맹.',links:['은수']}}}]},
  {label:'"좋은 거면 혼자 들어요"', out:[{p:1, text:'"…좋은 건 나누면 두 배인데." 은수가 아쉬워하며 헤드폰을 도로 꼈다.\n\n대신 내용을 실황 중계해줬다. 중계도 나쁘지 않았지만, 다음엔 그냥 받기로 했다.', fx:{mood:{eunsu:1}}}]},
 ]},
{id:'talk_es_02', type:'대화', w:4, once:true, needsComp:'eunsu',
 title:'은수 — 콜사인',
 text:'"관제할 때는 서로 콜사인으로 불렀어요." 은수가 말했다. "이름보다 정확하니까."\n\n"…우리도 하나씩 정할래요?"',
 choices:[
  {label:'"내 콜사인 정해줘요"', out:[{p:1, text:'은수가 3초 고민했다. 3초 더 고민했다.\n\n"\'델타 원\'. 달구지의 D는 델타. 맨 앞에서 운전하니까 원."\n\n"본인은요?" "…\'노스 스타\'. 북쪽 별. 방향 잡는 데 쓰라고요. 여행용이에요. 원래 쓰던 건— 따로 있는데, 그건 아직요." 관제사다운 작명이었고, 관제사다운 유보였다.\n\n이후로 은수는 가끔 무전 톤으로 말을 건다. "델타 원, 전방에 커브. 감속 권고." 놀이인데, 이상하게 든든한 놀이다.', fx:{mood:{eunsu:4}, flag:'eunsu_callsign_held', note:{type:'사건',title:'델타 원 · 노스 스타',body:'콜사인 교환. 이름보다 정확한 부름. 무전 놀이 개시.',links:['은수']}}}]},
 ]},
{id:'talk_es_03', type:'대화', w:4, once:true, needsComp:'eunsu',
 title:'은수 — 침묵 분류학',
 text:'"침묵에도 종류가 있다고 했잖아요." 은수가 말을 이었다. "관제사는 그걸 구분하는 직업이에요. 무전이 조용한 이유가 평온인지 사고인지."',
 choices:[
  {label:'"지금 이 차의 침묵은요?"', out:[{p:1, text:'은수가 차 안을 한 바퀴 둘러봤다. 각자 제 할 일을 하느라 조용했다.\n\n"…이건 \'교신할 필요가 없는 침묵\'이에요. 제일 좋은 등급." 은수가 헤드폰을 목에 걸었다. "등급표가 따로 있는 건 아니에요. 방금 만들었어요. …관제실에선 한 번도 못 들어본 침묵이라서."\n\n나는 고개만 끄덕였다. 은수도 더 말하지 않았다.', fx:{mood:{eunsu:4}, note:{type:'인물',title:'침묵 분류학',body:'최상급 침묵 = 교신할 필요가 없는 침묵. 관제실엔 없던 등급.',links:['은수']}}}]},
 ]},
{id:'talk_es_04', type:'대화', w:4, once:true, needsComp:'eunsu',
 title:'은수 — 관제 용어',
 text:'"오늘의 관제 용어." 은수가 수업을 열었다. 은수식 스몰토크다.\n\n"\'로저\'는 알아들었다. \'윌코\'는 알아들었고 그대로 하겠다. 차이가 뭘까요?"',
 choices:[
  {label:'"실행 여부요?"', out:[{p:1, text:'"정확해요. 로저는 듣기만 한 거고, 윌코는 하겠다는 약속이에요."\n\n"…어느 쪽이 로저라고요?"\n\n"듣기만 한 쪽이요. 방금 그 질문이 딱 로저였어요." 은수가 드물게 장난스러운 표정을 지었다. "사람들 대답도 다 로저 아니면 윌코예요. \'알았어\'가 로저인 사람이 있고 윌코인 사람이 있죠."\n\n"이 차 사람들은요?" "…전원 윌코." 최고 등급 평가였다.', fx:{mood:{eunsu:4}, moodAll:1, note:{type:'사건',title:'전원 윌코',body:'로저=들었다, 윌코=하겠다. 이 차의 대답은 전부 윌코 등급.',links:['은수']}}}]},
 ]},
{id:'talk_es_05', type:'대화', w:4, once:true, needsComp:'eunsu',
 title:'은수 — 별명의 유래',
 text:'"은수 씨는 어쩌다 관제사가 됐어요?"\n\n"…별을 좋아해서요." 예상 밖의 답이 왔다.',
 choices:[
  {label:'"별이랑 관제가 무슨 상관이에요?"', out:[{p:1, text:'"천문학과 가고 싶었는데 성적이… 그래서 하늘 보는 직업 중에 되는 걸 골랐어요. 아니, \'되는 걸\'은 말이 좀 그런가. 할 수 있는 거요." 은수가 웃었다. "레이더 화면도 밤하늘 비슷해요. 점들이 떠 있고, 저는 그 점들이 무사히 지나가게 지키고."\n\n"이젠 관제탑 아니어도 별 보러 갈 수 있겠네요."\n\n"밤이 맑으면요. 야간수당은 없지만." 은수가 헤드폰을 내려놓았다.', fx:{mood:{eunsu:4}, note:{type:'인물',title:'별 대신 레이더',body:'천문학과 대신 관제탑을 택했던 은수. 별을 좋아해 하늘을 보는 직업을 골랐다고 했다.',links:['은수']}}}]},
 ]},
{id:'talk_es_06', type:'대화', w:4, once:true, needsComp:'eunsu', needBond:['eunsu',5],
 title:'은수 — 죄책감의 방향',
 text:'"가끔… 아니에요." 은수가 말을 접었다가, 다시 폈다. "궁금한 게 있어요. 내가 관제실에 있었으면서 아무것도 몰랐다는 게… 잘못일까요."',
 choices:[
  {label:'"모르게 만든 쪽 잘못이죠"', out:[{p:1, text:'"…그렇게 말해주는 사람은 처음이에요." 은수가 헤드폰을 만지작거렸다.\n\n"다들 관제실에 있었다고 하면 일단 한 발 물러서거든요. 뭔가 알았을 거라고." 은수가 창밖을 봤다. "몰랐어요. 그게 제일 무서운 거예요. 아는 사람이 정말 없었다는 게."\n\n"남산 가면 물어볼 거예요. 너는 우리한테 왜 안 알려줬냐고. …반말로요." 반말이라는 데서 웃어버렸고, 은수도 웃었다.', fx:{mood:{eunsu:5}, note:{type:'인물',title:'반말로 물을 것',body:'"너는 우리한테 왜 안 알려줬냐" — 남산에서 천리안에게 할 질문(반말 예정).',links:['은수','천리안','남산']}}}]},
 ]},
{id:'talk_es_07', type:'대화', w:4, once:true, needsComp:'eunsu', needBond:['eunsu',5],
 title:'은수 — 노이즈 속 음악',
 text:'은수가 녹음기(어디서 구했는지)에 뭔가를 모으고 있다.\n\n"잡음이요. 좋은 잡음만."',
 choices:[
  {label:'"잡음에 좋은 게 있어요?"', out:[{p:1, text:'"있죠. 잠깐만요. 이 앞인데… 지나갔다." 은수가 되감기를 두 번 놓치고 세 번째에 맞췄다. 빗소리 뒤로 희미한 음악이 잡혔다.\n\n"여기요. 사람 목소리 들리죠? 앞에서 말하는 사람 말고, 뒤에서 따라 부르는 사람."\n\n볼륨을 올리자 잡음만 커졌다. 은수는 조금 낮추고 같은 부분을 다시 틀었다. 그제야 한 음 늦게 따라오는 목소리가 들렸다.\n\n"관제실에선 이런 건 다 지웠어요. 지금은 따로 남겨요. 나중에 이것만 이어서 들어 보려고요."\n\n은수는 녹음기 옆에 재생 위치를 적었다. 나는 한 번 더 듣고 나서 헤드폰을 돌려줬다.', fx:{mood:{eunsu:4}, note:{type:'인물',title:'좋은 잡음 수집가',body:'은수가 잡음 뒤에서 노래를 따라 부르는 목소리를 들려줬다. 관제실에서 지우던 소리를 이제는 따로 모은다.',links:['은수']}}}]},
 ]},
{id:'talk_es_08', type:'대화', w:4, once:true, needsComp:'eunsu', needBond:['eunsu',12],
 title:'은수 — 마지막 교신',
 text:'"그날 마지막으로 관제한 비행기, 기억해요." 은수가 묻지 않은 이야기를 시작했다. 이 사람에겐 드문 일이다.',
 choices:[
  {label:'듣는다', out:[{p:1, text:'"제주발 김포행. 착륙 10분 전에 시스템이 넘어갔어요. 마지막으로 제가 한 말이 \'유지하세요, 곧 다시 연결됩니다\'였어요."\n\n"…연결됐어요?"\n\n"몰라요. 아직도." 은수가 헤드폰을 꼭 쥐었다. "그래서 매일 밤 스캔해요. 그 기장 목소리를 아니까. 무전 한 번만 잡히면… 뭐라고 할지는, 아직 못 정했어요."\n\n그 뒤로 은수가 야간 스캔을 시작하면, 아무도 채널을 먼저 돌리지 않았다.', fx:{mood:{eunsu:6}, note:{type:'인물',title:'유지하세요, 곧 다시 연결됩니다',body:'마지막 관제의 마지막 문장. 은수는 지금도 매일 밤 그 비행기의 신호를 찾는다.',links:['은수']}}}]},
 ]},
{id:'talk_es_09', type:'대화', w:4, once:true, needsComp:'eunsu', needBond:['eunsu',12],
 title:'은수 — 신뢰의 형식',
 text:'"비밀 하나 말해도 돼요?" 은수가 물었다. "관제사는 비밀이 생기면 기록으로 남겨요. 직업병이에요. 근데 이건 기록 못 하겠어서."',
 choices:[
  {label:'"들을게요. 기록 안 할게요"', out:[{p:1, text:'"…중계기만 끄면 제 볼일은 끝이라고 생각했어요. 대전에서 차 얻어 탔을 때는요."\n\n"그다음엔 혼자 가려고 했는데. 같이 가도 된다고 하니까… 그냥 좋더라고요. 말할 때는 티 안 냈지만." 은수가 헤드폰을 목에 걸었다. 케이블을 무릎 위에서 풀었다가 다시 감았다.\n\n"그 얘기예요. 계속 같이 가고 싶다고요. 이상, 교신 끝."\n\n"로저."\n\n"수신 확인했으니까 이제 제 자리 좀 남겨 주세요." 웃으면서 헤드폰을 다시 썼다.', fx:{mood:{eunsu:6}, note:{type:'사건',title:'교신 끝',body:'중계기를 끈 뒤 혼자 가려던 은수가, 계속 함께 가고 싶다고 말했다.',links:['은수']}}}]},
 ]},
{id:'talk_es_10', type:'대화', w:4, once:true, needsComp:'eunsu', needBond:['eunsu',20],
 title:'은수 — 남산 이후',
 text:'"남산 끝나면요." 은수가 지도의 서울 위쪽, 빈 데를 짚었다.\n\n"저는 더 올라가 볼까 해요."',
 choices:[
  {label:'"휴전선 너머요?"', out:[{p:1, text:'"북쪽에도 관제탑이 있어요. 거기도 누가 있었을 거고, 거기도 하늘이 있잖아요."\n\n은수가 헤드폰을 고쳐 썼다. "천리안한테 물어보고, 대답을 듣고, 그 다음엔— 아무도 관제 안 하는 하늘을 보러 갈 거예요. 별만 있는 하늘."\n\n"혼자요?"\n\n"…글쎄요. 계획은 혼자였는데, 계획이라는 게 요즘 잘 안 지켜져서." 은수가 나를 봤다. "동행 신청은 선착순이에요." 3막의 예고편 같은 말을, 나는 접수해뒀다.', fx:{mood:{eunsu:6}, note:{type:'소문',title:'별만 있는 하늘',body:'남산 이후의 계획: 더 북쪽, 아무도 관제 안 하는 하늘. 동행 신청 선착순.',links:['은수','남산']}}}]},
 ]},

/* ═══════════ v2.4 1:1 — 보리 ═══════════ */
{id:'talk_bori_01', type:'대화', w:4, once:true, needsDog:true,
 title:'보리 — 산책 협상',
 text:'정차하자마자 보리가 문 앞에 앉았다. 리드줄(폐허에서 주운 것)을 물고.\n\n영업이다.',
 choices:[
  {label:'산책을 나간다', out:[{p:1, text:'차 근처를 짧게 돌았다. 보리의 코가 가는 곳이 코스다. 풀 앞에서 멈추고, 돌 앞에서도 멈추고, 아무것도 없는 곳에서 또 멈췄다.\n\n돌아오는 길에 보리가 막대기를 물어와 발 앞에 놓았다. 선물인지 던지라는 건지 오랫동안 미해결이지만, 오늘은 선물로 접수했다.', fx:{moodAll:3, fatigue:-3, note:{type:'사건',title:'코스 설계자',body:'보리 코가 정하는 산책 코스. 막대기는 선물로 접수(해석 논쟁 오랫동안).',links:['보리']}}}]},
  {label:'"다음에"', out:[{p:1, text:'보리가 리드줄을 문 채로 3초간 나를 보다가, 조용히 제자리로 돌아갔다.\n\n리드줄을 문 옆에 걸어 뒀다. 보리는 그 아래에 엎드렸다. 지금은 나가지 않았다.', fx:{moodAll:2}}]},
 ]},
{id:'talk_bori_02', type:'대화', w:4, once:true, needsDog:true, night:true,
 title:'보리 — 불침번',
 text:'밤. 보리가 내 발치에 엎드려 있다. 자는 줄 알았는데 귀가 계속 움직인다.\n\n눈만 감고 근무 중이다.',
 choices:[
  {label:'"너도 자"', out:[{p:1, text:'머리를 쓰다듬자 보리가 한쪽 눈을 떴다가, 한숨 비슷한 소리를 내고 진짜로 잤다.\n\n교대해줄 사람이 있어야 자는 거였다. 개도, 사람도.\n\n그날 밤 불침번은 내가 섰다. 보리 코 고는 소리를 배경음악으로.', fx:{moodAll:3, note:{type:'사건',title:'교대 근무',body:'보리는 교대자가 있어야 잔다. 그날 배경음악: 개 코골이.',links:['보리']}}}]},
 ]},
{id:'talk_bori_03', type:'대화', w:4, once:true, needsDog:true, needsComp:'leo',
 title:'보리 — 통역',
 text:'보리가 나를 보고 세 번 짖었다. 처음 있는 일이다.\n\n"통역해드릴까요?" 레오가 끼어들었다. "저 보리어 전공이에요."\n\n"전공?"\n\n"경력 여러 해요. 자격증은 없고요."',
 choices:[
  {label:'"통역해줘요"', out:[{p:1, text:'"첫 번째 짖음은 \'너\', 두 번째는 \'냄새가\', 세 번째는 \'맘에 들어\'예요."\n\n"…그걸 어떻게 알아요?" "꼬리 각도요. 45도 이상이면 호의예요."\n\n"45도는 누가 정한 거예요?" "…그건 좀 있다 설명할게요."\n\n설명은 끝내 없었다. 대신 보리 꼬리가 확실히 45도 이상이었다. 공인 통역에 따르면, 나는 오늘 보리에게 정식 승인을 받았다.', fx:{mood:{leo:2}, moodAll:3, note:{type:'사건',title:'보리어 통역 공증',body:'3연속 짖음="너 냄새가 맘에 들어"(레오 역). 꼬리 45도 이상 확인.',links:['보리','레오']}}}]},
 ]},
{id:'talk_bori_04', type:'대화', w:4, once:true, needsDog:true,
 title:'보리 — 조수석 청원',
 text:'보리가 조수석을 노리고 있다. 수첩이 놓인 그 자리를.\n\n한 발을 올렸다가, 나를 보고, 내렸다가, 다시 올렸다.',
 choices:[
  {label:'수첩을 잠깐 옮겨준다', out:[{p:1, text:'보리가 조수석에 올라 창밖으로 코를 내밀었다. 세상 만족한 얼굴로 한동안.\n\n그러더니 제 발로 내려와 뒷자리로 갔다. 확인만 하고 싶었던 모양이다. 저 자리가 어떤 자리인지.\n\n수첩을 도로 놓는데, 왠지 할아버지가 웃은 것 같았다. 개는 좋은 자리를 안다.', fx:{moodAll:3, note:{type:'사건',title:'잠깐 빌린 조수석',body:'보리는 조수석을 둘러본 뒤 제 발로 뒷자리로 돌아갔다. 개는 좋은 자리를 안다.',links:['보리','할아버지']}}}]},
  {label:'"그 자리는 안 돼"', out:[{p:1, text:'보리가 알아들었다는 듯 발을 내리고, 대신 조수석 아래 바닥에 엎드렸다.\n\n타협안: 그 자리 밑. 협상가의 품격이었다.', fx:{moodAll:2}}]},
 ]},

/* ═══════════ v2.5 동료 페어 스토리 — 민지 라인 ═══════════ */
{id:'pair_mj_pss_1', type:'대화', w:4, once:true, needsComp:'minji', needsComp2:'parkss',
 turnSpeakers:['minji','minji','parkss','minji','parkss','minji'],
 title:'민지×박선생 — 맞교환 강습',
 text:'"저기, 거래 하나 해요." 민지가 박 선생 앞에 섰다. "응급처치 가르쳐줘요. 저는 기초 정비 가르쳐드릴게요."\n\n"기술 물물교환이군."\n\n"…네."\n\n"콜. 그래서 나는 뭘 배우는 거였지?"\n\n"정비요, 선생님."',
 choices:[
  {label:'참관한다', out:[{p:1, text:'1교시, 지혈. 민지는 배우는 것도 정비처럼 했다. "압박, 몇 뉴턴이요?"\n\n"…감으로 하는 걸세."\n\n"감을 수치로 주세요."\n\n"수치가 없어. 그, 손끝이 하얘질 때까지— 아니지, 하얘지면 너무 센 거고."\n\n2교시, 타이어. 박 선생은 볼트를 약병 다루듯 조심조심 풀었다. 민지가 옆에서 참다가 말했다. "선생님, 그거 안 부러져요."\n\n"약도 기계도 급하게 다루면 사고야."\n\n"…그건 맞아요."\n\n종강 무렵 둘은 서로를 새로 봤다. "선생님 손, 정비사 손인데요." "이 학생 눈은 약사 눈이고."\n\n민지는 연습에 쓴 붕대를 다시 감았고, 박 선생은 육각 렌치의 크기를 손가락으로 재 봤다. 가르쳐 준 도구를 돌려주면서도 둘 다 한 번 더 들여다봤다.', turnSpeakers:['minji','parkss','minji','parkss','minji','parkss','minji','minji','parkss'], fx:{mood:{minji:3, parkss:3}, note:{type:'사건',title:'기술 물물교환',body:'지혈↔타이어 맞교환 강습. 반쪽짜리 약사 겸 정비사 2명 배출.',links:['민지','박 선생']}}}]},
 ]},
{id:'pair_mj_pss_2', type:'대화', w:4, once:true, needsComp:'minji', needsComp2:'parkss', needBond:['minji',12],
 title:'민지×박선생 — 손 이야기',
 text:'박 선생이 민지 손의 흉터들을 물끄러미 보다가 말했다. "손이 참 애썼네."\n\n"…네?"\n\n"손. 애썼다고."\n\n민지가 손을 감추려다— 그만뒀다.',
 choices:[
  {label:'조용히 듣는다', out:[{p:1, text:'"흉터마다 고친 차가 있어요." 민지가 손등을 폈다. "이건 첫 엔진, 이건 오빠 스쿠터… 아니다, 이건 스쿠터 아니고 그냥 문에 찍힌 거."\n\n"그런데 왜 감췄나."\n\n"…손 더럽다고 보는 사람이 많아서요."\n\n박 선생도 자기 손을 내밀었다. 손가락 끝이 약품에 하얗게 삭아 있었다. "나도 그래. 약국 할 땐 조제를 손으로 했거든. 요오드 한번 만지면 사흘은 안 빠져. 한번은 손님이 거스름돈을 카운터에 안 놓고 바닥에 놨어. 내 손에 닿기 싫어서."\n\n"…그래서요?"\n\n"그래서 뭐. 주웠지."\n\n민지가 박 선생의 손을 보다가 자기 손을 다시 폈다. "약값을 더 받지 그랬어요."\n\n"그럴걸 그랬군."', fx:{mood:{minji:5, parkss:4}, note:{type:'사건',title:'두 사람의 손',body:'민지와 박 선생은 손의 흉터를 감추게 만든 손님 이야기를 나눴다.',links:['민지','박 선생']}}}]},
 ]},
{id:'pair_mj_kw_1', type:'대화', w:4, once:true, needsComp:'minji', needsComp2:'kangwoo',
 title:'민지×강우 — 기어 논쟁',
 text:'"아저씨. 기어 넣는 거, 미션한테 사과해야 돼요."\n\n"……."\n\n"들으셨죠."\n\n"…군용차는 이렇게 몰았다."\n\n"여긴 군대 아니고요. 얘도 군용차 아니고요. 클러치 타이밍이 반 박자 빨라서 싱크로가— 아니, 됐어요. 그냥 반 박자만 늦게요."\n\n"……."\n\n일촉즉발이다.',
 choices:[
  {label:'중재한다', out:[{p:1, text:'"그럼 이렇게 해요. 강우 씨가 민지 방식으로 변속해 보고, 민지는 험한 길에서 강우 씨 라인을 배우고."\n\n"…일주일." 강우가 먼저 기간을 정했다.\n\n"시험이면 기록도 해야죠. 연비랑 변속 소리." 민지가 수첩을 폈다.\n\n"험지 구간은 내가 고른다. 다음 비포장부터."\n\n"그럼 지금 하나만 봐요." 민지가 운전석 옆에 쪼그려 앉아 클러치 페달 유격을 조정했다. "여기서 반 박자. 발 떼는 데까지."\n\n강우가 시동 꺼진 페달을 두 번 밟아 봤다. 세 번째에는 말없이 박자를 맞췄다.\n\n"…해 보겠다."', turnSpeakers:['me','kangwoo','minji','kangwoo','minji','minji','kangwoo'], fx:{mood:{minji:3, kangwoo:3}, van:3, note:{type:'사건',title:'변속 협정',body:'클러치 유격을 조정했다. 강우는 민지식 변속을 일주일 시험하고, 민지는 다음 비포장에서 강우의 주행 요령을 배우기로 했다.',links:['민지','강우']}}}]},
 ]},
{id:'pair_mj_kw_2', type:'대화', w:4, once:true, needsComp:'minji', needsComp2:'kangwoo', needBond:['kangwoo',12], night:true,
 title:'민지×강우 — 오빠와 후임',
 text:'밤 경계. 강우와 민지가 드물게 나란히 앉아 있다.\n\n"아저씨도 찾는 사람 있죠." 민지가 불쑥 물었다. "서울에."\n\n"……."\n\n"없으면 없다고 하셔도 되는데요."\n\n"……있다."',
 choices:[
  {label:'멀리서 지켜본다', out:[{p:1, text:'강우가 군번줄을 꺼내 보였다. 민지는 라디오 주파수를 말했다. 88.9.\n\n"…그걸로 찾나."\n\n"찾는 게 아니라 열어두는 거예요. 켜놓으면 언젠가 걸릴 수도 있으니까. 안 걸려도 켜놓는 거고요."\n\n"……."\n\n"지치지 않냐고 물어보시려는 거죠."\n\n"…그렇다."\n\n"지쳐요." 민지가 하늘을 봤다. "근데 기다리는 걸 그만두면, 그때부터 진짜 잃는 거예요."\n\n강우는 바로 대답하지 않았다. 대답은 두어 박자 늦게 왔다. "…그 말, 빌리겠다."\n\n민지가 뭐라고 대꾸하려다 그만뒀다. 두 사람은 교대 시간까지 그러고 앉아 있었다.', fx:{mood:{minji:5, kangwoo:5}, note:{type:'사건',title:'수색자 동맹',body:'군번줄과 88.9. "기다리는 걸 그만두면 그때부터 진짜 잃는 거다" — 대출된 말.',links:['민지','강우']}}}]},
 ]},
{id:'pair_mj_leo_1', type:'대화', w:4, once:true, needsComp:'minji', needsComp2:'leo',
 title:'민지×레오 — 크레딧 협상',
 text:'"민지야. 400km 앨범 크레딧에 이름 올릴게. \'엔진 튜닝: 민지\'로."\n\n"…크레딧이 뭔데."\n\n"음반 뒤에 누가 뭘 했는지 적는 거야. 엔진 소리도 들어가니까 이름 올려야지."\n\n"앨범도 없으면서."\n\n말은 그렇게 하는데 민지 귀가 빨갛다.',
 choices:[
  {label:'부추긴다', out:[{p:1, text:'"기왕이면 \'사운드 엔지니어\'로 올려줘요. 엔진 소리도 사운드니까." 내가 거들자 레오가 무릎을 쳤다.\n\n"그거다! 그럼 저는 프로듀서 겸 보컬 겸 기타 겸— 아니다, 겸이 너무 많다. 그냥 레오로 할게요, 대장님."\n\n"…뭐 하나만 해."\n\n"민지야, 2번 실린더 소리 그거 리듬 파트로 녹음해도 돼?"\n\n"…실린더한테 물어봐."\n\n레오는 그날 저녁 내내 보닛에 귀를 대고 있었다.', fx:{mood:{minji:3, leo:4}, moodAll:1, note:{type:'사건',title:'실린더 피처링',body:'400km 크레딧: 사운드 엔지니어 민지, 피처링 2번 실린더.',links:['민지','레오','달구지']}}}]},
 ]},
{id:'pair_mj_leo_2', type:'대화', w:4, once:true, needsComp:'minji', needsComp2:'leo', needBond:['leo',12],
 title:'민지×레오 — 오빠 노래',
 text:'레오가 조심스럽게 민지에게 물었다. 레오치고는 조심스럽게.\n\n"민지야. 민규 형은… 어떤 노래 좋아했어?"\n\n차 안이 조용해졌다. 민지가 화낼까 봐. 그런데—',
 choices:[
  {label:'숨죽이고 지켜본다', out:[{p:1, text:'민지가 콧노래를 흥얼거렸다. 처음 듣는 멜로디였다.\n\n"…이거."\n\n"한 번 더."\n\n민지가 다시 불렀다. "맨날 이거 불렀어. 제목도 모르는데, 정비하면서 맨날. 아니 맨날은 아니고, 좀 잘 풀리는 날에만."\n\n레오가 기타로 그 멜로디를 받았다. 처음엔 음을 두 번 놓쳤고, 세 번째에 붙잡았다. 후렴이 생기고, 화음이 생기고— 20분 만에 노래가 됐다.\n\n"제목 뭐로 하지?"\n\n"…\'형 마중 갈 때 부를 노래\'."\n\n민지가 즉답했다. 준비해뒀던 제목처럼. 레오는 아무 말도 안 하고 그 제목을 기타 케이스 안쪽에 적었다.', fx:{mood:{minji:6, leo:5}, note:{type:'사건',title:'형 마중 갈 때 부를 노래',body:'제목 모르던 콧노래가 20분 만에 노래가 됐다. 서울행 재생목록 추가.',links:['민지','레오','민규']}}}]},
 ]},
{id:'pair_mj_jy_1', type:'대화', w:4, once:true, needsComp:'minji', needsComp2:'jaeyi',
 title:'민지×재이 — 합작 사업 구상',
 text:'"민지 씨, 우리 동업해요." 재이가 눈을 빛냈다. "제가 물건 보는 눈, 민지 씨가 고치는 손. 고물 사서 고쳐 파는 거예요."\n\n"…마진은?"\n\n"버너 하나가 고철값 2인데 심지 갈면 3에서 3.5요. 아니다, 심지값 빼면 3.2. 대신 주물 냄비는 8까지 봐요. 무게가— 아, 무게 얘긴 나중에."\n\n민지가 진지하게 받았다. 진지하게 받았다는 게 중요하다.',
 choices:[
  {label:'투자 의향을 밝힌다', out:[{p:1, text:'즉석 사업계획이 발표됐다. 상호 「고쳐드림」(재이 작명), 본점 위치 미정, 초기 자본 고철 30(투자자: 나).\n\n"지분은요?"\n\n"셋이 똑같이요." 민지가 먼저 말했다.\n\n"눈이 손보다 좀 더 받아야 되는데요."\n\n"손이 없으면 눈이 뭘 봐요."\n\n"…그건 그러네요." 재이가 이 초 만에 접었다.\n\n"서울 끝나면 1호점이에요." 재이가 손을 내밀었고 민지가 잡았다. 재이가 「고쳐드림사」로 고쳐 부르자 민지는 벌써 상호를 바꾸냐고 물었다. 이름은 다시 「고쳐드림」이 됐다.', fx:{mood:{minji:3, jaeyi:4}, note:{type:'소문',title:'주식회사 고쳐드림',body:'눈(재이)+손(민지) 합작. 고치고 다시 값을 찾는 가게. 개업은 서울 이후.',links:['민지','재이']}}}]},
 ]},
{id:'pair_mj_jy_2', type:'대화', w:4, once:true, needsComp:'minji', needsComp2:'jaeyi', needBond:['jaeyi',12],
 title:'민지×재이 — 찾을 사람',
 text:'재이가 민지 옆에 붙어 앉더니 낮은 목소리로 말했다.\n\n"민지 씨는 좋겠네요. 오빠가 있어서. …찾을 사람이 있다는 거요."',
 choices:[
  {label:'자리를 비켜준다', out:[{p:1, text:'나중에 민지에게 들은 대화의 결말은 이랬다.\n\n"찾을 사람 없으면 만들면 돼요."\n\n"…네?"\n\n"만들면 된다고요."\n\n"그게 만들어지는 거예요?"\n\n"지금 만들고 있잖아요, 언니."\n\n민지가 재이 이마를 손가락으로 툭 밀었다. "그럼 저는 언니 찾을 사람이에요. 잃어버리면 찾아요."\n\n"찾는 데 비용은—"\n\n"언니."\n\n"…네."\n\n재이가 그날 시세 없는 목록에 한 줄을 더 적었다. 찾을 사람(생김).', fx:{mood:{minji:5, jaeyi:6}, note:{type:'사건',title:'목록 11번',body:'"찾을 사람 없으면 만들면 돼요. 지금 만들고 있잖아요." — 11번: 찾을 사람(생김).',links:['민지','재이']}}}]},
 ]},
{id:'pair_mj_es_1', type:'대화', w:4, once:true, needsComp:'minji', needsComp2:'eunsu',
 title:'민지×은수 — 88.9 부스터',
 text:'은수가 민지의 라디오를 오래 보다가 말했다.\n\n"이거… 수신 감도, 올릴 수 있어요. 안테나 배선만 손보면요."\n\n"얼마나요."\n\n"…확실하지 않아요. 재봐야 알아요." 은수가 말을 고쳤다. "손보면 나아진다는 것까지는 확실하고요."\n\n88.9 얘기라는 걸, 차 안 전원이 알았다.',
 choices:[
  {label:'작업을 돕는다', out:[{p:1, text:'은수가 회로를 그리고 민지가 납땜을 했다. 오간 말은 대부분 "여기요" "거기 말고" "잠깐" 이 셋이었다.\n\n완성 후 첫 시험. 88.9. …여전히 잡음.\n\n"안 됐네요." 은수가 먼저 말했다.\n\n"잡음이 커졌잖아요."\n\n"…그건 그래요."\n\n"수신 범위가 넓어졌다는 거잖아요. 오빠 신호가 오면, 더 먼 데서도 잡힌다는 거잖아요."\n\n은수가 잠깐 계산하는 얼굴을 하더니 끄덕였다. "훨씬 먼 데서도요." 두 사람은 다음에 쉴 때 다시 들어 보기로 하고 주파수를 88.9에 맞춰 뒀다.', fx:{mood:{minji:5, eunsu:5}, note:{type:'사건',title:'커진 잡음',body:'은수가 회로를 그리고 민지가 연결부를 손봤다. 잡음이 커졌다. 다음 휴식 때 88.9를 다시 들어 보기로 했다.',links:['민지','은수','민규']}}}]},
 ]},
{id:'pair_mj_es_2', type:'대화', w:4, once:true, needsComp:'minji', needsComp2:'eunsu', needBond:['eunsu',12],
 title:'민지×은수 — 기다리는 직업',
 text:'"관제사도 결국 기다리는 직업이에요." 은수가 말했다. "신호를. 응답을."\n\n"정비사도요." 민지가 받았다. "부품을. 손님을."\n\n기다림의 프로 둘이 마주 앉았다.',
 choices:[
  {label:'끼어들지 않는다', out:[{p:1, text:'"기다리다 지치면 어떻게 해요?" 은수가 물었다.\n\n"정비해요."\n\n"뭘요?"\n\n"기다리는 대상 말고, 기다리는 나를." 민지가 자기 손을 폈다 쥐었다. "몸 챙기고, 연장 닦고. 신호 오는 날 컨디션 좋게."\n\n은수가 헤드폰 한쪽을 벗었다. 그러고는 수첩을 꺼내 그 말을 받아 적었다. 진짜 수첩에, 진짜로.\n\n"…적으려고요?"\n\n"관제 교본에 없는 문장이라서요." 은수가 적다 말고 한 줄을 지웠다. "\'최상\'이라고 적었는데, 그렇게까지는 안 말씀하셨죠."', fx:{mood:{minji:5, eunsu:5}, note:{type:'사건',title:'기다리는 나를 정비한다',body:'교본에 없는 문장 — 신호 오는 날 최상 컨디션이도록. 수첩에 공식 등재.',links:['민지','은수']}}}]},
 ]},

