      S.items['부품']=(S.items['부품']||0)+1;
      freshHaul+=' · 부품 +1';
    }
  }
  G.advance(status.mins);
  if(S.ended) return true;
  S.fatigue=clamp(S.fatigue+status.fatigue,0,100);
  const localPool=G.nodeEvents?G.nodeEvents(S.at):[];
  const pool = G.eligible('탐색');
  if(status.repeat){
