  };
  if(queued){ markRoadEvent(); G.openEventById(queued); return true; }
  const weight=e=>e.w*(G.eventIsContextual(e)?2.1:1)*G.directorWeight(e);
  const total=pool.reduce((s,e)=>s+weight(e),0); let r=rng()*total;
