G.companionQuestEntries = ()=>{
  if(!S) return [];
  const ledger=G.ensureQuestLedger();
  const ids=new Set(Array.isArray(S.party)?S.party:[]);
  if(S.recruitQ&&S.recruitQ.id) ids.add(S.recruitQ.id);
  return [...ids].map(id=>{
    const comp=D.comps&&D.comps[id];
    if(!comp) return null;
    const state=S.comps&&S.comps[id]||{};
    const recruiting=S.recruitQ&&S.recruitQ.id===id&&!S.party.includes(id);
    const level=Number(state.lvl)||0;
    const storyStage=typeof G.companionStoryStage==='function'?G.companionStoryStage(id):Math.min(level,3);
    const completed=!recruiting&&level>=3&&storyStage>=3;
    const deed=(D.deeds||[]).find(row=>row.comp===id);
    const milestones=D.companionMilestones&&D.companionMilestones[id]||['서로의 생활 방식을 익힌다','과거와 선택을 더 깊이 듣는다','남산까지 가져갈 이야기를 완성한다'];
    const pending=Number(state.pending)||0;
    const targetBond=!completed&&!pending&&D.bondTh?Number(D.bondTh[Math.min(level,2)])||0:0;
    const remaining=Math.max(0,targetBond-(Number(state.bond)||0));
    let next;
    if(completed) next='개인 이야기를 모두 들었다. 남산에서 이 동료의 의견을 들을 수 있다.';
    else if(recruiting){
      const target=S.recruitQ.target&&D.nodes[S.recruitQ.target];
      next=target?`${target.name}에 가서 ${comp.name}가 부탁한 일을 한다.`:'이 사람이 함께 타기 전에 부탁한 일을 한다.';
    }else if(pending) next=`동료 화면에서 Lv.${pending} 특기를 하나 고른다.`;
    else if(remaining>0) next=`야영에서 대화하거나 길 위 사건을 함께 해결해 유대를 ${remaining} 더 올린다.`;
    else if(storyStage<3) next=`정차한 뒤 ${comp.name}에게 말을 걸어 다음 이야기를 듣는다.`;
    else next=deed&&deed.hint?deed.hint:'야영이나 정착지에서 대화를 이어 간다.';
    return {
      id:`companion_${id}`, kind:'companion', status:completed?'completed':'active',
      tracked:ledger.tracked.includes(`companion_${id}`), companion:id,
      eyebrow:recruiting?'동료 미션 · 합류':'동료 미션',
      title:recruiting?`${comp.name}와 함께할 이유`:comp.name,
      phase:recruiting?'합류 조건 진행 중':pending?`새 퍼크 선택 가능 · 유대 ${Number(state.bond)||0}`:`개인 이야기 ${storyStage}/3 · 동료 Lv.${Math.min(level,3)} · 유대 ${Number(state.bond)||0}`,
      why:recruiting?'서로 믿고 같은 차를 탈 수 있는지 확인하는 중이다.':`${comp.name}의 이야기를 끝까지 들으면 남산에서 이 동료의 의견을 들을 수 있다.`,
      next, expected:completed?'남산에서 이 동료의 의견을 들을 수 있다.':'새 대화와 특기가 열리고, 남산에서 이 동료의 의견을 들을 수 있다.',
      steps:milestones.slice(0,3).map((label,index)=>({id:`${id}_${index+1}`,label,state:index<storyStage?'done':index===storyStage?'current':'upcoming'})),
      progress:{have:recruiting?0:storyStage,need:3,label:recruiting?'합류 전':`${storyStage}/3`},
    };
  }).filter(Boolean);
};

G.localQuestEntries = ()=>{
  if(!S) return [];
  const ledger=G.ensureQuestLedger(), rows=[];
  if(S.quest){
    const q=S.quest;
    if(!q.ledgerId) q.ledgerId=`local_${q.kind}_${q.from}_${q.to}_${q.due}`;
    const from=D.nodes[q.from]&&D.nodes[q.from].name||'출발지';
    const to=D.nodes[q.to]&&D.nodes[q.to].name||'목적지';
    const label=typeof G.questLabel==='function'?G.questLabel(q):(q.item||'지역 의뢰');
    let have=S.at===q.to?1:0, need=1, next=`${to}로 이동해 의뢰를 마친다.`;
    if(q.kind==='procure'){
      have=Math.min((S.items&&S.items[q.need.name])||0,q.need.qty); need=q.need.qty;
      next=have>=need?`${from}의 의뢰인에게 물건을 건넨다.`:`${q.need.name} ${need-have}개를 더 구한 뒤 ${from}으로 돌아간다.`;
    }else if(S.at===q.to) next='정착지 게시판에서 물건과 기록을 건네고 이 단계를 마친다.';
    if(!q.noExpiry&&S.day>q.due) next=`${to} 게시판에서 기한이 지난 부탁의 처리 상태를 확인한다.`;
    if(q.story){ have=Math.max(q.story.stage-1,have?q.story.stage:0); need=q.story.total; }
    rows.push({
      id:q.ledgerId, kind:'local', status:'active', tracked:ledger.tracked.includes(q.ledgerId),
      eyebrow:q.story?`연속 미션 · ${q.story.stage}/${q.story.total}`:`${q.kind==='delivery'?'배달':q.kind==='procure'?'조달':'지역'} 미션 · ${from}`, title:label,
      phase:`목적지 ${to} · ${q.noExpiry?'기한 없음':`기한 ${q.due}일차까지 · 넘기면 실패`}`, next,
      expected:q.story?`고철 ${q.reward}를 받고 다음 부탁이 열린다.`:`고철 ${q.reward}를 받는다.`,
      progress:{have,need,label:q.story?`${q.story.stage}/${q.story.total}`:q.kind==='procure'?`${have}/${need}`:(S.at===q.to?'도착':'이동 중')},
    });
  }else if(S.questFollowup){
    const q=S.questFollowup, from=D.nodes[q.from]&&D.nodes[q.from].name||'현재 정착지';
    rows.push({
      id:q.ledgerId,kind:'local',status:'available',tracked:ledger.tracked.includes(q.ledgerId),
      eyebrow:`후속 미션 · ${q.story.stage}/${q.story.total}`,title:q.story.title,
      phase:`${from} 게시판에서 이어짐 · 기한 없음`,next:`${from}의 게시판에서 다음 부탁을 확인하고 계속할지 결정한다.`,
      expected:`이어서 맡으면 ${q.item}을 ${D.nodes[q.to].name}까지 가져간다.`,
      progress:{have:q.story.stage-1,need:q.story.total,label:`${q.story.stage-1}/${q.story.total}`}
    });
  }
  return rows;
};

G.completedQuestEntries = ()=>{
  const ledger=G.ensureQuestLedger();
  if(!ledger) return [];
  return [...ledger.completed,...ledger.mainHistory].slice().reverse().map(row=>({...row,kind:'completed',status:'completed',tracked:false}));
};

G.questLedgerEntries = ()=>{
  if(!S) return [];
  return [G.mainQuestEntry(),...G.companionQuestEntries(),...G.localQuestEntries(),...G.completedQuestEntries()].filter(Boolean);
};

// A goal link describes a preview surface. Only that surface's own controls
// may travel, spend resources, turn in an item, or advance a conversation.
G.questActionPlan = id=>{
  if(!S||G.openingPending()) return null;
  const row=G.questLedgerEntries().find(entry=>entry.id===id);
  if(!row||row.status==='completed'||row.kind==='completed') return null;
  const plan=G.questObjectivePlan(id);
  const target=plan&&plan.target;
  const action=(surface,label,extra={})=>({questId:id,surface,label,target,...extra});
  if(row.kind==='main'){
    const evidence=G.mainEvidenceOpportunity();
    if(!S.driving&&evidence&&S.at===evidence.target)
      return action('local','주변 탐색 보기',{focus:'explore'});
    if(!S.driving&&S.at==='seoul'&&G.seoulReady())
      return S.flags.seoul_open?action('seoul','서울 진입로 보기'):null;
    return action('route','경로 보기');
  }
  if(row.kind==='local'){
    const q=S.quest&&S.quest.ledgerId===id?S.quest:S.questFollowup;
    const needSupplies=q&&q.kind==='procure'&&(Number(S.items&&S.items[q.need.name])||0)<q.need.qty;
    if(!S.driving&&(S.at===target||needSupplies)&&D.nodes[S.at]?.stl)
      return action('market',needSupplies?'물품·게시판 보기':'게시판 보기',{target:S.at});
    return target?action('route','경로 보기'):null;
  }
  if(row.kind==='companion'){
    const rq=S.recruitQ&&S.recruitQ.id===row.companion?S.recruitQ:null;
    if(rq){
      if(S.driving||rq.stage==='road'||(rq.stage!=='ready'&&S.at!==rq.target))
        return action('route','경로 보기');
      const waitsForNight=rq.stage==='follow'&&Number.isFinite(rq.roadDay)&&S.day<=rq.roadDay;
      return action('local',waitsForNight?'야영 준비 보기':'동료의 부탁 보기',{focus:waitsForNight?'camp':'recruitstep'});
    }
    if(S.comps[row.companion]?.pending||S.driving) return action('crew','동료 보기');
    return action('local','야영 준비 보기',{target:S.at,focus:'camp'});
  }
  return null;
};

G.toggleQuestTracking = (id)=>{
  const ledger=G.ensureQuestLedger();
  if(!ledger||id==='main_namsan') return {ok:false,why:'메인 스토리는 항상 표시된다.'};
  const entry=G.questLedgerEntries().find(row=>row.id===id&&row.status!=='completed');
  if(!entry) return {ok:false,why:'이 임무는 추적할 수 없다.'};
  const index=ledger.tracked.indexOf(id);
  if(index>=0) ledger.tracked.splice(index,1);
  else {
    if(ledger.tracked.length>=2) return {ok:false,why:'사이드 미션은 두 개까지만 추적할 수 있다.'};
    ledger.tracked.push(id);
  }
  if(typeof G.save==='function') G.save();
  try{ window.dispatchEvent(new CustomEvent('questtrackingchange',{detail:{id,tracked:index<0}})); }catch(e){}
  return {ok:true,tracked:index<0};
};

G.questLedgerSync = ()=>{
  const ledger=G.ensureQuestLedger();
  if(!ledger) return;
  const active=G.questLedgerEntries().filter(row=>row.kind!=='completed');
  const main=active.find(row=>row.kind==='main');
  const current={};
  for(const row of active) current[row.id]=`${row.status}|${row.phase}|${row.next}|${row.progress&&row.progress.label}`;
  if(!ledger.mainState&&main) ledger.mainState={chapterId:main.chapterId,act:main.act,title:main.title,phase:main.phase,next:main.next,expected:main.expected,progress:main.progress&&main.progress.label};
  if(!Object.keys(ledger.snapshot).length){ ledger.snapshot=current; return; }
  if(main){
    const previous=ledger.mainState;
    const changedChapter=previous&&previous.chapterId!==main.chapterId;
    const changedStep=previous&&(previous.next!==main.next||previous.progress!==(main.progress&&main.progress.label));
    if(changedChapter){
      ledger.mainHistory.push({id:`main_history_${previous.chapterId}_${S.day}_${S.at}`,eyebrow:`메인 스토리 기록 · ${previous.act}`,title:previous.title,phase:`${previous.phase} · ${S.day}일차`,next:'이 장에서 해야 할 일을 마쳤다.',expected:previous.expected,progress:{have:1,need:1,label:'완료'}});
      ledger.mainHistory=ledger.mainHistory.slice(-24);
      ledger.updates.push({id:main.id,kind:'main',title:`${main.act} · ${main.title}`,next:main.next,day:S.day,at:S.at});
    }else if(changedStep) ledger.updates.push({id:main.id,kind:'main',title:`메인 스토리 진행 · ${main.title}`,next:main.next,day:S.day,at:S.at});
    ledger.mainState={chapterId:main.chapterId,act:main.act,title:main.title,phase:main.phase,next:main.next,expected:main.expected,progress:main.progress&&main.progress.label};
  }
  for(const row of active.filter(row=>row.kind!=='main')){
    if(ledger.snapshot[row.id]&&ledger.snapshot[row.id]!==current[row.id]){
      ledger.updates.push({id:row.id,kind:row.kind,title:row.title,next:row.next,day:S.day,at:S.at});
    }else if(!ledger.snapshot[row.id]){
      ledger.updates.push({id:row.id,kind:row.kind,title:`새 임무 · ${row.title}`,next:row.next,day:S.day,at:S.at});
    }
  }
  if(ledger.updates.length>40){const overflow=ledger.updates.length-40;ledger.updates.splice(0,overflow);ledger.seenUpdateCount=Math.max(0,ledger.seenUpdateCount-overflow);}
  ledger.snapshot=current;
  try{ window.dispatchEvent(new CustomEvent('questledgerchange')); }catch(e){}
};

G.questLedgerUpdates = ()=>{
  const ledger=G.ensureQuestLedger();
  return ledger?ledger.updates.slice(ledger.seenUpdateCount):[];
};
G.questUpdateHistory = ()=>{const ledger=G.ensureQuestLedger();return ledger?ledger.updates.slice().reverse():[];};
G.clearQuestLedgerUpdates = ()=>{
  const ledger=G.ensureQuestLedger();
  if(ledger) ledger.seenUpdateCount=ledger.updates.length;
};

if(typeof G.acceptQuest==='function'){
  const acceptQuestBase=G.acceptQuest;
  G.acceptQuest=(q)=>{
    if(q&&!q.ledgerId) q.ledgerId=`local_${q.kind}_${q.from}_${q.to}_${q.due}`;
    return acceptQuestBase(q);
  };
}
if(typeof G.checkQuest==='function'){
  const checkQuestBase=G.checkQuest;
  G.checkQuest=()=>{
    const q=S&&S.quest?{...S.quest,need:S.quest.need?{...S.quest.need}:null}:null;
    const scrapBefore=Number(S&&S.scrap)||0;
    const result=checkQuestBase();
    if(result&&q){
      const ledger=G.ensureQuestLedger();
      const label=typeof G.questLabel==='function'?G.questLabel(q):(q.item||'지역 의뢰');
      ledger.completed.push({
        id:`completed_${q.ledgerId||Date.now()}`, eyebrow:'완료 기록', title:label,
        phase:`${D.nodes[q.from].name} → ${D.nodes[q.to].name} · ${S.day}일차`,
        next:'완료한 지역 의뢰다.', expected:`고철 ${S.scrap-scrapBefore}개를 받았다.`,
        progress:{have:1,need:1,label:'완료'}
      });
      ledger.completed=ledger.completed.slice(-40);
      G.questLedgerSync();
      G.save();
    }
    return result;
  };
}
if(typeof G.save==='function'){
  const saveWithQuestLedger=G.save;
  G.save=(...args)=>{
    if(S){ G.ensureQuestLedger(); G.questLedgerSync(); }
    return saveWithQuestLedger(...args);
  };
}

source.src/04g-engine-evidence.js:
/* A remotely confirmed contact and an earlier personal visit are the same group. */
G.coreLinkedCells = ()=>D.coreLinkedCells(S);
G.pillars = ()=>{
  const done=G.deedsDone(),f=S.flags;
  const relation=done.filter(d=>d.cat==='동료').length;
  const truth=['massacre_known','parent_key_found','uplink_seen'].filter(k=>f[k]).length
    +(D.familyOrderKnown(S)?1:0);
  return {
    관계:{have:Math.max(relation,f.main_testimony_record?3:0),need:D.seoulPillars.관계,hint:'기록 교환소에서 당사자 세 사람의 증언을 확인한다'},
    세계:{have:G.coreLinkedCells().length,need:D.seoulPillars.세계,hint:'수원 외곽 무전 중계소에서 세 거점의 응답을 받는다'},
    진실:{have:Math.max(truth,f.main_command_record?3:0),need:D.seoulPillars.진실,hint:'북부 기록 보관함에서 증언과 명령 원본을 대조한다'},
    유산:{have:done.filter(d=>d.cat==='회수').length+(f.main_testimony_record?1:0),need:D.seoulPillars.유산,hint:'당사자가 맡긴 증언 사본과 부모님의 검증키를 보관한다'}
  };
};
G.pillarUnmet = name=>{const p=G.pillars()[name];return !!p&&p.have<p.need;};
G.parentSplitKnown = ()=>!!(S.flags.parents_split_known||S.flags.parents_routes_traced);
G.mainEvidenceRows = ()=>{
  const f=S.flags,p=G.pillars();
  return [
    {id:'trace',done:!!f.first_order_trace,target:'yangsan',event:'onboarding_first_road'},
    {id:'parents_split',done:G.parentSplitKnown(),target:'gimcheon',event:'parents_diversion_manifest'},
    {id:'parents_work',done:!!f.parents_routes_traced,target:'cheongju',event:'parents_separated_work'},
    {id:'key',done:!!f.parent_key_found,target:'cheongju',event:f.parent_cache_shared?'story_parent_route_shared':f.parent_cache_guarded?'story_parent_route_guarded':f.parent_key_located?'story_personal_cache':!f.parent_principle_found?'story_family_principle':'story_family_key'},
    {id:'witness',done:p.관계.have>=p.관계.need,target:'cheongju',event:'main_transfer_testimony'},
    {id:'command',done:D.familyOrderKnown(S)&&p.진실.have>=p.진실.need,target:'cheonan',event:f.main_testimony_record?'main_command_ledger':'main_command_companion_ledger'},
    {id:'father',done:!!f.father_fate_known,target:'pyeongtaek',event:f.failed_namsan_known?'parents_father_last_log':'history_failed_namsan'},
    {id:'mother',done:!!f.mother_reunited&&!!f.mother_broadcast_ready,target:'suwon',event:f.mother_reunited?'parents_mother_truth':f.parents_recent_signal?'parents_mother_reunion':'history_parents_network'},
    {id:'relay',done:p.세계.have>=p.세계.need,target:'suwon',event:f.main_testimony_record?'main_relay_conference':'main_relay_companion_conference'},
    {id:'records',done:p.유산.have>=p.유산.need,target:'cheongju',event:'main_transfer_testimony'}
  ];
};
G.mainEvidenceChoiceTimes = (id,seen=[])=>{
  if(seen.includes(id)) return [0];
  const event=D.events.find(event=>event.id===id);
  return (event?.choices||[]).flatMap(choice=>(choice.out||[]).flatMap(out=>{
    const time=Number(out.fx?.time)||0;
    return out.fx?.chain?G.mainEvidenceChoiceTimes(out.fx.chain,[...seen,id]).map(next=>time+next):[time];
  }));
};
G.mainEvidenceSourceId = id=>Object.keys(D.mainRecoveryEvents).find(source=>D.mainRecoveryEvents[source]===id)||id;
G.mainEvidenceEntryId = id=>{
  if(id==='es_nightshift'&&S.flags.es_v1194&&!D.eunsuBackdoorDone(S)) return 'es_backdoor';
  if(id==='es_backdoor'&&!S.flags.es_v1194&&!D.eunsuBackdoorDone(S)) return 'es_nightshift';
  // Entry is not completion. Old unchosen key scenes must first play the video;
  // already located/extracted legacy keys retain their earned progress.
  if(G.mainEvidenceSourceId(id)==='story_family_key'&&!S.flags.parent_principle_found
    &&!S.flags.parent_key_located&&!S.flags.parent_key_found){
    return S.at==='suwon'?'main_recovery_story_family_principle':'story_family_principle';
  }
  return id;
};
G.mainEvidenceEventDone = id=>{
  if(['es_nightshift','es_backdoor'].includes(id)) return !!D.eunsuBackdoorDone(S);
  const source=G.mainEvidenceSourceId(id);
  return source==='parents_diversion_manifest'?G.parentSplitKnown():
    source==='story_family_key'?!!(S.flags.parent_key_located||S.flags.parent_key_found):!!S.flags[D.mainEvidenceCompletion[source]];
};
// These are present encounters at the northern exchange, not portable records.
// Total mileage includes southbound detours and cannot stand in for arrival.
G.mainEvidenceLocationReady = id=>{
  if(['es_nightshift','es_backdoor'].includes(id))
    return !!S.flags.es_backdoor_ready&&G.hasComp('eunsu');
  const source=G.mainEvidenceSourceId(id);
  if(['story_bridge_invitation','story_bridge_last_quiet'].includes(source))
    return !S.driving&&S.at==='seoul'&&!S.flags.seoul_open&&G.seoulReady()
      &&!!S.flags[source==='story_bridge_invitation'?'bridge_crew_answer':'bridge_invitation'];
  if(!['history_parents_network','parents_mother_reunion','parents_mother_truth'].includes(source)) return true;
  // The present reunion refers to the father's last stand. Mileage or a stale
  // queued chain must not reveal it before the player has read that evidence.
  return !S.driving&&S.at==='suwon'&&!!S.flags.father_fate_known
    &&(source!=='parents_mother_reunion'||!!S.flags.parents_recent_signal)
    &&(source!=='parents_mother_truth'||!!S.flags.mother_reunited
      ||!!S.flags.parents_recent_signal&&S.used.includes('parents_mother_reunion'));
};
G.resolveMainEvidenceChain = id=>{
  id=G.mainEvidenceEntryId(id);
  if(!G.mainEvidenceLocationReady(id)||G.mainEvidenceEventDone(id)) return null;
  const source=G.mainEvidenceSourceId(id),recovery=D.mainRecoveryEvents[source];
  if(!recovery) return id;
  if(S.at==='suwon') return recovery;
  // A saved northern scene cannot travel with the player. Leave the actual
  // partial flags intact so the next evidence search can resume at its target.
  const row=G.mainEvidenceRows().find(row=>row.event===source);
  return id===source&&S.at===row?.target?source:null;
};
G.mainEvidenceOpportunity = ()=>{
  if(!S||S.flags.story_done||G.openingPending()) return null;
  const row=G.mainEvidenceRows().find(row=>!row.done);
  if(!row) return null;
  // Mileage includes detours: it must not pull still-local chapters north.
  // Recovery is offered at the exchange, or when returning from Seoul.
  const target=S.at==='seoul'||S.at==='suwon'?'suwon':row.target;
  const eventId=target==='suwon'?(D.mainRecoveryEvents[row.event]||row.event):row.event;
  const event=D.events.find(ev=>ev.id===eventId);
  const times=G.mainEvidenceChoiceTimes(eventId);
  const low=Math.min(...times),high=Math.max(...times);
  const cost=high?`열람 준비 30분 + 선택·후속 작업 ${low===high?low:low+'~'+high}분`:'열람 준비 30분';
  return {...row,target,event:eventId,sourceEvent:row.event,cost,hint:`${D.nodes[target].name}에서 ‘주변 탐색’을 눌러 「${event.title}」 기록을 확인한다 (${cost})`};
};
G.mainStoryReady = ()=>!!S&&G.mainEvidenceRows().every(row=>row.done);
G.seoulReady = ()=>G.mainStoryReady();
G.seoulMissing = ()=>{
  const next=G.mainEvidenceOpportunity();
  return next?{pillar:'메인 스토리',have:0,need:1,...next}:
    {pillar:'메인 스토리',have:1,need:1,target:'seoul',hint:'서울로 이동해 남산 진입로를 연다'};
};

G.departureSteps = ()=>{
  if(!S) return [];
  const witnessed=G.pillars?G.pillars().관계.have:0;
  const rows=[
    {id:'family',done:!!S.flags.intro_family_helped,label:'도윤 가족의 이송표를 확인한다',detail:S.flags.intro_family_helped?'버스 난방을 고치며 지금도 가족을 갈라놓는 이송표가 나온다는 사실을 보았다':'도윤 가족의 버스를 살펴보고 이송표를 확인한다'},
    {id:'appeal',done:!!S.flags.intro_appeal_failed,label:'부산에서 이송 명령에 이의를 제기한다',detail:S.flags.intro_appeal_failed?'부산의 원격 절차로는 멈출 수 없고 남산 현장 확인이 필요하다는 답을 받았다':'부산의 원격 민원 창구에서 이송 명령에 이의를 제기한다'},
    {id:'module',done:!!S.flags.intro_module_seen,label:'엄마가 남긴 장치를 확인한다',detail:S.flags.intro_module_seen?'엄마의 회로도와 달구지 계기판 안쪽의 배선이 일치했다':'엄마의 회로도를 달구지 계기판 배선과 비교한다'},
    {id:'trace',done:!!S.flags.first_order_trace,label:'이송 명령의 첫 발신 기록을 찾는다',detail:S.flags.first_order_trace?'부모님의 이송표와 지금의 표가 같은 곳에서 왔다는 사실을 확인했다':'부산을 떠난 첫 구간에서 이송표의 발신 번호가 남은 기록을 찾는다'},
    {id:'parents_split',done:G.parentSplitKnown(),label:'부모님의 다음 차가 갈라진 경로를 확인한다',detail:G.parentSplitKnown()?'아빠는 남산 유지선, 엄마는 중부 기록 정리소로 보내졌음을 확인했다':'남쪽 환승소의 오래된 운행표에서 오지 않은 다음 차를 찾는다'},
    {id:'parents_work',done:!!S.flags.parents_routes_traced,label:'두 곳에서 이어진 부모님의 작업을 확인한다',detail:S.flags.parents_routes_traced?'아빠의 분리 절차와 엄마의 증언 묶음이 같은 번호로 오갔다':'서로 다른 이송선에 갇힌 뒤 부모님이 남긴 기록을 대조한다'},
    {id:'key',done:!!S.flags.parent_key_found,label:'부모님의 인간 확인 검증키를 꺼낸다',detail:S.flags.parent_key_found?'빠진 설명서 두 장을 찾아 검증키를 안전하게 꺼냈다':'계기판에서 검증키를 떼려면 빠진 설명서 두 장이 필요하다'},
    {id:'witness',done:witnessed>=D.seoulPillars.관계,label:'같은 이송표를 받은 사람들의 이야기를 모은다',detail:witnessed>=D.seoulPillars.관계?'이송을 겪은 사람들이 확인한 증언을 보관했다':`같은 이송표를 받은 사람들의 이야기를 모은다 · ${witnessed}/${D.seoulPillars.관계}`},
    {id:'command',done:D.familyOrderKnown(S)&&!G.pillarUnmet('진실'),label:'증언과 명령 원본을 대조한다',detail:'발신 번호·사람의 확인 누락·상위 명령선을 기록 원본과 대조한다'},
    {id:'father',done:!!S.flags.father_fate_known,label:'아빠의 마지막 남산 기록을 확인한다',detail:S.flags.father_fate_known?'아빠는 의료와 급수 회선을 지키다 남산에서 사망했다':'실패한 남산 진입에서 끝난 정비 번호의 뒤를 확인한다'},
    {id:'mother',done:!!S.flags.mother_reunited&&!!S.flags.mother_broadcast_ready,label:'엄마의 최근 신호를 따라간다',detail:S.flags.mother_reunited?(S.flags.mother_broadcast_ready?'수원 외곽 무전 중계소에서 엄마와 재회했고 송출 지원을 약속받았다':'수원 외곽 무전 중계소에서 엄마와 재회했다. 아직 이야기를 더 들어야 한다'):'북부 연대망을 따라 며칠 전까지 이어진 무전 표식을 찾는다'},
    {id:'relay',done:G.pillars().세계.have>=D.seoulPillars.세계,label:'남산 진입과 연락을 맡을 거점의 응답을 받는다',detail:'수원 외곽 무전 중계소에서 진입로와 송신 순서를 확인한다'},
    {id:'records',done:!G.pillarUnmet('유산'),label:'남산에 가져갈 실물 기록을 보관한다',detail:'검증키와 당사자의 증언 사본, 또는 길에서 맡은 기록을 챙긴다'},
    {id:'seoul',done:!!S.flags.story_done,label:'남산 코어에서 강제 이송 명령을 끊는다',detail:S.flags.story_done?'제7 잔류구역을 향하던 강제 이송을 끝냈다':'필요한 기록과 사람을 모은 뒤 남산 코어에서 명령을 멈춘다. 날짜 제한은 없다'}
  ];
  const next=G.mainEvidenceOpportunity();
  const evidence=G.mainEvidenceRows();
  return rows.map(row=>{
    const fact=evidence.find(item=>item.id===row.id);
    return {...row,...(fact?{done:fact.done}:{}),...(!row.done&&next&&row.id===next.id?{detail:next.hint}:{})};
  });
};

