    if(!node.classList.contains('on')){
      node._returnFocus=document.activeElement;
      const cue={'ovl-status':'bag','ovl-journal':'journal','ovl-map':'map','ovl-menu':'menu'}[node.id];
      if(cue) AMBI.action(cue);
