  /* Desktop rail repeats existing journey state, without new mechanics. */
  function renderDeskRail(){
    const rail=$('#desk-rail');
    if(!rail) return;
    if(!S||screen!=='game'||window.innerWidth<1200){ rail.hidden=true; return; }
    rail.hidden=false;
