    const label=lat<35.4?'남해안'
      :lat<36?'영남 내륙'
        :lat<36.45?'중부 내륙'
          :lat<36.85?'충청권'
            :lat<37.2?'경기 남부':'수도권';
    return {label,route:`${from.name||'현재 위치'} → ${to.name||'다음 목적지'}`};
  }
